window.__D("text/torat-chaim/c016",{"p":[[2300540526,"העצמו' ששם מקבלים גם אוה\"ע כו', שזהו מצד בחי' ההסתלקו' בבחי' רצוא בעצמו' ההתנשאות דקמי' כולא כלא ממש כו'. אמנם בזה עצמו גם בהיותם בגלות מצרים הובדלו ישראל מאוה\"ע, שגם בבחי' רוממו' דעצמו' ממש ישראל הן עלו במחשבה<sup data-n=\"2782\">212</sup> הפנימי' ועצמו' כמ\"ש יבחר לנו את נחלתינו<sup data-n=\"2783\">213</sup> כו', ולא ישרה שכינתו רק בישראל לבד כמ\"ש ונפלינו כו'. וזהו הרבותא יתירה שא' או הנסה אלקי'<sup data-n=\"2784\">214</sup> לקחת לו גוי מקרב גוי כו', שנבדלו ישראל להיות מיוחדי' לשפע הפנימי' ועצמו' גם בהיותם בגלות מצרים שהרי נגלה עליהם שם מלך מלכי<sup data-n=\"2785\">215</sup> כו', ונתייחדו המה דוקא לקבלת התורה פב\"פ מאנכי מי שאנכי כו' ולא עם אחר זולתם, וכמו ששלח לפרעה ע\"י משה שלח את בני ויעבדני<sup data-n=\"2786\">216</sup> בני בכורי ישראל<sup data-n=\"2787\">217</sup> כו' וד\"ל. וזהו מי כה' אלקינו<sup data-n=\"2788\">218</sup> המגביהי לשבת המשפילי לראות<sup data-n=\"2789\">219</sup> בשמים ובארץ כו' מקימי מעפר דל<sup data-n=\"2790\">220</sup> כו', ולכאורה מה שייכות יש למ\"ש מקימי למ\"ש תחלה המגביהי המשפילי כו'. אך הענין הוא דמקימי מעפר קאי ארישא דקרא שא' מי כה' אלקינו דוקא שמיוחד לעמו ישראל דוקא להיות אלקינו, וההוראה לזה הוא כאשר מגביהי לשבת בבחי' הרוממו' בעצמותו ממש, ואע\"פ שמגביהי לשבת למעלה מעלה מ\"מ כשמשפיל א\"ע ביריד' והשתלשלו' למטה בשמים וארץ אע\"פ שהכל שוין עכ\"ז לא ישרה שכינתו רק בישראל. וז\"ש מקימי מעפר דל שהוא השכינה<sup data-n=\"2791\">221</sup> שבגלות, כי גם בגלות שעולה הוא ית' ברוממו' דעצמו' כמ\"ש המגביהי לשבת כו' (אלכה אשובה<sup data-n=\"2792\">222</sup> אל מקומי ממש), נבחרו שם דוקא ישראל לעם סגולתו<sup data-n=\"2793\">223</sup> כמ\"ש כי הוא עשנו<sup data-n=\"2794\">224</sup> ולא<sup data-n=\"2795\">225</sup> אנחנו עמו וצאן מרעיתו כו' יעקב חבל נחלתו לפי שחלק הוי' עמו<sup data-n=\"2796\">226</sup> ממש כו וכמו שאו' הבוחר בעמ\"י<sup data-n=\"2797\">227</sup> כו'. וזהו שבמ\"ת דוקא ירדה שנאה לאוה\"ע שמפני זה נק' סיני<sup data-n=\"2798\">228</sup> כידוע, דמשמע שקודם לכן לא הי' שנאה לאוה\"ע כלל שהיו הכל שוין מצד בחי' הרוממו' כנ\"ל, ואמנם במ\"ת גם בבחי' הרוממו' דעצמו' ממש נבדלו ישראל לקבלת התו' פב\"פ וממילא ירד[ה] שנאה לאוה\"ע וד\"ל.\n<span data-k=\"pg\">188</span> ּ<b>ובכ\"ז</b><sup data-n=\"2799\">229</sup> יתורץ טעם גזירת גלות מצרים למה הוצרכו להיות בגלות דוקא תחת שר של מצרים כו', ואם בשביל שיהי' להם עלי' אח\"כ שזה תלוי בירידה ושפלות ויסורים",[["2782","212","<b>ישראל הן </b>[ב: ליתא]<b> עלו במחשבה</b>: נסמן לעיל פ' שמות לב, ב."],["2783","213","<b>יבחר לנו את נחלתינו</b>: תהלים מז, ה."],["2784","214","<b>או הנסה אלקי'</b>: ואתחנן ד, לד [בדילוג]. ראה גם לקמן פ' בא קכד, ב."],["2785","215","<b>נגלה עליהם. . מלכי</b>: הגש\"פ פיסקא מצה זו."],["2786","216","<b>שלח את בני ויעבדני</b>: שמות ד, כג."],["2787","217","<b>בני בכורי ישראל</b>: שמות שם, כב."],["2788","218","<b>מי כה' אלקינו</b>: תהלים קיג, ה."],["2789","219","<b>המשפילי לראות</b>: תהלים שם, ו."],["2790","220","<b>מקימי מעפר דל</b>: שם קיג, ז."],["2791","221","<b>דל שהוא השכינה</b>: ראה גם לקמן פ' ויקהל תכג, ד. מאמרי אדה\"א נ\"ך ע' שנו. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670236\" data-slug=\"torat-chaim\" data-id=\"2300670236\">תו\"ח לך פג, ב</a>."],["2792","222","<b>אלכה אשובה</b>: נסמן לעיל לט, א."],["2793","223","<b>ישראל לעם סגולתו</b>: ע\"פ תהלים קלה, ד."],["2794","224","<b>כי הוא עשנו</b>: תהלים ק, ג [בדילוג]."],["2795","225","<b>ולא</b>: ה: ולו."],["2796","226","<b>יעקב. . שחלק הוי' עמו</b>: האזינו לב, ט."],["2797","227","<b>הבוחר בעמ\"י </b>[ בעמו ישראל]: נוסח ברכת — אהבת עולם — ק\"ש."],["2798","228","<b>שנאה לאוה\"ע. . סיני</b>: שבת פט, סע\"א."],["2799","229","<b>ובכ\"ז</b>: ב: ומכ\"ז."]]],[2300540544,"שמקודם כמ\"ש ג' דברים באים כו', הרי הי' יכול להיות זה בלא גלות כו'. אך הענין הוא כנ\"ל בענין רם על כל גוים כו', שאצל הגוים הוא בבחי' הרוממות והתנשאו' שבעצמותו ממש בבחי' המקיף העליון ביותר כנ\"ל, ששם אין הפרש בין אור לחשך וקדש וחול ויכולים הכל לקבל בשוה כו' (שאין צדקת הצדיק פועל שם בחי' תוס' אור ולא רשעת הרשע פועל גרעון האור להיותו מובדל ומרומם מכל ההשתלשלו' כנ\"ל, ולכך איוב הגם שהי' צדיק גמור וירא אלקים וסר מרע<sup data-n=\"2800\">230</sup> שאין כמוהו א' אם צדקת מה תתן לו כו' לפי שהי' מאוה\"ע שמקבלים מבחי' המקיף דרוממו' דשם דוקא אם צדקת מה תתן לו להוסיף אור ואם רבו פשעיך מה תעשה לו לגרוע האור כו' וד\"ל). אבל כשירד ה' על ה\"ס בבחי' האר' אור פנימי ועצמו' לישראל לבדם וא' אנכי ה' אלקיך<sup data-n=\"2801\">231</sup> דוקא כו', הרי ירד אור זה מבחי' הרוממו' דעצמות ממש בא' אנכי ממש ומשם דוקא הובדלו ישראל בבחי' הפנימי' ועצמו' מפני שהבדיל שם דוקא בין קדש לחול ובין אור לחשך ובין ישראל לעמים כנ\"ל להיות אנכי ה' אלקיך דוקא וירד[ה] שנא[ה] כו' כנ\"ל, אז עיקר ההבדלה אשר נבדלו ישראל בזה זהו במה שקיבלו תו\"מ דוקא בסור מרע ועש\"ט ברמ\"ח מ\"ע ושס\"ה ל\"ת שכלולים באנכי ולא יהי' לך, שיהי' בחי' הטוב שלהם במצות מעשיות פועל למעלה בחי' תוס' אור גדול מעצמות הא\"ס באצי', ולהיפך מל\"ת יהי' גרעון האור באו\"כ כידוע במ\"ש הפושעים בי בגופא דמלכא<sup data-n=\"2802\">232</sup> כו', שזהו היפך גמור ממ\"ש אם צדקת מה תתן לו שאינו אלא באוה\"ע דוקא לפי שהפרידן מיחודו<sup data-n=\"2803\">233</sup> העצמי שבתו\"מ ואינם מקבלים רק מחיצוני' דמקיף העליון מרחוק דוקא ולא מקרוב כלל כמ\"ש רם על כו' וד\"ל).\n<b>וזהו</b> הטעם שהיו ישראל בגלות מצרים תחלה קודם מ\"ת דוקא, לפי שבכדי שיובדלו ישראל למעלה בבחי' הרוממות דעצמו' א\"ס בבחי' הפנימי' ועצמו' בקבלת תו\"מ שהוא בחי' המשכ' הפנימי' דשם הוי' העצמי שלא נודע גם לאבות כלל, היו צריכים להיות תחלה בגלות מצרים שיהיו משועבדים תחת שר של מצרים וישלוט עליהם שעי\"ז יהיו גם המה בבחי' ההסתלקו' למעלה לקבל מבחי' הרוממו' דמקיף העליון שע\"ז א' רם על כל גוים כו', שזהו דוקא בשעת ממשלת שר של מצרים שיכול לומר לי יאורי<sup data-n=\"2804\">234</sup> כו', וכמ\"ש מי הוי' אשר אשמע בקולו<sup data-n=\"2805\">235</sup> להיותו מקבל מבחי' מקיף שלמעלה מהשתלשלו' דשם הוי' (כמבואר בפ' שמות באריכות<sup data-n=\"2806\">236</sup> ) שז\"ש המגביהי לשבת כו' כנ\"ל. אך במה ששיעבד פרעה בישראל בחומר ובלבינים עד שעלה שוועתם כו',",[["2800","230","<b>וירא אלקים וסר מרע</b>: איוב א, א."],["2801","231","<b>אנכי ה' אלקיך</b>: יתרו כ, ב."],["2802","232","<b>הפושעים בי בגופא דמלכא</b>: נסמן לעיל ו, ב."],["2803","233","<b>שהפרידן מיחודו</b>: ראה זהר יתרו פז, א. לקמן פ' תשא שפב, א. וש\"נ."],["2804","234","<b>שר. . לי יאורי</b>: נסמן לעיל פ' שמות ל, ג."],["2805","235","<b>מי הוי' אשר אשמע בקולו</b>: שמות ה, ב."],["2806","236","<b>בפ' שמות באריכות</b>: לע\"ע לא נתברר לאיזה מאמר הכוונה. ראה לעיל פ' שמות כד, ג ואילך [והוא דרוש אדה\"ז משנת תקס\"ה]. ל, ג ואילך [והוא משנת תקפ\"ב-תקפ\"ד]."]]],[2300540561,"זה הי' התועלת שיהיו ישראל נבדלים למעלה דוקא ברוממות דעצמו' להיות בבחי' פנימי' ועצמו' לקבלת התורה כנ\"ל (וכמ\"ש הנסה אלקי' כו' [לקחת לו] גוי מקרב גוי להבדיל ישראל ממצרים פנימי' מחיצוני' במקום הגבוה ונעלה כזה שהוא רוממות דמקיף העליון ששם הכל שוין ממש עד שביקש משה שלא ישרה כו' כנ\"ל). וא\"כ כדי שיוכלו ישראל לבוא למדרגה גבוה כזאת שיומשך להם מפנימי' ועצמו' דא\"ס בתו\"מ במ\"ת הי' צריך ב' דברים, א' <span data-k=\"pg\">צד</span> ּ שיהיו בגלות מצרים תחלה וגם יהי' בהם בחי' הרצוא והסתלקות ביסורים דשעבוד בחו\"ל שעי\"ז יגיעו לעלי' גדולה כזאת במ\"ת שהוא בחי' השוב בתו\"מ, שבא ממקום הגבוה ביותר שהוא דוקא לפ\"ע בחי' הרצוא והסתלקות דכנ\"י בעב\"ק שלהם שמררו את חייהם כו' ובגלות מצרים דוקא מטעם הנ\"ל וד\"ל. וזהו שאז נא' עת אשר שלט האדם<sup data-n=\"2807\">237</sup> באדם לרע לו, ששליטה זאת באדם דקדושה הוא העושה הבדלה הפנימי' למעלה מעלה בעצם הרוממות כנ\"ל, שעי\"ז יובדל בחי' החיצוני' לגמרי גם למעלה ברוממו' דמקיף העליון עד שיפרידם גם למטה מיניקתם מסט' דקדושה ויהי' הבדלה גמורה גם למטה בין קדש לחול כו'. וזהו שיהי' לרע לו כו' כמו שהי' במצרים בהבדלה גם למטה בחיצוני' בי' מכות ובקי\"ס כו', ואשר הוציאו כל הטוב שהי' גנוז במצרים כמ\"ש וינצלו את מצרים<sup data-n=\"2808\">238</sup> כו'. וכך הוא בכל גלות שישראל משועבדים בלחץ ודחק בתכלית יותר מהכל כו' שע\"ז א' עת אשר שלט האדם באדם כו' (וזהו שא' מי כמוך באלים, אין כמוך באלמים<sup data-n=\"2809\">239</sup> כו', והן הן גבורותיו<sup data-n=\"2810\">240</sup> כו' (אע\"פ שהגלות נק' שינה<sup data-n=\"2811\">241</sup> שזהו בחי' הסתלקות המוחי' כו' דאסתלק לעילא לעילא ברוממות העצמו' כנ\"ל, עכ\"ז א' דומה דודי לצבי<sup data-n=\"2812\">242</sup> כמו צבי ישן בעינו א'<sup data-n=\"2813\">243</sup> וניעור בעין א' וכתיב לא ינום ולא יישן<sup data-n=\"2814\">244</sup> כו' (וזהו מי כה' אלקינו דוקא כשמגביהי לשבת כו' ששם הוא למעלה מן המצות כמ\"ש אם צדקת כו' וכמ\"ש זכרנו את הדגה כו' חנם בלא מצות<sup data-n=\"2815\">245</sup>, אמנם שם דוקא הוא נק' ה' אלקינו דוקא כשמשפילי לראות שמקים מעפר דל כו', כמ\"ש ליעקב אנכי ארד<sup data-n=\"2816\">246</sup> עמך מצרימה ואנכי אעלך במ\"ת גם עלה בא\"י<sup data-n=\"2817\">247</sup> ועוה\"ב<sup data-n=\"2818\">248</sup> וד\"ל.\n<b>וזהו</b> ענין התשובה על שאלת משה למה הרעות לעם הזה כו' כמ\"ש וארא אל אברהם כו' באל שדי ושמי הוי' לא נודעתי להם כו', דהנה מבואר מכל הנ\"ל דשרש התו\"מ למעלה הוא בפנימיות ועצמיות דא\"ס ממש שנק' מצותי כו', וזהו ושמי ה' ממש שלא נודעתי להם לאבות (רק ברוחניות דמצות כמו שהן באצי' לבד ולא כמו שהן במהו\"ע ממש), וע\"כ כדי שיוכלו",[["2807","237","<b>עת אשר שלט האדם</b>: נסמן לעיל פ' שמות ל, ד."],["2808","238","<b>וינצלו את מצרים</b>: נסמן לעיל לו, ג."],["2809","239","<b>מי כמוך באלים. . באלמים</b>: בשלח טו, יא. נסמן לעיל יט, ג."],["2810","240","<b>והן הן גבורותיו</b>: נסמן לעיל כא, ג."],["2811","241","<b>שהגלות נק' שינה</b>: נסמן לעיל כה, א."],["2812","242","<b>דומה דודי לצבי</b>: שה\"ש ה, ט."],["2813","243","<b><a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670514\" data-slug=\"torat-chaim\" data-id=\"2300670514\">צבי ישן בעינו א</a>'</b>: ראה שהש\"ר ספ\"ח. מאמרי אדה\"א נ\"ך ע' תג. וש\"נ. תו\"ח וירא קיח, ג ובהערה 19."],["2814","244","<b>לא ינום ולא יישן</b>: תהלים קכא, ד."],["2815","245","<b>זכרנו. . חנם בלא מצות</b>: נסמן לעיל כו, ד."],["2816","246","<b>אנכי ארד</b>: ויגש מו, ד. ראה לקמן פו, ב."],["2817","247","<b>אעלך במ\"ת גם עלה בא\"י</b>: ראה גם מאמרי אדה\"א שמות ח\"א ע' פד. וש\"נ. במדבר ח\"ה ע' א'תתנג."],["2818","248","<b>גם עלה. . ועוה\"ב</b>: נסמן לעיל פ' שמות ו, ד הערה 296."]]],[2300540577,"בנ\"י לקבל התו\"מ פב\"פ ממדרגה גבוה מאד כזו הי' בהכרח שיהי' בהם בחי' הרצוא וההסתלקו' למעלה בפנימי' ועצמות ממש, שזהו לפ\"ע ממש להיות אח\"כ בחי' השוב כזה בתו\"מ שהן ג\"כ מבחי' הפנימי' ועצמו' דוקא (והוא ע\"י שהיו בגלות מצרים דוקא שהוא שליט' מצרים עליהם שאז נא' רם על כל גוים כו' לפי שמגביהי לשבת כו' מטעם הנ\"ל). ומטעם זה הי' משך זמן הגלות במדה ומשקל זמן רב כזה רד\"ו שנה (ועיקר המרירות לא הי' רק פ\"ו שנה [כ]ימי מרים<sup data-n=\"2819\">249</sup> שהיתה בת פ\"ו שנה ביצ\"מ כידוע, וזהו גימט' דאלקים<sup data-n=\"2820\">250</sup> שהוא בחי' הדין<sup data-n=\"2821\">251</sup> וצמצום שנמתק בזמן זה כמ\"ש ותעל שועתם כו' וידע אלקים כו' (כמ\"ש ע\"פ ואת גביעי גביע הכסף<sup data-n=\"2822\">252</sup> כו' באריכות), שזה הי' צריך להיות בבחי' הרצוא והסתלקות כדי להיות מזה בחי' השוב אח\"כ לפ\"ע זה במ\"ת כנ\"ל וד\"ל. וזהו שא' ושמי הוי' לא נודעתי להם דהיינו תו\"מ בגשמיות שהן גילוי שם הוי' העצמי' ופנימי' ממש ע\"כ הי' הגלות משך זמן כזה כדי שיקבלו בעלי' הגדולה כזאת במ\"ת בגילוי דשם הוי' זה כו', וזאת היא התשובה על שאלתך למה הרעות לעם הזה כו' (דמשמע דשאלת משה הי' על עיקר גזירת הגלות).\n<b>אך</b> עדיין תשובה זאת אינה <span data-k=\"pg\">190</span> ּ לשלימותה על טענת משה למה הרעות כו', דאין זו תשובה רק על העבר שהיו ישראל במצרים עד כה, אבל מה שהי' משה טוען על להבא בא' ומאז באתי לדבר אל פרעה<sup data-n=\"2823\">253</sup> כו' והצל לא הצלת את עמך כו' לכאורה לא השיבו עדיין. אך הנה ע\"ז השיבו ה' עתה תראה כו' כי ביד חזקה כו', ולמה לפי שהגיע לזמן של הגלות ושעבוד שהוא רד\"ו שנה כפי הצריך שיהי' ראויי' לקבלת התורה פב\"פ כנ\"ל. ועוד א' וגם הקימותי<sup data-n=\"2824\">254</sup> את בריתי אתם לתת להם את ארץ מגוריהם כו', פי' דגם [ש]שמי הוי' לא נודעתי להם בתו\"מ אבל א\"י נתן להם בכריתות ברית, ועיקר קיום התו\"מ צ\"ל בא\"י דוקא שהוא למעלה ממ\"ת. וז\"ש וגם [אני] שמעתי<sup data-n=\"2825\">255</sup> את נאקת בנ\"י אשר מצרים מעבידים אותם ואזכור את בריתי הזה לתת להם א\"י, שמצד היסורי' בגלות דוקא זכו גם לא\"י ע\"כ אזכור את בריתי להאבות לתת להם כו'. ולזאת בטלה טענת משה על להבא שבודאי אביאם גם לא\"י להקים הברית לאבות כו'. וז\"ש וגם אני שמעתי כו' דגם בשביל א\"י היו מוכרחי' להיות בשעבוד הגלות יותר מבשביל מ\"ת, אע\"פ שכבר כרת ברית לאבות הוא מטעם שא' אח\"כ לכן אמור לבנ\"י<sup data-n=\"2826\">256</sup> אני הוי' כו' עד ולקחתי אתכם לי לעם<sup data-n=\"2827\">257</sup> והייתי לכם לאלקי' כו', דפי' לכן כולל ג' הטעמים שקדם א' וארא כו' ושמי הוי' לא כו', והב' וגם הקימותי",[["2819","249","<b>המרירות. . פ\"ו שנה [כ]ימי מרים</b>: ראה תנחומא — באבער — בא ז. מאמרי אדה\"א בראשית ע' רעט. וש\"נ. וראה לעיל פ' שמות א, ג הערה 41."],["2820","250","<b>פ\"ו. . גימט' דאלקים</b>: ע\"ח (שער המוחין) ש\"כ, פ\"א."],["2821","251","<b>דאלקים. . בחי' הדין</b>: ראה רש\"י בראשית א, א. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"א לע' שלז."],["2822","252","<b>ע\"פ ואת גביעי גביע הכסף</b>: ויגש מד, ב. ראה מאמרי אדה\"ז על פרשיות התורה ח\"א בהוספות [קה\"ת תשמ\"ט] ס\"ע 22 ואילך. מאמרי אדה\"א בראשית ע' רעט וע' שב [והוא משנת תקפ\"ג]."],["2823","253","<b>ומאז באתי לדבר אל פרעה</b>: שמות ה, כג [ושם: אל פרעה לדבר]."],["2824","254","<b>וגם הקימותי</b>: וארא ו, ד [בדילוג]."],["2825","255","<b>וגם [אני] שמעתי</b>: וארא שם, ה."],["2826","256","<b>לכן אמור לבנ\"י</b>: וארא שם, ו."],["2827","257","<b>ולקחתי אתכם לי לעם</b>: וארא ו, ז."]]],[2300540593,"כו', והג' וגם אני שמעתי נאקת כו', דכל אלה יחוברו לטעם א' להשיב על טענתו למה הרעות כו', והוא מ\"ש לכן, כלומר מג' טעמים אלה אמור, יכול תוכל לומר לישראל שיהיו מוכנים להיות לקבלת התורה שז\"ש ולקחתי אתכם לי לעם ולא עוד אלא והייתי לכם לאלקים שזהו בקיום המצות בפו\"מ בא\"י דוקא, שע\"י המצות יש יחוד הוי' באלקי' ממש, דהיינו ששם הוי' כמו שהוא בעצמו<sup data-n=\"2828\">258</sup> נעשה רק בבחי' שם אלקי' וכמ\"ש יעקב והי' הוי' לי לאלקי'<sup data-n=\"2829\">259</sup> שזהו כמו דבר נפלא ומחודש ביותר שאין כמוהו שיהי' הוי' בעצמו לי לאלקים ממש, כמו שעכשיו אצלו בחי' אלקי' רק בצירוף שם הוי' ע\"י צמצום דאל שדי שהוא בחי' הממוצע כנ\"ל. וכך הוא כאן מ\"ש והייתי לכם לאלקי' דמ\"ש והייתי היינו שם הוי' שהזכיר קודם אני הוי' כו', שהוא עצמו ממש יהי' להם לאלקים ממש כמ\"ש מי כה' אלקינו, ובכמה מקומות ובפרט בא' אנכי ה' אלקיך דוקא שזהו מדרגה היותר נעלה גם מיחוד דשם אלקים בהוי' הנ\"ל שא' ע\"ז וידבר אלקי' כו' אני הוי' כו' וד\"ל.\n<b>והנה</b> מאחר שמבואר למעלה דלפ\"ע ההעלאה בבחי' רצוא והסתלקות בכלות הנפש בזמן הגלות שצעקו אל ה' בצר להם<sup data-n=\"2830\">260</sup> כו', כך הי' ערך בחי' השוב ממקום עליון וגבוה ביותר דהיינו מאותו מקום ומדרגה שעלה לשם, יומשך משם מבחי' הפנימי' ועצמיות בשם הוי' העצמי כנ\"ל. וז\"ש אנכי ארד עמך מצרימה ואנכי אעלך במ\"ת כו' שזהו רק קבלת התו\"מ, וממילא יובן מזה כאשר יהי' גילוי אוא\"ס ממדרגה גבוה ונעלה יותר שהן פנימי' טעמי המצות וסודות התורה שיתגלה ע\"י משיח (בהעברה שני' בנהר פרת כמ\"ש עד יעבור<sup data-n=\"2831\">261</sup> עמך ה' עד יעבור כו' וכמ\"ש כימי צאתך<sup data-n=\"2832\">262</sup> מאמ\"צ אראנו נפלאות כו' כמ\"ש במ\"א), א\"כ ודאי שצ\"ל בחי' הרצוא שקודם לבחי' שוב כזה בהסתלקות ועלי' למעלה מעלה הרבה יותר, שמשם יהי' המשכת בחי' שוב כזה בגילוי רזי' דאוריי' והשגו' עצמו' אוא\"ס מגדול עד קטן כמ\"ש ולא ילמדו<sup data-n=\"2833\">263</sup> כו' כי כולם <span data-k=\"pg\">צה</span> ּ ידעו אותי כו', שלא הי' כזה במ\"ת ולא בבית ראשון כו'. וזהו הטעם לענין אריכות הגלות דעכשיו כ\"כ משך זמן רב (י\"ח מאות שנה<sup data-n=\"2834\">264</sup> ) שהוא בבחי' העלי' והסתלקו' למעלה מעלה בעילוי אחר עילוי בעצמו' במדרגה העליונה הרבה יותר מגלות מצרים שלא הי' רק רד\"ו שנה לבד, א\"כ ודאי שממקום שעלה משם דוקא יהי' בחי' השוב מרצוא כזה בבחי' יתרון מעלה ומדרגה הרבה יותר מכמו שהי' בזמן מ\"ת שהי' פב\"פ, והוא בחי' שלימות האמיתי שיהי' בימות המשיח דכתיב ונגלה כבוד ה' כו' וכתיב כי עין בעין יראו<sup data-n=\"2835\">265</sup> כו', שזהו",[["2828","258","<b>בעצמו</b>: ב: ניתוסף: ממש. ה: ממש בעצמו."],["2829","259","<b>והי' הוי' לי לאלקי'</b>: נסמן לעיל פ' שמות מח, ג."],["2830","260","<b>שצעקו אל ה' בצר להם</b>: ע\"פ תהלים קז, ו. כח."],["2831","261","<b>עד יעבור</b>: נסמן לעיל פ' שמות א, ב."],["2832","262","<b>כימי צאתך</b>: מיכה ז, טו."],["2833","263","<b>ולא ילמדו</b>: ירמי' לא, לג."],["2834","264","<b>הגלות. . י\"ח מאות שנה</b>: ראה גם מאמרי אדה\"א הנחות תקע\"ז ע' קי. וש\"נ."],["2835","265","<b>כי עין בעין יראו</b>: ישעי' נב, ח."]]],[2300540608,"הכרה במהו\"ע ית' וכמ\"ש ידעו אותי כלומר יכירו אותי כו', ולא כמ\"ת שגם שא' וכל העם רואים<sup data-n=\"2836\">266</sup> כו', [ש]זהו קול דברים בלבד ותמונה<sup data-n=\"2837\">267</sup> אינכם רואים זולתי קול כו', וכן אמר כי לא ראיתם<sup data-n=\"2838\">268</sup> [כל תמונה] כו', ובמשיח א' ותמונת ה' יביט<sup data-n=\"2839\">269</sup> למעלה ממדרגת משה שא\"ל ופני לא יראו<sup data-n=\"2840\">270</sup> כי לא יראני האדם וחי<sup data-n=\"2841\">271</sup> שזהו עכשיו משא\"כ במשיח וד\"ל (והעוה\"ב הוא למעלה גם מימות המשיח, וז\"ש ואנכי אעלך גם עלה גם זה ריבוי לחיי העוה\"ב<sup data-n=\"2842\">272</sup> שנא' יקימנו ונחי' לפניו<sup data-n=\"2843\">273</sup> ממש שזהו אחר תח\"ה דוקא וז\"ש עם זו קנית<sup data-n=\"2844\">274</sup> ממש).\n<b>והנה</b> אחר כל הנ\"ל יובן ג\"כ שגם עכשיו בק\"ש במ\"ש ואהבת את ה' בכל לבבך כו' שהן ג' מדרגות הנ\"ל בפ' זו וארא אל כו', דמ\"ש ואהבת בכל לבבך היינו בחי' היחוד דהוי' אלקים שהי' באבות שהן המרכבה באוי\"ר כו'. אהבה דאברהם שרש לאהבה שבכל א' מישראל<sup data-n=\"2845\">*275</sup> בא' ואהבת את הוי' אלקיך וידוע דואהבת גימ' ב\"פ אור<sup data-n=\"2846\">275</sup> או\"י ואו\"ח שהוא אהבה דאברהם ופחד יצחק<sup data-n=\"2847\">276</sup> שהוא אוי\"ר רו\"ש ורחמים דיעקב בחי' הממוצע כו', וזהו בכל לבבך באוי\"ר ורחמים כו' (ובאמת גם אוי\"ר שנצטוו ישראל בדרך ציווי הרי גם הם ממצות הוי' שבכלל התו\"מ ששרשם עליון יותר מאוי\"ר דאבות גם שהי' ברוחניות בחי' מרכבה, כי יחוד זה דהוי' אלקים שבמצות אוי\"ר למטה ובפרט לענין מעשה להיות סור מרע ביראה שהיא שרש<sup data-n=\"2848\">277</sup> לשס\"ה ל\"ת ובאהבה להיות עשה טוב בפו\"מ גבוה הוא מיחוד העליון דהוי' באלקי' באוי\"ר דאבות, לפי שנתחב\"ס דוקא וכנ\"ל בפי' ושמי הוי' לא נודעתי להם כו'), וזהו בכל לבבך בשני יצריך<sup data-n=\"2849\">278</sup> בסומ\"ר מיראה וע\"ט מאהבה כו' וד\"ל. והמדרגה הב' בכל נפשך היינו מדרגה הב' דקבלת התו\"מ פב\"פ במ\"ת שהוא בחי' שמי הוי' ממש שבעצמו' אוא\"ס שלא נודע לאבות וכנ\"ל. וזהו במצות ת\"ת עכשיו כמ\"ש ודברת בם<sup data-n=\"2850\">279</sup> כו', שע\"י שמדבר דבר ה' בפיו הרי מקשר נפשו ומחשבתו ודיבורו בדבר הוי' במוחי' ומו\"ד מחשבה במחשבה כו', שזהו כמו בחי' פב\"פ דמ\"ת ממש שהיו מקבלים דבר ה' בי' הדברות כי דבריו חיים וקיימים<sup data-n=\"2851\">280</sup> כו', וכידוע דכל היושב ושונה<sup data-n=\"2852\">281</sup> הקב\"ה יושב ושונה כנגדו ג\"כ בבחי' פני' ומוחי'",[["2836","266","<b>וכל העם רואים</b>: יתרו כ, טו."],["2837","267","<b>קול דברים. . ותמונה</b>: ואתחנן ד, יב [בדילוג]."],["2838","268","<b>כי לא ראיתם</b>: ואתחנן שם, טו."],["2839","269","<b>ותמונת ה' יביט</b>: בהעלותך יב, ח. ראה גם לקמן סז, ג."],["2840","270","<b>ופני לא יראו</b>: תשא לג, כג."],["2841","271","<b>כי לא יראני האדם וחי</b>: תשא שם, כ."],["2842","272","<b>גם. . העוה\"ב</b>: ראה גם לעיל כא, א. מאמרי אדה\"א שמות ח\"א ע' סו. וש\"נ."],["2843","273","<b>יקימנו ונחי' לפניו</b>: הושע ו, ב."],["2844","274","<b>עם זו קנית</b>: המשך הכתוב עד יעבור — בשלח טו, טז."],["2845","*275","<b>אהבה דאברהם שרש לאהבה. . מישראל</b>: ראה גם לקמן פ' תצוה שסד, א. וש\"נ."],["2846","275","<b>דואהבת גימ' ב\"פ אור</b>: פע\"ח (שער הק\"ש) ש\"ח, פכ\"ג. ראה לקמן עז, ב. פ' בשלח רלח, ג. תרומה שטז, ג. ויקהל שצד, ד. פקודי תס, א. ש\"א כט, ב. מ, סע\"ב. מאמרי אדה\"א שמות ח\"ב ע' שנא. דברים ח\"ד ס\"ע א'תקה ואילך ובהנסמן בהנ\"ל."],["2847","276","<b>ופחד יצחק</b>: ויצא לא, מב."],["2848","277","<b>ביראה שהיא שרש</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310009\" data-slug=\"tanya\" data-id=\"3401310009\">תניא</a> פ\"ד ובמ\"מ הגהות והע\"ק לשם. של\"ה נא, ב. מאמרי אדה\"א קונטרסים ע' פז. וש\"נ."],["2849","278","<b>בכל לבבך בשני יצריך</b>: ואתחנן ו, ה ובספרי שם. ברכות נד, א (במשנה). הנסמן במ\"מ לש\"א ו, א."],["2850","279","<b>ודברת בם</b>: ואתחנן ו, ז."],["2851","280","<b>דבריו חיים וקיימים</b>: ע\"פ ברכת אמת ויציב."],["2852","281","<b>דכל היושב ושונה</b>: נסמן לעיל נח, ג הערה 18."]]],[2300540622,"העליוני' וכמ\"ש ואשים דברי בפיך<sup data-n=\"2853\">282</sup> ובצל ידי כו' וכן מ\"ש ה' צלך<sup data-n=\"2854\">283</sup> כו' וכמ\"ש במ\"א, שזהו כמו קבלת התורה בסיני ממש וראי' ממה שארז\"ל מה להלן באימה ויראה<sup data-n=\"2855\">284</sup> כו'. וזהו בחי' השוב כמ\"ש ובכל נפשך לקשר השכל ומו\"ד כו' להמשיך דבר ה' בד\"ת להחיות נשמתו כמ\"ש כי אמרתך חייתני<sup data-n=\"2856\">285</sup>, ולהיות גילוי אור ה' באותיות התורה, ובחי' שוב זה הוא אחרי בחי' הרצוא דכל לבבך הנ\"ל בבחי' התפעלו' הלב באוי\"ר כנ\"ל וד\"ל. והמדרגה הג' הוא מ\"ש ובכל מאדך שהיא מדרגה עליונה גם מבכל נפשך הנ\"ל, וזהו ענין ומדרגה הנ\"ל שיהי' בימות המשיח דוקא שאחר אריכות הגלות דעכשיו דכתיב עין בעין יראו<sup data-n=\"2857\">286</sup> כו' שלמעלה גם ממדרג' דמ\"ת פב\"פ כנ\"ל. וזהו ע\"י ענין בכל מאדך דוקא שהוא <span data-k=\"pg\">192</span> ּ התשובה בקירות הלב שלמעלה מן השכל ו[ה]טעם שזהו בחי' מאד בלי גבול כלל, שהוא למעלה גם מקיום התו\"מ באוי\"ר בפו\"מ דתשובה קדמה לעולם<sup data-n=\"2858\">287</sup> כו', לפי שמגיע בעצמו' אוא\"ס ממש שלמעלה גם משמי הוי' שבתו\"מ הנ\"ל שאינו אלא בחי' שם עכ\"פ אלא שהוא בחי' שמו העצמי כו'. וכמו שמבואר הטעם בזהר משום דבע\"ת משכי לי' לקודב\"ה בחילא יתיר<sup data-n=\"2859\">288</sup>, פי' בחילא יתיר בכח גדול ועצום הרבה יותר מכח האוי\"ר ומע\"ט, ומפני זה אמרו רז\"ל דבמקום שבע\"ת עומדי'<sup data-n=\"2860\">289</sup> צ\"ג א\"י לעמוד שם כלל (וראי' מתשובה דראב\"ד שיצאה נשמתו<sup data-n=\"2861\">290</sup> בבכי' וקנא בו רבי שהי' צ\"ג וא' יש קונה עולמו<sup data-n=\"2862\">291</sup> בשעה א' כו'). וזהו הטעם שא' בזהר ובדרז\"ל דגם משה לא זכה לתשובה<sup data-n=\"2863\">292</sup> רק קודם מותו כו' אע\"פ שכבר קיבל את התורה פב\"פ כו', וע\"כ גם ביאת משיח תלוי בתשובה דוקא כמארז\"ל אם ישראל עושי' תשובה<sup data-n=\"2864\">293</sup> נגאלי' וא\"ל אינן נגאלין, לפי שמדרגה הגבוה מאד דעין בעין כו' הנ\"ל שיהי' בימות המשיח א\"א להיות כ\"א ע\"י בחי' רצוא והסתלקות דתשובה דוקא והוא כמו האה\"ר דבכל מאדך. וז\"ש ואנכי אעלך גם עלה לימות המשיח ע\"י תשובה וכמ\"ש בר\"מ דמשיחא אתא לאתבא<sup data-n=\"2865\">294</sup> צדיקייא בתיובתא כו' (והעוה\"ב למעלה גם מזה כמ\"ש גם עלה, וכמ\"ש עם זו קנית בקנין עצמי. ואין העוה\"ב בא רק מן המצות<sup data-n=\"2866\">295</sup>, כי גם התשובה אינו אלא בצדיקים<sup data-n=\"2867\">296</sup> בתו\"מ דוקא כמ\"ש במ\"א וכמ\"ש לאתבא צדיקייא כו'. וז\"ש אחר ובכל מאדך דתשובה והיו הדברים<sup data-n=\"2868\">297</sup> כו', וכמ\"ש תכלית חכמה<sup data-n=\"2869\">298</sup> תשובה",[["2853","282","<b>ואשים דברי בפיך</b>: ישעי' נא, טז. ראה הנסמן במאמרי אדה\"א דברים ח\"א ע' רמ."],["2854","283","<b>ה' צלך</b>: תהלים קכא, ה. ראה תולעת יעקב — לר\"מ בן גבאי — בהקדמה (ד, א). לקמן פ' בשלח קפ, א. של\"ה (שער הגדול) ל, א בשם המדרש. מאמרי אדה\"ז תקס\"ה ח\"א ע' קכו. מאמרי אדה\"א בראשית ס\"ע שלט ואילך. וש\"נ."],["2855","284","<b>מה להלן באימה ויראה</b>: ברכות כב, א. ראה לקמן פ' יתרו רנג, ד."],["2856","285","<b>כי אמרתך חייתני</b>: תהלים קיט, נ."],["2857","286","<b>עין בעין יראו</b>: ישעי' נב, ח."],["2858","287","<b>דתשובה קדמה לעולם</b>: פסחים נד, א."],["2859","288","<b>דבע\"ת. . בחילא יתיר</b>: נסמן לעיל לז, א."],["2860","289","<b>דבמקום שבע\"ת עומדי'</b>: נסמן לעיל מא, א הערה 175."],["2861","290","<b>דראב\"ד שיצאה נשמתו</b>: נסמן לעיל מ, ד."],["2862","291","<b>יש קונה עולמו</b>: ע\"ז יז, א. ראה לקמן פ' בשלח קס, ב."],["2863","292","<b>משה. . לתשובה</b>: נסמן לעיל לז, א."],["2864","293","<b>אם ישראל עושי' תשובה</b>: נסמן לעיל לז, א."],["2865","294","<b>דמשיחא אתא לאתבא</b>: נסמן לעיל פ' שמות מא, ב."],["2866","295","<b>העוה\"ב. . המצות</b>: נסמן לעיל ז, א."],["2867","296","<b>התשובה. . בצדיקים</b>: ראה גם מאמרי אדה\"א נ\"ך ע' רו. הנחות תקע\"ז ע' צה ובהנסמן בהנ\"ל."],["2868","297","<b>והיו הדברים</b>: ואתחנן ו, ו."],["2869","298","<b>תכלית חכמה</b>: ברכות יז, א. ראה גם לקמן פ' בשלח קעז, ב. יתרו רסו, ד. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680128\" data-slug=\"torat-chaim\" data-id=\"2300680128\">תו\"ח וישב קצט, ג</a> ובהערה 43."]]],[2300540636,"ומע\"ט, שניהם יחד, ותשובה קודם למע\"ט, וכן א' יפה שעה א'<sup data-n=\"2870\">299</sup> בתשובה ומע\"ט כו' שזהו ימות המשיח והעוה\"ב וד\"ל).\n<b>והנה</b> יש לפרש עוד בפ' זו דוארא אל אברהם כו' באופן אחר שהוא מדבר בבחי' עיבור ולידה ומוחין כו' (כמשי\"ת). וכללות הענין בפי' וארא שהוא לשון התגלות מבחי' ההעלם דוקא, ואמנם יש בו ב' פי' א' לשעבר שכבר נתגלה מן ההעלם לאברהם כו' כמו וירא ה' אל אברהם<sup data-n=\"2871\">300</sup> כו', ופי' הב' וארא לשון עתיד דוקא שעתיד להגלות לאברהם וליצחק כו' שזהו כמו בחי' הלידה שאחר העיבור כמו האני אשביר<sup data-n=\"2872\">301</sup> ולא אוליד כו', כידוע דהגלות נק' עיבור<sup data-n=\"2873\">302</sup> והגאולה נק' לידה כמ\"ש כמו הרה תקריב ללדת<sup data-n=\"2874\">303</sup> כו' (כמשי\"ת). ותחלה היו בנ\"י הכלולי' מג' אבות בבחי' עיבור (כמ\"ש עד יעבור כו' אותיות עיבור<sup data-n=\"2875\">304</sup> ) ואח\"כ יהיו בבחי' לידה כולד שיצא לאויר העולם כו', והוא פי' הב' וארא שעתיד להגלות באור חדש לאבות כו' שלא נתגלה להם מעולם כו' (וכמ\"ש אהי' אשר אהי'<sup data-n=\"2876\">305</sup> שלחני אליכם, אהי' הא' אנא זמין לאולדה כו' בימות המשיח, ואהי' הב' אנא זמין לאתגלאה<sup data-n=\"2877\">307</sup> בעוה\"ב<sup data-n=\"2878\">306</sup> אחר תח\"ה דכתיב ביום הג' יקימנו<sup data-n=\"2879\">308</sup> ונחי' לפניו ממש כו').\n<b>ולהבין</b> ביאור הענין הנה תחלה יש להקדים ענין הידוע שאין קורין אבות אלא לשלשה<sup data-n=\"2880\">309</sup> דוקא שהן אברהם יצחק ויעקב, ע\"כ בכל תפלה אין מזכירי' רק ג' אלה דוקא כמו שאו' אלקי אברהם אלקי יצחק כו' (וכן <span data-k=\"pg\">צו</span> ּ בשאר נוסחו' שמזכירין שרש נש\"י ממקורם הראשון כמו שאו' אבל אנחנו עמך<sup data-n=\"2881\">310</sup> בני אברהם כו', ובתפלת מנחה דשבת אברהם יגל יצחק כו'). ולכאו' יש להבין למה לא יקראו אבות גם לשבטים כראובן ושמעון ולוי כו' אחר שהמה קרובי' יותר אל הנולדי' מהם, כמו כל שבט ראובן במספרו בתולדותיו שקרוב יותר לראובן אביהם מלאברהם יצחק ויעקב ולמה לא יקראו בניהם אחריהם בשם אבות, רק לאברהם כמו שנק' אברהם אבינו וכן יצחק ויעקב ולא יקראו ראובן אבינו וכן בשאר השבטים. אך הנה באמת א\"א לקרות אבות ממש רק למקור ושרש הראשון שממנו מסתעפי' הענפים הפרטי', כמו השרשי' מאילן שהן העיקר והענפים שיונקים מהם נק' שבטים כמ\"ש ששם עלו שבטים<sup data-n=\"2882\">311</sup> כו' וכתיב הבאים ישרש יעקב<sup data-n=\"2883\">312</sup> יציץ",[["2870","299","<b>יפה שעה א'</b>: אבות פ\"ד, מי\"ז. ראה גם לקמן פ' בשלח קס, א. קעז, ב. תצוה שמג, ג. שדמ, א ואילך. מאמרי אדה\"א דברים ח\"ד ע' א'קעט. וש\"נ. ש\"א לח, ב. שע\"ת עב, ד ובהערה 25."],["2871","300","<b>וירא ה' אל אברהם </b>[ב: אברם]: לך יב, ז. יז, א. אברהם — ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670362\" data-slug=\"torat-chaim\" data-id=\"2300670362\">תו\"ח לך פה, ד</a>."],["2872","301","<b>האני אשביר</b>: ישעי' סו, ט."],["2873","302","<b>דהגלות נק' עיבור</b>: נסמן לעיל יז, ג."],["2874","303","<b>כמו הרה תקריב ללדת</b>: ישעי' כו, יז."],["2875","304","<b>עד יעבור. . עיבור</b>: נסמן לעיל יז, ג."],["2876","305","<b>אהי' אשר אהי'</b>: שמות ג, יד [בדילוג]."],["2877","307","<b>אנא זמין לאולדה. . לאתגלאה</b>: ראה זהר ויקרא יא, א. אחרי סה, ב."],["2878","306","<b>אהי' הא'. . בימות המשיח. . הב'. . בעוה\"ב</b>: ראה הנסמן לעיל א, ב הערה 17."],["2879","308","<b>ביום הג' יקימנו</b>: הושע ו, ב."],["2880","309","<b>שאין קורין אבות אלא לשלשה</b>: ברכות טז, ב. ראה לקמן פ' משפטים רפו, ד. וראה לקו\"ש בלק (כרך ד) ע' 1068 הערה 12. ויצא (כרך י) ע' 97 הערה 48."],["2881","310","<b>אבל אנחנו עמך</b>: תפלת השחר מתדא\"ר פכ\"א."],["2882","311","<b>ששם עלו שבטים</b>: תהלים קכב, ד."],["2883","312","<b>הבאים ישרש יעקב</b>: ישעי' כז, ו. ראה גם לעיל פ' שמות א, ב."]]],[2300540648,"כו', והכל הולך אחר השורש דוקא כמ\"ש הביטו אל צור חוצבתם<sup data-n=\"2884\">313</sup> כו' הביטו אל אברהם אביכם<sup data-n=\"2885\">314</sup> כו'. וזהו שיש מבחי' השרש דג' אבות בכאו\"א מישראל גם בניצוץ הקטן ביותר גם בדור האחרון ביותר כמו בדור הראשון כמו השרש שממשיך כח יניקה בשוה לענפי האילן כולו מראש לסוף כו' ולכך<sup data-n=\"2886\">315</sup> יכול כאו\"א לומר מתי יגיעו מעשי<sup data-n=\"2887\">316</sup> למעשה אברהם כו' וכל א' או' בתפלתו אלקינו ואלקי אבותינו אלקי אברהם כו'). ושרש הענין ידוע דאע\"פ שהשבטים נק' שבטי י\"ה<sup data-n=\"2888\">317</sup> ממש מ\"מ אין שם הוי' בשלימותו רק באבות דוקא שהן הן המרכבה ממש (וכמ\"ש כאן וארא אל אברהם כו' שהוא שם הוי' ע\"י אל שדי כנ\"ל). וטעם הדבר ידוע דשם הוי' הכללי דאצי' הוא בג' מדות דחג\"ת דוקא דהיינו כשב' השמות דאל החסד<sup data-n=\"2889\">318</sup> ואלקי' דגבורה<sup data-n=\"2890\">319</sup> כלולי' בשם הוי' בחי' ת\"ת<sup data-n=\"2891\">320</sup> דז\"א כו', וג' אלה המדות דאצי' הן מקוריי' הכלליי' וראשיי' לכל השפע' הנמשכ' מאצי' לבריאה כו', כמו כאשר מתחלק אור השפע הכללי' דשם הוי' דאצי' בבריאה בד' מחנות<sup data-n=\"2892\">321</sup> כו' הרי מחנה מיכאל שהוא בבחי' החסד<sup data-n=\"2893\">322</sup> ה\"ז כמו ענף הפרטי שנמשך מן שרש של האילן, וכך הוא למטה דגל מחנה ראובן בסט' דדרום<sup data-n=\"2894\">323</sup> בחסד<sup data-n=\"2895\">324</sup> בדוגמא דד' מחנות שכינה<sup data-n=\"2896\">325</sup> למעלה כמ\"ש בזהר בפ' פקודי<sup data-n=\"2897\">326</sup> כו' אינו רק ענף א' משרש האילן שהן האבות, וא\"כ דוקא בהתחלקו' ד' דגלים ונכללי' יחד אז אע\"פ שכל א' נמשך מבחי' האורות דאצי' שכלולים בשם הוי' בדרך פרט עד שהן י\"ב שבטי' י\"ב חלקים, מ\"מ בכללותם יחד דוקא שורה שם הוי' דאצי' שבחג\"ת שהן האבות שנק' מרכבה לחג\"ת דאצי' ממש כידוע. אבל בשבט א' או בדגל א' א\"א שישרה בו שם הוי' דאצי' הכללי כמו שהוא באצי' רק בג' אבות לבד שהן הג' קוין חג\"ת דאצי' ממש. וז\"ש ששם עלו שבטים שבטי י\"ה כשעולי' בהתכללות א' מלמטה למעלה מבריאה לאצי' נק' שבטי י\"ה ממש לקבל מאבו' שהן חג\"ת הכלולי' בשם הוי' דאצי', וזהו עדות לישראל<sup data-n=\"2898\">327</sup> להודות לשם הוי' דאצי' אבל לא כשהשבטי' למטה בעולם הבריאה ומשם מתפשטי' לנשמות שבגופי' שאין נק' אבות כלל גם שהן קרובים יותר לנולדי', רק ג' האבות דוקא מפני שהן בחי' השרש הראשון בבחי' שם הוי' דאצי' שהן חג\"ת, וזהו שאו' אלקי אברהם כו' ואח\"כ הגדול הגבור כו' וד\"ל (וע\"כ גם בכל ניצוץ אלקי בפרט אינו מאיר רק מג' אבות לבד ולא מי\"ב שבטים כנ\"ל כמו שאו'",[["2884","313","<b>הביטו אל צור חוצבתם</b>: ישעי' נא, א."],["2885","314","<b>הביטו אל אברהם אביכם</b>: ישעי' שם, ב."],["2886","315","<b>ולכך</b>: אוצ\"ל: (ולכך."],["2887","316","<b>מתי יגיעו מעשי</b>: ראה תדא\"ר רפכ\"ה. תו\"ח ויצא קעו, ב ובהערה 36."],["2888","317","<b>שבטי י\"ה</b>: תהלים קכב, ד."],["2889","318","<b>דאל החסד</b>: ראה זהר אחרי סה, א. הנסמן ב<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670094\" data-slug=\"torat-chaim\" data-id=\"2300670094\">תו\"ח נח סד, ג</a> הערה 39."],["2890","319","<b>ואלקי' דגבורה</b>: ראה זהר יתרו פג, ב. הנסמן בתו\"ח שם הערה 41."],["2891","320","<b>הוי' בחי' ת\"ת</b>: ראה זהר ויקרא יא, א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670419\" data-slug=\"torat-chaim\" data-id=\"2300670419\">תו\"ח בראשית מא, א</a> הערה 7."],["2892","321","<b>בד' מחנות</b>: נסמן בהערה 325."],["2893","322","<b>מיכאל. . החסד</b>: ראה ת\"ז ת\"ע (קכו, א. קכז, א). שו\"ע אדה\"ז הל' תפלה סק\"כ, ס\"ב."],["2894","323","<b>מיכאל. . דגל מחנה ראובן בסט' דדרום</b>: במדבר ב, י. ראה זהר במדבר קיח, ב. לקמן עט, א. מאמרי אדה\"א בראשית ע' תקלג. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670566\" data-slug=\"torat-chaim\" data-id=\"2300670566\">תו\"ח נח נז, ד</a> הערה 60."],["2895","324","<b>דדרום בחסד</b>: ראה זהר בראשית כט, ב ובאוה\"ח שם. מאמרי אדה\"א נ\"ך ע' קכב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670464\" data-slug=\"torat-chaim\" data-id=\"2300670464\">תו\"ח בראשית מב, ב</a> ובהערה 30."],["2896","325","<b>דד' מחנות שכינה</b>: זהר במדבר קיח, ב."],["2897","326","<b>בזהר בפ' פקודי</b>: ראה גם לעיל פ' שמות א, ב הערה 9. ל, ב הערה 135. לקמן עט, א."],["2898","327","<b>עדות לישראל</b>: המשך הכתוב ששם עלו שבטים."]]],[2300540660,"אבל <span data-k=\"pg\">194</span> ּ אנחנו כו' מה יפה ירושתינו כו' וד\"ל). וזהו שא' וארא אל אברהם כו' באל שדי שכבר נמשך ונתגלה לאבות בבחי' חג\"ת דאצי' כנ\"ל שירדו למטה בי\"ב שבטים דבריאה כו' שזהו בחי' ההתגלות מן ההעלם כנ\"ל, אך שמי הוי' לא נודעתי להם לפי שזה יתגלה לע\"ל ע\"י קיום התו\"מ שהוא בחי' מוחי' דגדלות שלאחר מוחי' דיניקה (כמשי\"ת).\n<b>ומעתה</b> הנה יש להבין ב' הפי' דוארא הנ\"ל, א' לעבר שכבר נראה ונתגלה לאבות והב' להבא שעתיד להגלות עליהם כו', שזהו ב' מדריגות דעיבור ולידה כנ\"ל. והנה תחלה יש להבין הטעם שמצינו בכמה מקומות שהגלות נק' בשם עיבור כמו הרה תקריב ללדת כו' כן הרינו חלינו מפניך הוי'<sup data-n=\"2899\">328</sup>, וידוע שהגאולה נק' לידה כמו הרה גם ילדה ציון<sup data-n=\"2900\">329</sup> את בני' כו' וכן האני אשביר ולא אוליד כו' (וקודם ביאת משיח נק' חבלי לידה כמ\"ש תחיל תזעק בחבלי' כו'), וכן ארז\"ל במשנה אפי' בשעה<sup data-n=\"2901\">330</sup> שאתה מתמלא עליהם עברה כאשה עוברה יהיו כל צרכיהם לפניך כו', שזהו בזמן הגלות דוקא שנש\"י הן בבחי' עיבור כאשה עוברה כו'. וביאור הדברים הנה יובן עד\"מ עיבור הגשמי בילד<sup data-n=\"2902\">331</sup> כמו שהוא במעי אמו כו' שאמרו שהולד מקופל ומונח ראשו בין ברכיו<sup data-n=\"2903\">332</sup> כו' ואוכל מה שאמו אוכלת<sup data-n=\"2904\">333</sup> דהיינו שאוכל מטיבורו כי פיו סתום וטיבורו פתוח. ומה שנברר מן המאכל שאמו אוכלת בקרביי' ומיעיים נכנס לפי טיבורו לבני מעיו ומקבל חיותו מזה בכל האברי' כי עובר כירך אמו<sup data-n=\"2905\">334</sup>, וכמו בני מעיים שמקבלי' המאכל שהולך מן הפה לקרביי', כך הולד מקבל המאכל שאכלה ונברר בקיבה בפי טיבורו, שנמצא שלא קיבל שפע המאכל רק בני מעיו לבד, וגם רק המאכל כמו שהוא בקרביי' ולא קיבלו אברי' הפנימיי' כלב וריאה וכבד וקנה וושט ופה וכה\"ג זה השפע כלל כי ראשו מונח בין ברכיו, ומה שנכנס בטיבורו שבברכיו כשהוא מקופל הולך מלמטה למעלה להשפיע חיות גם לראשו ולבו וכבדו כו' עי\"ז שאוכל מטיבורו (ונק' אכילה חיצוני' כמ\"ש במ\"א<sup data-n=\"2906\">335</sup> ) ע\"פ רפאות תהי לשריך<sup data-n=\"2907\">336</sup> (כמשי\"ת). כי אע\"פ שיש בולד כל האברים בשלימותם כמו שהן לאחר שנולד כמו העין והאזן והפה וידים כו', אך הן בלתי פועלי' פעולת[ן] כלל וכלל, שהעין אינו רואה והאזן אינו שומע כו' ופיו סתום וראשו וידיו בין ברכיו כדבר המקופל כו', ע\"כ גם קבלת חיותו בא מן הטבור שלו ולא בפיו כלל כנ\"ל. אך הנה מיד כשנולד הולד ויצא לאויר העולם הנה נפתח הסתום שבו, שפיו הסתום נפתח והעין רואה והאזן ישמע כו', והפתוח יסתם שהוא הטבור שהי' פתוח בבטן נסתם כו' ויונק חלב מפיו כו', והנה ידוע שמיד שיולד התינוק הוא צועק",[["2899","328","<b>כן הרינו חלינו מפניך הוי'</b>: ישעי' כו, יז. יח [ושם: כן היינו מפניך ה'. הרינו חלנו — ראה לקמן סז, ג. פ' ויקהל שצט, ג. מאמרי אדה\"א שמות ח\"א ע' נה. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680255\" data-slug=\"torat-chaim\" data-id=\"2300680255\">תו\"ח וישב רח, ב</a>]."],["2900","329","<b>הרה גם ילדה ציון</b>: ישעי' סו, ח [ושם: חלה גם ילדה — ראה מאמרי אדה\"ז תקס\"ב כאן ע' קלד]."],["2901","330","<b>במשנה אפי' בשעה</b>: נסמן לעיל לא, ג."],["2902","331","<b>בילד</b>: אה: ב(ד)ולד. וראה גם לקמן הערה 361."],["2903","332","<b>שהולד. . ראשו בין ברכיו</b>: נדה ל, ב."],["2904","333","<b>ואוכל מה שאמו אוכלת</b>: נדה שם."],["2905","334","<b>עובר כירך </b>[א: ירך]<b> אמו</b>: גיטין כג, ב."],["2906","335","<b>במ\"א)</b>: אגדה: במ\"א. אגד: גם התחלת החצע\"ג ליתא."],["2907","336","<b>רפאות תהי לשריך</b>: משלי ג, ח. ראה גם מאמרי אדה\"ז על מארז\"ל ע' קלא. מאמרי אדה\"א שמות ח\"א ע' קמג."]]],[2300540672,"ובוכה ומיד בבכייתו נותנין לו מעט חלב מחלב אמו ותהי' זאת נחמתו מעצבונו וישתוק כו'. ויש להבין מה שהוא בוכה בהולדו שבאמת הי' ראוי להיות בחדוה ושמחה על שנפתחו עיניו ורואה את האור ונפתח פיו כו' לקבל אויר העולם, שהרי הי' במאסר בבטן אמו ובחושך לא ראה אור וראשו בין ברכיו כו', ואבריו כדומם ממש בלתי פועלים שום פעולה כלל, ועתה שנולד יצא מחושך לאור ומפחיתות ערך למעלה גבוה וא\"כ למה הוא בוכה בהולדו כו'. הענין הוא <span data-k=\"pg\">צז</span> ּ דבכי' זאת לא מחמת גרעון ופחיתות ערכו במה שנולד ויצא לאויר העולם, דאדרבה נתעלה בעילוי גדול שנפתחו עיניו שהי' סתומים<sup data-n=\"2908\">337</sup> ופיו פתוח כו' וכנ\"ל וכיוצא מבית האסורים שצריך להודות כו', רק ענין בכייתו הוא ענין הבכי' שמרוב חדוה ואשר יצא מן הצער. ואמנם יש בזה בכי' של עצב על מה שעבר עליו שהי' במאסר קשה כזה וגם בעת יציאתו יוצא בדוחק ולחץ גדול ברחם אמו כו', וע\"כ בוכה במר נפשו בעוצב לומר מה זאת הי' לו עד הנה שלא ראה מאורות מימיו כו' ושמח ביציאתו וכלול בכי' זו מחדוה ועצבות יחד, שזהו כמו היוצא מבית האסורים הקשי' מאד שהי' בו זמן רב, שישמח ויבכה כא' [ממש], שדמעות אלה כוללי' חדוה ועצב על שעבר עליו כו' וד\"ל. והנה מעט החלב שיונק מחלב אמו תנחמהו מעצבונו על מה שעבר עליו ותשמחנו מעט וישתוק מבכייתו כו', וזהו כמו פלא למה חלב אמו דוקא תנחמנו מעצבונו כו'. והענין הוא לפי שדם נעכר ונעשה חלב<sup data-n=\"2909\">338</sup> בדדי אמו, וזה שמקבל חיות חדש מחלב אמו שהוא בחי' התענוג שבשפע חלב מזונו שלא הי' לו בבטן אמו מזון טוב כזה ובפיו, ע\"כ ישמח מאד ע\"ז וישכח על כל צרותיו שהי' לו בבטן ולידה כו', ומתעלה להיות במהות בריאה בפ\"ע רק שיקבל מוחי' ומדות והגדלת איברי' מיניקת חלב אמו כל ימי היניקה כו'<sup data-n=\"2910\">339</sup> וד\"ל.\n<b>והנמשל</b> מכ\"ז יש להבין בכללות נ\"י<sup data-n=\"2911\">340</sup> בזמן הגלות שנמשל לעיבור כמ\"ש כמו הרה תקריב ללדת כו' כנ\"ל, וכמו בגלות מצרים שא' ביחזקאל ואעבור עליך<sup data-n=\"2912\">341</sup> ואראך מתבוססת בדמיך שהי' בחי' לידה כולד שיוצא מבטן אמו מיד בהולדו שמתבוסס בדמי לידה כו' (וכמו שא' יחזקאל סי' י\"ו<sup data-n=\"2913\">342</sup> ) ומולדת[י]ך ביום הולדתיך לא כרת שרך ובמים לא רחצת והמלח לא המלחת והחתל כו' ואעבור עליך כו'. והענין הוא בדרך כללו' דנש\"י בגלות הן בבחי' עיבור כולד בבטן אמו דהיינו מה שאין אור האלקי בא בבחי' גילוי אור וחיות מורגש בנשמות, ובכל ניצוץ האלקי בפרט לא במוחי' שלו ובלבו וגם לא בבחי' ראי' ושמיעה, כי גם שמתבונן בגדולת ה' במוחו, מרחוק מאד נראה לו ה' בבחי' ההעלם ביותר, וכאילו אינו רואה בעיניו כלל ואינו",[["2908","337","<b>עיניו שהי' סתומים</b>: ראה ת\"ז ת\"ע קלו, א ד\"ה פתח. וראה גם לעיל ולקמן (בפנים). פ' בא קטז, ד. תצוה שכה, א. ויקהל שצט, ד. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680051\" data-slug=\"torat-chaim\" data-id=\"2300680051\">תו\"ח מקץ רטו, ג</a> ובהערה 29."],["2909","338","<b>שדם נעכר ונעשה חלב</b>: נדה ט, א. ראה גם לעיל נא, א."],["2910","339","<b>כו'</b>: א: כידוע."],["2911","340","<b>יש להבין בכללות נ\"י</b>: א: יובן בכנ\"י בכנסת ישראל ( ). ראה לקמן הערה 347. 378."],["2912","341","<b>ואעבור עליך</b>: יחזקאל טז, ו."],["2913","342","<b>סי' י\"ו</b>: פסוק ב [בדילוגים — ושם: ומולדותיך. . הולדת]."]]],[2300540684,"שומע ומבין כלל כי טח עיניהם מראות<sup data-n=\"2914\">343</sup> כו' ולבו לא יבין ואזנו לא ישמע, כמו הולד בבטן שעיניו סתומים כו' וראשו בין ברכיו שאין בו בגילוי רק הברכיי' שנק' תלת גו תלת<sup data-n=\"2915\">344</sup> כו'<sup data-n=\"2916\">345</sup>, שבחי' חב\"ד נעלמי' בחג\"ת וחג\"ת בנה\"י. וכך אין בנש\"י בגלות בבחי' גילוי אור האלקי רק בבחי' קטנות דנה\"י בלבד שהוא רק בבחי' המעשה דמצות בפו\"מ בלי טעם ודעת ובלא אוי\"ר שבלב כלל רק ע\"י בחי' קטנות דאוי\"ר השייך למעשה בלבד להיות סור מרע גמור בפו\"מ מפני היראה וגם זה בהעלם גדול מאד וכן בועשה טוב דמ\"ע מפני האהבה כו'<sup data-n=\"2917\">*346</sup> וגם זה בהעלם ולא נגלה רק בחי' המעשה בעצמה לבד (ונק' נה\"י דנה\"י כו').\n<b>וזהו</b> שארז\"ל אפי' בשעה שאתה מתמלא עליהם עברה כאשה עוברה שזהו בזמן הגלות שנש\"י הן בבחי' עיבור דקטנות ביותר שנק' אשה עוברה (שאז הדינין קשין וקטרוגי' מתגברי'<sup data-n=\"2918\">346</sup> שנק' עברה כאשה עוברה כו' כמ\"ש במ\"א עכ\"ז יהיו כל צרכיהם לפניך בהשגחה מיוחדת במוחי' דגדלות כו'), וכן מ\"ש כמו הרה תקריב כו' להיות שבזמן הגלות <span data-k=\"pg\">196</span> ּ כללות נש\"י נמשלים<sup data-n=\"2919\">347</sup> לולד בבטן כו' שמקופל ומונח ראשו בין ברכיו כנ\"ל (דהיינו תלת גו תלת כו' כנ\"ל), והוא שאין ישראל מקבלים גילוי אלקות בנשמתם בכאו\"א לפי מדרגתו רק בבחי' נה\"י שבו לבד והוא בחי' המעשה לבד שמקבל עליו [ע]מ\"ש בקיצור רק לענין מעשה לעשות רצון קונו כו' וזהו שנק' ברכיו וראשו שהן המוחי' ומוחי' [ומדות] נעלמי' בברכיו כו' וד\"ל.\n<b>והנה</b> מבואר למעלה במשל הולד שאוכל מטיבורו ממה שאמו אוכלת כו', והענין יובן בדוגמא למעלה בעיבור נש\"י בבטן אמם שנק' אם הבנים בחי' מל' דאצי' שנק' אימא תתאה<sup data-n=\"2920\">348</sup> (וכמו [ו]בפשע[י]כם שולחה אמכם<sup data-n=\"2921\">349</sup> כו') ונק'<sup data-n=\"2922\">350</sup> אוצר הנשמות<sup data-n=\"2923\">351</sup> ששמו<sup data-n=\"2924\">352</sup> גוף<sup data-n=\"2925\">353</sup> כו'), דכמו שלא נתקבל שפע המאכל דאמו אוכלת בולד גשמי רק לבני מעיו ע\"י טיבורו כו', כך הוא למעלה במאכל שאם הבנים העליוני' אוכלת כו' שהוא לחם דתו\"מ שא' לכו לחמו בלחמי<sup data-n=\"2926\">354</sup> כו' וכתיב ותורתך בתוך מעי<sup data-n=\"2927\">355</sup> ממש למזון וחיות ממש (וכענין שא' רעייתי פרנסתי<sup data-n=\"2928\">356</sup> שמפרנסי' לאביהם כו'), וזהו שנק' אכילה פנימי' כמאכל שאדם אוכל בפיו ובשינים יטחון ויטעום בחיך ואח\"כ נכנס במעיו ומתבשל ונברר המאכל והי' לחיות גמור גם לחזק השכל במוח ומדות בלב וכל חיות האברי' פנימי' וחיצוני' כו'. וכך הוא במזון האלקי העליון דתו\"מ שנעשה לאור וחיות חדש בתוס' מוחין חדשים במל' ובמדות וכל בחי' אברי' דשכינתא שזהו ענין מה שאמו אוכלת כו', וכמו",[["2914","343","<b>כי טח עיניהם </b>[אה: עיניו]<b> מראות</b>: ע\"פ ישעי' מד, יח."],["2915","344","<b>תלת גו תלת</b>: נסמן לעיל פ' שמות לח, ד."],["2916","345","<b>כו'</b>: אגה: ניתוסף: שהוא רק."],["2917","*346","<b>וגם. . כו'</b>: בתורת חיים נכפלו תיבות אלו."],["2918","346","<b>הדינין קשין וקטרוגי' מתגברי'</b>: ראה גם מאמרי אדה\"א שמות ח\"א ע' נה."],["2919","347","<b>כללות נש\"י נמשלים</b>: א: כנ\"י נמשל. ראה לעיל הערה 340."],["2920","348","<b>מל'. . אימא תתאה</b>: נסמן לעיל פ' שמות ט, סע\"ב."],["2921","349","<b>[ו]בפשע[י]כם שולחה אמכם</b>: ישעי' נ, א."],["2922","350","<b>ונק'</b>: כנצ\"ל: (ונק'."],["2923","351","<b>מל'. . אוצר הנשמות</b>: ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'קסה. קונטרסים ע' רלו ובהנסמן בהנ\"ל. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680377\" data-slug=\"torat-chaim\" data-id=\"2300680377\">תו\"ח תולדות קמח, ד</a>. לקמן פ' בשלח קלג, ד. תצוה שלג, ד."],["2924","352","<b>אוצר הנשמות ששמו גוף</b>: ראה ע\"ז ה, א וברש\"י ותוס' שם. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תשעה. מאמרי אדה\"א דברים ח\"ב ע' תקנג בהערה."],["2925","353","<b>מל'. . ונק'. . גוף</b>: ראה ערה\"כ לבעל סדה\"ד מערכת גוף."],["2926","354","<b>לכו לחמו בלחמי</b>: משלי ט, ה."],["2927","355","<b>ותורתך בתוך מעי</b>: תהלים מ, ט."],["2928","356","<b>רעייתי פרנסתי</b>: שה\"ש א, ט. ראה זהר ויקרא ז, ב. לקמן פ' ויקהל שצט, א הערה 254. הנסמן במאמרי אדה\"א דברים ח\"ב ע' תרעט. הנחות תקע\"ז ע' קמז."]]],[2300540696,"באדם התחתון שמתחזק מוחי' שלו בעבודת ה' ומדותיו באוי\"ר שבלב בשר וכל גופו ע\"י המאכל גשמי שאכל ושתה בכוונה שלא לתאוה רק שיוכל לעבוד ה' בכח האכילה כו', שאז מה שיש כח השכל האלקי [במאכל] זה שנפל בשבה\"כ מתברר וניתוסף מוחי' חדשים בעבודת ה' כו'. וכך הוא מזון דתורה הנגלית לנו שאדם לומד בפיו וטוחן וגורס בשיניו שנק' גירסא<sup data-n=\"2929\">357</sup> כידוע ונמשך בתוך מעיו כמ\"ש ותורתך בתוך מעי שנעשה לו תוס' אור וחיות בנשמתו במוחין ומדות כו', וזהו בחי' אכילה פנימי' כנ\"ל וד\"ל. אבל בחי' אכילה חיצוני' כמו שאוכל מטיבורו כו' זהו כמו האוכל לתיאבון בתאוה גופני' כבהמה למלאו' כריסו לבד, שהשפעה זו של המאכל לא נתקבל לחיות רק במעיו למלאות כריסו ובני מעיו לבד ולא נברר ועלה ממנו למוחו ולבו בדעת ויראה אלקית כלל, שזה כמאכל בהמה ממש שאינו אלא ל[מלאות] כריסה כו'. ועכ\"ז יש בהעלם תוס' חיזוק השכל ומדות במוח ולב רק שזהו כאוכל מטיבורו ולא בפיו שלא נכנס רק למעיו כו', וכנ\"ל בולד בבטן שאוכל מטיבורו שהמאכל כמו שהוא בלא בירור כלל נכנס למעיו לבד כו' ולא למוחו ולבו שהרי ראשו בין ברכיו כו' כנ\"ל, ועכ\"ז נמשך קצת חיזוק המוחי' [ומדות] בהעלם ע\"י מה שאוכל מטיבורו מה שאמו אוכלת כו'. וכך יובן בדוגמא בכנ\"י שהן בעיבור בבטן המל' בזמן הגלות ששפע יניק' חיותם האלקי' גם במזון דתורה שאם הבנים אוכלת באכילה פנימי' בפה כו' ומקבלים הן רק בבחי' אכילה חיצוני' בפי הטבור שלא נכנס רק לבני מעיו כו', ואין מזה תוס' אור וחיות האלקי במוחי' ומדות דנשמה כלל רק בענין המעשה דבחי' נה\"י לבד כנ\"ל (ועכ\"ז יש תוס' כח בהעלם למוחי' ומדות כמ\"ש במ\"א שז\"ש רפאות תהי לשרך כו' וד\"ל), והיינו כל התו\"מ שעושי' ישראל בזמן הגלות שלא נכנס מאכל <span data-k=\"pg\">צח</span> ּ זה במוחם ולבם כו' להיותם בבחי' עיבור עדיין שעיניו סתומים ופיו סתום כו' ואוכל מטיבורו מה שאמו כו' וד\"ל. אבל הנה הגאולה נק' לידה שזהו כמו שהולד כשנולד יפתחו עיניו ופיו פתוח ויסתם טיבורו הפתוח כו' ויבכה מיד בהולדו כו' כנ\"ל.\n<b>והענין</b> הוא דבזמן הגלות שהיו נש\"י בבחי' העיבור כנ\"ל הי' בזה בחי' בירור גדול שהוא מה שהדם נעכר בשעת עיבור ונעשה חלב אחר הלידה להניק לולד כו', והענין הוא למעלה דע\"י מצות מעשיות שהן בחי' מזון לנשמה בהיותה בבחי' עיבור בבחי' נה\"י לבד כנ\"ל, הנה ע\"י מעשה המצות דעכשיו נתברר כמו המאכל שאמו אוכלת שנהפך לדם הוא הנפש כו', ומדם נעשה מזה אור וחיות להאיר בנש\"י בבחי' מוחין",[["2929","357","<b>וטוחן וגורס בשיניו שנק' גירסא</b>: ראה גם לעיל פ' שמות יד, ד ובהערה 646."]]],[2300540708,"דיניקה כמו שהדם נעכר ונעשה חלב בלידה כו'. והוא מה שיהי' גילוי אור הוי' דאצי' ממש בנש\"י בכאו\"א שיראה בעיניו כמו בראיי' חושיי' כמ\"ש כי עין בעין יראו, כולד שנולד שיפתחו עיניו לראות אור העולם שלא ראה בעודו בבטן אמו כו', ואזניו ישמעו בהשג' והתבוננו' בגילוי מקרוב ממש (שלא הי' בחי' ראי' ושמיעה כזו גם במ\"ת רק ראו את הקולות<sup data-n=\"2930\">358</sup> כו' כמ\"ש קול דברים כו' ותמונה אינכם רואים כו' וכן כי לא ראיתם כל תמונה, ובמשיח א' ותמונת ה' יביט כרואה בעין גשמי וכמ\"ש השכל וידוע אותי<sup data-n=\"2931\">359</sup>, כולם ידעו אותי<sup data-n=\"2932\">360</sup> ממש כמ\"ש במ\"א). והיינו בחי' התענוג האלקי שבהשגה והתבוננו' בגדולת ה' שעכשיו הוא בהעלם גדול מרחוק בנשמ', ובימות המשיח שיהי' בחי' לידת הנשמות שיהי' אור הוי' בגילוי גמור בכל נשמה ויקבל כאו\"א אור שפע חיותו האלקי', כילד<sup data-n=\"2933\">361</sup> שיונק מחלב אמו בפיו ונכנס במעיו לחזק המוחי' שלו ומתגדלי' מדותיו וגופו כו'. כך יהי' קיבול יניקת הנשמות גילוי אור אלקות מבחי' חלב דאימא עילאה שהוא בחי' פנימי' התורה, שישכילו באוי\"ר שכליי' וידעו אותי מקטנם<sup data-n=\"2934\">362</sup> כו', ויהי' להם למזון וחיות לחזק בחי' המוחי' ומדות שלהם ויפקחו עינים לראות באור פני מלך<sup data-n=\"2935\">363</sup> ואזנים לשמוע כו' (בלי שינוי כלל כל היום באור פניו יהלכון<sup data-n=\"2936\">364</sup> כו'). ויקבלו השפע הפנימי' הזאת דרך הפה כמו שעכשיו מקבל אדם מזון הנשמה בפיו בדברו בד\"ת כו', ומזה נעשה בחי' הגדלת החומר של המדות והמוחין שנק' מוחין דיניקה כו' וכמ\"ש אז יאמרו בגוים<sup data-n=\"2937\">365</sup> הגדיל ה' לעשות עם אלה כו' בבחי' גדלות דמוחי' דיניקה כו', שיתגדלו נש\"י משם הוי' מבחי' פנימי' התורה שנק' חלב דאימא עילאה כמו דבש וחלב תחת לשונך<sup data-n=\"2938\">366</sup> כו' שהן טעמי מצות כידוע כמ\"ש ישקני מנשיקות פיהו<sup data-n=\"2939\">367</sup> כו', וזה לא יהי' לע\"ל רק מבחי' הבירורים שבזמן הגלות שנק' עיבור שהדם נעכר ונעשה חלב כנ\"ל, והיינו ענין מעשה המצות שבבחי' קטנות דנה\"י כו' וכנ\"ל, מזה דוקא נעכר ונעשה בחי' חלב דאימא להגדיל המוחי' דנש\"י ומדות דאוי\"ר בבחי' גילוי דשם הוי' מקרוב ממש בראי' עיני'<sup data-n=\"2940\">368</sup> ושמיע' אזן ולבבו יבין ויכיר לבורא בהכרה חושיי' כנ\"ל כמו שא' וידע כ\"פ<sup data-n=\"2941\">369</sup> כו' ויבין כל יצור כו', לפי שלע\"ל נא' ונגלה כבוד ה' וראו כ\"ב כו' מצד עוצם גילוי אור הוי' דבחי' סוכ\"ע בכל העולמות ובנש\"י יותר מהכל מפני שהן היו בבחי' עיבור תחלה בגלות וכמ\"ש העם ההולכים בחשך<sup data-n=\"2942\">370</sup> דוקא ראו אור גדול בימי משיח שנק' לידה כמ\"ש כמו <span data-k=\"pg\">198</span> ּ הרה תקריב ללדת כו' כן הרינו חלנו מפניך ה' בזמן הגלות שנק' עיבור כנ\"ל וד\"ל.",[["2930","358","<b>ראו את הקולות</b>: יתרו כ, טו."],["2931","359","<b>השכל וידוע אותי</b>: ירמי' ט, כג."],["2932","360","<b>כולם ידעו אותי</b>: ירמי' לא, לג."],["2933","361","<b>כילד</b>: אה: כולד. וראה גם לעיל הערה 331."],["2934","362","<b>וידעו אותי מקטנם</b>: ע\"פ ירמי' לא, לג."],["2935","363","<b>באור פני מלך</b>: משלי טז, טו."],["2936","364","<b>באור פניו יהלכון</b>: ע\"פ תהלים פט, טז."],["2937","365","<b>אז יאמרו בגוים</b>: תהלים קכו, ב."],["2938","366","<b>דבש וחלב תחת לשונך</b>: שה\"ש ד, יא. ראה גם מאמרי אדה\"א שמות ח\"א ע' עז. וש\"נ. ח\"ב ע' תנט."],["2939","367","<b>ישקני מנשיקות פיהו</b>: שה\"ש א, ב. ראה גם מאמרי אדה\"א דברים ח\"ד ס\"ע א'תעג ואילך."],["2940","368","<b>עיני'</b>: א: עין."],["2941","369","<b>וידע כ\"פ</b>: תפלת העמידה לר\"ה."],["2942","370","<b>העם ההולכים בחשך</b>: ישעי' ט, א."]]],[2300540720,"<b>והנה</b> מבואר למעלה במשל הולד כשנולד כו' שהוא כמו היוצא מבית האסורים שישב שם בלחץ ודחק כמה שנים שיבכה מיד בצאתו מחמת חדוה שנפתחו עיניו ורואה אור העולם כו', ומחמת עוצב דהיינו על העבר שהי' לו עד כה ממה שעבר עליו בהיותו במאסר בעיבור ראשו בין ברכיו כו' ואשר נלחץ בצאתו מרחם אמו כו', והחלב שיונק תשמחנו ותנחמנו כו' כנ\"ל. והנמשל מכ\"ז יובן ג\"כ למעלה ע\"ד הנ\"ל בנש\"י בהיותם בגלות שאין בהם גילוי אלקות כלל במוח ולב וראי' ושמיעה כו' כולד שנלחץ בבטן וראשו בין ברכיו כו' שמקבל רק בבחי' נה\"י שבו, וכך הוא בכנ\"י בגלות שאין בהם רק בחי' אוי\"ר הטבעיי' לענין מעשה לבד כנ\"ל (וכמו בשינה שמסתלק השכל והמדות רק נשאר תנועת חיצוניות האברים כו' כמ\"ש אני ישינה בגלותא<sup data-n=\"2943\">371</sup> כו'), וכשיהי' הגאולה שנק' לידה שאז יתגלה שם הוי' בנש\"י מקרוב בראי' ושמיעה ובמוח ולב בגדלו' המוחי' ומדות כו' אז יבכו מרוב החדוה שראו אור ה' אור העולם, וגם תהי' בכי' זו בעצבות ומרירות על העבר זה זמן רב שהלכו בחושך ולא ראו מאורות מימיהם, ומה זאת הי' להם שנלחצו וישבו במאסר בחשך שנסתמו העינים והאזנים ולבבם לא הבין כל ימי הגלות (או כמו הניעור מן השינה שיפקחו עיניו ושכלו ומדותיו ויתפלא על החלומות שחלם כו', וכמ\"ש אז היינו כחולמים<sup data-n=\"2944\">372</sup> כו', דשינה ועיבור ענין א' הוא בבחי' הגלות<sup data-n=\"2945\">373</sup> כידוע). וזהו הלוך ובכה יהלכו ואת ה' אלקי' יבקשו<sup data-n=\"2946\">374</sup> כו' כמו עד\"מ התינוק מיד בהולדו שיבכה על הצער שעבר עליו ואשר נלחץ בצאתו כו', וכך בגאולת כנ\"י שקדמו תחלה חבלי לידה שנק' חבלי משיח<sup data-n=\"2947\">375</sup> בצרות רבות ורעות בלחץ ודחק (כמו קדרותא דצפרא<sup data-n=\"2948\">376</sup> שקודם אור השחר), שיציאתם מן הגלות יהי' כיציאת הולד מתוך דוחק ולחץ גדול כמ\"ש כמו הרה תקריב ללדת, שזהו סמוך ללידה ממש, תחיל תזעק בחבלי'<sup data-n=\"2949\">377</sup> כן הרינו חלנו כו', וע\"כ א' הלוך ובכה יהלכו ועכ\"ז הוי' אלקי' יבקשו לדעת את ה' בבחי' ראי' מקרוב דוקא כי נפתחו עיניהם לראות באור הוי' כולד הנולד כנ\"ל וד\"ל.\n<b>וזהו</b> וארא אל אברהם כו' באל שדי כו', כי הנה מבואר מכל הנ\"ל במשל העיבור שבזמן הגלות הרי כללות נש\"י<sup data-n=\"2950\">378</sup> שהן כלולים מג' אבות שנק' שרש הראשון שלהם בשרש<sup data-n=\"2951\">379</sup> האילן כנ\"ל, הרי הם עדיין בבחי' עיבור בקטנות דנה\"י לבד כו'. ומבואר למעלה שיש בפי' וארא ב' אופנים א' לשעבר והב' להבא, ומה שא' וארא לעבר היינו מה שכבר נתגלה לאבות והן",[["2943","371","<b>אני ישינה בגלותא</b>: נסמן לעיל לז, ד."],["2944","372","<b>אז היינו כחולמים</b>: תהלים קכו, א [היינו כחולמים]. ב [אז]."],["2945","373","<b>דשינה ועיבור. . הגלות</b>: ראה גם לעיל פ' שמות כה, א ובהערה 64."],["2946","374","<b>הלוך ובכה. . יבקשו</b>: ירמי' נ, ד [ושם: ובכו ילכו. . אלקיהם. אגה: הלוך ילך ובכה. וראה לקמן הערה 404. במאמרי אדה\"ז תקס\"ב (כאן ע' קלו): הלוך ובכה ילכו ואת ה' אלקינו יבקשו. מארז\"ל (ע' קלב): הלך ילך בבכי. . אלקיו]."],["2947","375","<b>חבלי משיח</b>: ראה שבת קיח, א. סנהדרין צח, ב. מאמרי אדה\"א קונטרסים ע' רכג."],["2948","376","<b>קדרותא דצפרא</b>: זהר בראשית מ, ב. וישלח קע, א. ראה גם שע\"ת קיט, א. מאמרי אדה\"א קונטרסים ע' רלו."],["2949","377","<b>תחיל תזעק בחבלי'</b>: המשך הכתוב כמו הרה תקריב ללדת — ישעי' כו, יז."],["2950","378","<b>כללות נש\"י</b>: א: כנס\"י. ראה לעיל הערה 340."],["2951","379","<b>בשרש</b>: אה: כשרש."]]],[2300540732,"כללות נש\"י שכלולי' באבות בבחי' עיבור בגלות כמו הביטו אל צור חוצבתם כו' אל אברהם אביכם ושרה תחוללכם כו', שנמשך מן השרש [א]ל הענפים. והוא מה שיש בכח והעלם בכאו\"א כמו טבע בנפשו האלקי' בחי' האהבה הטבעי' הנמשכת כמים שטבע המים לדבק<sup data-n=\"2952\">380</sup> כו', והוא בחי' אהבה הטבעיות שיש בכל ניצוץ הקטן מישראל לימשך לבו ודעתו וכל נקודת רצונו אחרי ה' בדביקות והתקשרות האמיתי' בל תמוט לעולם. וזהו הכח המוטבע בנפש כאו\"א מאה\"ר דאברהם אוהבי<sup data-n=\"2953\">381</sup> כו' כנ\"ל שהי' בבחי' מרכבה ממש באצי' (וע\"כ יש כח בכל א' למס\"נ על קדה\"ש בנסיון ולעשות<sup data-n=\"2954\">382</sup> <span data-k=\"pg\">צט</span> ּ תשובה שלימה במס\"נ לפרקים כמו בעשי\"ת וכה\"ג) זהו<sup data-n=\"2955\">383</sup> מבחי' יצחק כו') והוא הנק' בשם אהבה המסותרת כידוע, והמדה הב' הוא בחי' התפעלות היראה ופחד אלקי' שנופל בלב כאו\"א לפרקים עד שמאד ירגיז על נפשו ויתמרמר בלבו מאד בעוצב ורוגז גדול ע\"ע על אשר נתרחק כ\"כ מה' אחד ונשא נפשו לריק והבל כו' בפירוד וריחוק עצום מאלקים חיים ע\"י שנטמא נפשו בכל תועבה כו'. ויש בהתפעלו' מרירות אמיתי' זו מבחי' החמימות ברשפי אש ממש, וזהו שנק' בחי' גבורו' דקדושה היפוך האהבה טבעיות שנמשך בקרירות כמים (שנק' קלעפ<sup data-n=\"2956\">384</sup> בל\"א שהוא המשכת הלב והתקשרותו לדבר האהוב ביותר). וגם זה הכח מושרש כמו טבע ממש בנפש כאו\"א מישראל (והוא מה שיפול בלב כל אדם הרהורי תשובה אמיתי' בלב נשבר ומרירות גדולה וכמו בעי\"ת עד שיבכה במר נפשו כו'). ובחי' ומדרגה הג' היא מדתו של יעקב שהוא בחי' הרחמים שגם זה מושרש כמו טבעיות ממש בנפש כאו\"א, והוא מה שאחר המרירות ועצבון ורוגז גדול על נפשו כנ\"ל יבא לכלל בכי' בדמעות לעורר ולהמשיך על נפשו הנשחתה ונתרחקה כ\"כ ממקור הרחמים העליוני' רחמים רבים שיקובל בתשובה ולא ידח ממנו נדח<sup data-n=\"2957\">385</sup> כו' כידוע וד\"ל.\n<b>והנה</b> ג' מדות הטבעיי' הנ\"ל אוי\"ר ורחמים שמושרשי' בתולדו' הנשמות בבטן מצד הירושה מאבות כנ\"ל זהו שעומד וקיים לזקנת האדם כשגדל בחכמה דתורה ומע\"ט ובעבודה שבמוח ולב בתכלית העילוי כו', או להיפך כאשר [גם] יתרחק ביותר יש בכח האוי\"ר ורחמים מכח האבות הנ\"ל להחזירו וכמ\"ש ובאו האובדים<sup data-n=\"2958\">386</sup> כו' ולא ידח ממנו נדח (וכמ\"ש אז תעבורנה הצאן<sup data-n=\"2959\">387</sup> ע\"י מונה כו' וד\"ל). ואמנם בהיותם בגלות מצרים הי' כל זה בבחי' קטנות דעיבור בכח והעלם גדול, אך בגאולה דגלות מצרים יצאו נש\"י בבחי' לידה כולד שנולד שנפקחו עיניו ושכלו ולבו כו' כנ\"ל. וזהו פי' וארא אל אברהם כו' בבחי' התגלות שם הוי' בנש\"י בבחי' לידה (שכאשר נשלח",[["2952","380","<b>שטבע המים לדבק</b>: ראה גם לקמן פ' בשלח רכה, א. הנסמן במ\"מ לשע\"ת לח, ב."],["2953","381","<b>דאברהם אוהבי</b>: ישעי' מא, ח."],["2954","382","<b>בנסיון ולעשות</b>: א: (ולעשות. גד: בנסיון) (ולעשות. וראה הערה הבאה."],["2955","383","<b>זהו</b>: ג: (שזהו. ד: שזהו. ה: (זהו. וראה הערה שלפנ\"ז."],["2956","384","<b>קלעפ</b>: ראה גם לקמן פ' תצוה שעח, ג. ויקהל תי, א. שע\"ת ג, ג. ז, ב. שעה\"י קי, א. קיא, א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670348\" data-slug=\"torat-chaim\" data-id=\"2300670348\">תו\"ח בראשית לט, ב</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680122\" data-slug=\"torat-chaim\" data-id=\"2300680122\">תולדות קנ, סע\"ג</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680302\" data-slug=\"torat-chaim\" data-id=\"2300680302\">וישב רט, ב</a> ורע\"ג. מאמרי אדה\"א קונטרסים ע' קעא וע' קפ."],["2957","385","<b>ולא ידח ממנו נדח</b>: ע\"פ שמואל-ב יד, יד."],["2958","386","<b>ובאו האובדים</b>: ישעי' כז, יג."],["2959","387","<b>אז תעבורנה הצאן</b>: ירמי' לג, יג [ושם: עוד תעבורנה — ראה לקמן פ' בשלח רלא, ב. משפטים רפה, ד. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680046\" data-slug=\"torat-chaim\" data-id=\"2300680046\">תו\"ח וישלח קפ, ד</a> הערה 26]."]]],[2300540744,"משה אליהם וא' משה לה' כשיאמרו לי מה שמו<sup data-n=\"2960\">388</sup> מה אומר אליהם ויאמר אלקים כו' אהי' אשר אהי' שלחני אליכם<sup data-n=\"2961\">389</sup> אהי' אנא זמין לאולדא בגאולה זו דמצרים ואשר אהי' בגאולה האחרונה דמשיח כו', ואח\"כ א' למשה כה תאמר הוי' אלקי אבותיכם אלקי אברהם כו' שלחני אליכם זה שמי לעלם<sup data-n=\"2962\">390</sup> כו' וד\"ל). והענין הוא דלאחר שכבר נתגלה ונתראה לאברהם כו' כשהיו נש\"י בבחי' עיבור הנה הי' מזה תועלת לבחי' הלידה בגאולה זו דמצרים וכמ\"ש ואעבור עליך ואראך מתבוססת בדמיך כו' ואומר לך בדמייך חיי<sup data-n=\"2963\">391</sup> כו'. כי הנה כמו שדם נעכר ונעשה חלב בשעת לידה, כך הוא ענין עכירת הדם בעיבור ולידה בנש\"י שנהפך לחלב, והוא כמו ענין המרירות ועצבון דנשמה האלקי' שירגיז על נפשו שהוא עכירת הדם כמו מי שבמרירות עצומה יהיו פניו רעים בלקותא שבדמים, אבל אח\"כ כשמתקרב לה<sup data-n=\"2964\">392</sup> בהשגה האלקי', המרירות דוקא תגרום שישמח ויתענג על ה' בהשגה והתבוננו' בחדוה ושמחת הלב במורגש החיות באלקות ביותר, כידוע לכל עובדי ה' בתמים שממש לפ\"ע המרירות ולב נשבר שבתחלה כך יהי' ערך החדוה ועונג בהתבוננו' בטוב טעם וחיות. ואם לא <span data-k=\"pg\">200</span> ּ הי' המרירות כ\"כ בתחלה לא הי' התענוג וחדוה בהתבוננות כ\"כ, וכמ\"ש בזהר דבכי' תקועא<sup data-n=\"2965\">393</sup> מסט' דא וחדוה מסט' דא כו', משום דעכירת הדם שע\"י המרירות העצומה בריחוקו מה' הוא שנהפך לבחי' חלב שהוא בחי' חלב דאימא עילאה אם הבנים דנש\"י. והוא בחי' התענוג שבהשגו' אלקות שנק' חלב אימא עילאה (כמו פנימי' ורזין דאוריי' כו'), שנשמות הנולדי' יונקי' מחלב האם שיוסיף להם הגדלו' המוחי' ומדות כו' וכמו שא' מי יתנך<sup data-n=\"2966\">394</sup> כאח לי יונק שדי אמי מתושב\"כ ושבע\"פ כו'. וכמו עד\"מ תינוק הנולד שיונק החלב משדי אמו שהעיקר הוא מה שטועם טעם בהרגשה בחיך בחלב זה, והוא עיקר העונג שלו שמוסיף לו יניקה זו גדלות המוחי' ומדות (והיינו שיהי' גידול החומר של המוחי' שיומשך מהם גם גדלות המדות בתינוק אח\"כ בימי הגדלות שיקבל הצורה השכלי' בחומר כו' (לאחר השלמת ימי היניקה כמ\"ש<sup data-n=\"2967\">395</sup> במ\"א). וכך הוא בבחי' היניקה דנשמה בחלב העליון שהוא בחי' ההשגה האלקי' עצמה דבחי' מוחי' דאימא שבא' בטעם מורגש לנשמה שתשמח בה ותרגיש בהרגשה טוב טעם אור וחיות אלקי (שיבא מזה בחי' גידול מוחי' דחב\"ד וגידול המדות בבחי' החומר שלהם שיוכלו לקבל הצורה דמוחי' דגדלות דאו\"א כו'). ולא שהחלב הזה שיונק התינוק נעשו לו מוחי' ממש, אלא טעם חיות רוחני שמרגיש ביניקת החלב הזה הוא שעושה הגדלת החומר דמוחי' וחומר המדות והגדלת גשם האברים בלבד שיהי' כלי מוכן לקבל אחר היניקה גידול אור השכל וגידול צור' המדות",[["2960","388","<b>מה שמו</b>: שמות ג, יג."],["2961","389","<b>ויאמר. . אליכם</b>: שמות שם, יד [בדילוג]."],["2962","390","<b>כה תאמר. . לעלם</b>: שם ג, טו [בדילוג]."],["2963","391","<b>ואומר לך בדמייך חיי</b>: המשך הכתוב ואעבור עליך (יחזקאל טז, ו)."],["2964","392","<b>לה</b>: א: לה'."],["2965","393","<b>דבכי' תקועא </b>[א: תקיעא]: ראה זהר אחרי עה, א. (היכלות) פקודי רנה, א. <a class=\"ft-cite\" href=\"#/read/tanya/3401310039\" data-slug=\"tanya\" data-id=\"3401310039\">תניא</a> <a class=\"ft-cite\" href=\"#/read/tanya/3401310039\" data-slug=\"tanya\" data-id=\"3401310039\">ספל\"ד. שע\"ת ב, א</a> ובהערה 44. לקמן פ' תצוה שכב, ד."],["2966","394","<b>מי יתנך</b>: שה\"ש ח, א."],["2967","395","<b>(לאחר. . כמ\"ש</b>: אגד: לאחר. . ד: (כמ\"ש. וראה הערה הבאה."]]],[2300540756,"וצורת האברים כו')<sup data-n=\"2968\">396</sup>. וכדוגמא זאת יובן ביניקה דנשמה מחלב אימא עילאה בגילוי אור האלקי עליהם בגאולה דמצרים כשנגלה עליהם מלך כו' בגילוי שכינה ממש שע\"ז א' ואומר לך בדמייך [חיי] דוקא, לפי שע\"י הדם כשנעכר ונעשה חלב דאימא כו' והוא בחי' המרירות העצומה דוימררו את חייהם דכנ\"י בעב\"ק כנ\"ל במרירות דנשמ' מן הריחוק העצום, שזה דוקא גורם שנהפך לשמחה וחדוה ביניקה דחלב אמו כו' וד\"ל.\n<b>וזהו</b> שנמשל לתינוק שנולד שבוכה מאד על מה שעבר עליו ונותנים לו מעט מחלב אמו ושותק כו', שענין בכי' זו מצד שלא ראה מאורות מימיו בבטן אמו, וכמו\"כ היו נש\"י באפילה בגלות מצרים. ובחי' המרירות הזה שהוא בחי' גבו' דיצחק כנ\"ל דם נעכר, מיד נהפך לחלב שזהו שנותנים לו חלב אמו שנעשה מעכירת הדם במרירות זו שבוכה, ומיד שיונק משדי אמו חלב מעט זה תנחמנו מעצבונו ושותק וד\"ל. וזהו כאיש אשר אמו תנחמנו<sup data-n=\"2969\">397</sup> כו' (וקאי לע\"ל בימות המשיח שיהי' גאולה שני' בבחי' לידה מעיבור דגלות זה האחרון וכמ\"ש עד יעבור<sup data-n=\"2970\">398</sup> כו', שבחי' מרירות כזאת הנמשך משך זמן רב כזה בגלות האחרון בכל צרת ישראל בצעקתם בצר להם בכל דור ודור ובמרירות שבלב בתפלה שצעק לבם אל ה'<sup data-n=\"2971\">399</sup> כו', דם נעכר במרירות הגלות (עד שנעשה לקותא בפנים כמ\"ש שחורה אני בגלותא<sup data-n=\"2972\">400</sup> דבני אמי נחרו בי<sup data-n=\"2973\">401</sup> כו') ונעשה חלב אימא עילאה בפנימי' בינה עילאה והן טעמי מצות ברזין ומתיקות חלב דתורה שבימות המשיח כמ\"ש ולא ילמדו כו' כולם ידעו אותי כו'. ועדיין זהו רק בחי' מוחין דיניקה שיהי' החומר דמוחין ומדות מוכנים לקבל הצורה דגדלות המוחין שזה יהי' העוה\"ב אחר תחה\"מ שיקימנו ונחי' לפניו כו'. וז\"ש <span data-k=\"pg\">ק</span> ּ אהי' אנא זמין לאולדא בלידה ב' בגאולה דמשיח אשר אהי' בעוה\"ב בבחי' גדלות המוחי' דתו\"מ כמו שהן במהו\"ע ממש כו' (כמשי\"ת). ולפי אופן זה הי' בחי' עיבור ולידה בגאולה דגלות מצרים (כמ\"ש כימי צאתך מאמ\"צ אראנו נפלאות לע\"ל וכמ\"ש עד יעבור סתם עם זו קנית בעוה\"ב), שהי' בלידה זו דמצרים ג\"כ בחי' מוחי' דיניקה שיהי' מזה הגדלות חומר המדות ומוחי' דכנ\"י שיהי' יכולים לקבל הצורה דגדלות המוחי' במ\"ת בבחי' דיבור פב\"פ כו' בדברי תורה דוקא (שהוא בחי' גדלות שני דאור אבא כמ\"ש במ\"א (וכמשי\"ת), ונמצא שגוף סיבת מציא' בחי' החלב דאימא נעשה מבחי' גבורו' דיצחק מן הדם שנעכר במרירות כנ\"ל (וז\"ש ליצחק כי אתה אבינו<sup data-n=\"2974\">402</sup> שגרם הצחוק וחדוה שלע\"ל דכתי' אז ימלא<sup data-n=\"2975\">403</sup> שחוק פינו ולשוננו רינה אז יאמרו בגוים הגדיל ה' לעשות עם אלה בגדלות החומר דמדות ומוחי' ע\"י יניקה דחלב כו', אבל הבכי' דתינוק הנולד זהו",[["2968","396","<b>כו')</b>: אד: כו'. וראה הערה שלפ\"ז."],["2969","397","<b>כאיש אשר אמו תנחמנו</b>: ישעי' סו, יג."],["2970","398","<b>עד יעבור</b>: בשלח טו, טז."],["2971","399","<b>שצעק לבם אל ה'</b>: איכה ב, יח."],["2972","400","<b>שחורה אני בגלותא</b>: שה\"ש א, ה. וראה זהר אחרי נט, ב [וכן צ\"ל במאמרי אדה\"א בראשית ע' קכ]."],["2973","401","<b>דבני אמי נחרו בי</b>: שה\"ש שם, ו."],["2974","402","<b>ליצחק כי אתה אבינו</b>: שבת פט, ב. ישעי' סג, טז."],["2975","403","<b>אז ימלא</b>: תהלים קכו, ב."]]],[2300540768,"שמעורר ר\"ר בחי' יעקב עי\"ז וכמ\"ש הלוך ובכה יהלכו<sup data-n=\"2976\">404</sup> כו' ויניקת החלב דאמו תנחמנו בבכי' זו כו' וד\"ל.\n<b>וזהו</b> וארא אל אברהם כו' ושמי הוי' לא נודעתי להם, פי' וארא לעבר שהיו בבחי' עיבור ונראית להם בעת הגאולה בבחי' לידה כנ\"ל<sup data-n=\"2977\">405</sup>. וזהו שא' באל שדי מלשון שדים<sup data-n=\"2978\">406</sup> היונקים לולד מפני שכבר הוכן בחי' חלב בשדים דאימא ע\"י דם הנעכר בגלות ונעשה חלב כו'. וזהו שדים שעשה לה דדים במקום בינה<sup data-n=\"2979\">407</sup> שבלב כו' שזה בחי' התענוג שבהשגה והתבוננו' דבחי' בינה אימא עילאה, וזהו שעשה לה דדים במקום בינה שבלב דוקא להשפיע חלב לתינוק שזהו בחי' חלב דאוריי' בטעמי התורה לנש\"י שיהי' עי\"ז מוכנים למ\"ת פב\"פ ממש כנ\"ל וד\"ל. ועד\"ז יהי' בעלי' שנית בגאולה אחרונה דמשיח שע\"י מצות מעשיות שעושים עכשיו בגשמיות שזהו בחי' הבירורי' דק\"נ שהוא ענין דם נעכר, וכמו דם שנהפך למאכל כו', וזהו ישראל מפרנסי' כו'. והוא מה שאנו או' אשר קדשנו במצותיו למטה בהלבשה גשמיות, וקדשנו במצותיו משמע שהוא עושה בעצמו כנ\"ל. והוא מה שיקדשנו במצותיו ממש לע\"ל שיהי' מצות שלנו כמו מצותיו ממש, כמו שהקב\"ה מניח תפילין ומתעטף בציצית וכה\"ג כל המצות שנק' מצות הוי' ממש או אורחות הוי'<sup data-n=\"2980\">408</sup> ממש, שזה יהי' גילוי אור דבחי' מוחי' דיניקה בחי' חלב דאימא עילאה בימות המשיח בגילוי טעמי' וסודות [ה]מצות [כמו] שהן למעלה באצי' ממש בבחי' פנימי' מוחי' דאו\"א כו' בשביל הגדלות חומר הכלים דמדות דאצי' כו'. וז\"ש יחיינו מיומים<sup data-n=\"2981\">409</sup> דמוחי' דאו\"א בז\"א שנק' ישראל לעילא ולתתא כו', אבל כ\"ז יהי' רק בחי' הכנה לבד לחיי העוה\"ב אחר תחה\"מ (שע\"ז א' [אהי'] אשר אהי' אנא זמין לאתגלאה כנ\"ל), והיינו מ\"ש יקימנו ונחי' לפניו (וכן עם זו קנית ממש כו') שזהו בחי' גדלות המוחי' שלמעלה ממוחין דיניקה שבימות המשיח בגילוי טעמי תו\"מ לבד. והיינו בחי' גילוי עצמו' התענוג ורצון העליון שבמצות שלמעלה מח\"ס שנק' טעם כמוס לרצון<sup data-n=\"2982\">410</sup> כו', והוא העוה\"ב שבא מן המצות עצמן דוקא, דסוף מעשה עבמח\"ת כו' ונתחב\"ס וסב\"ת דוקא כידוע, שע\"ז א' ונחי' לפניו ממש כמו אלה המצות כו' וחי בהם<sup data-n=\"2983\">411</sup> מחיי החיים<sup data-n=\"2984\">412</sup> דא\"ס עצמו, וז\"ש שקדשנו במצותיו ממש וד\"ל.\n<span data-k=\"pg\">202</span> ּ<b>וזהו</b> ושמי הוי' לא נודעתי להם, דהנה כמו שמבואר למעלה שיש ג' מדרגות בכלל עיבור יניקה מוחי' כו' בגאולה אחרונה עד העוה\"ב, כך הי' ג' מדרגות כאלה בגאולה ראשונה מגלות מצרים. שגלות מצרים הי' בבחי' עיבור כנ\"ל, והגאולה משם הי' בבחי' לידה שאז התחיל בחי' מוחי' דיניקה (שהן מ\"ט",[["2976","404","<b>הלוך ובכה יהלכו</b>: וכ\"ה באגד. וראה לעיל הערה 374."],["2977","405","<b>וזהו וארא. . כנ\"ל</b>: אגד: ליתא."],["2978","406","<b>שדי מלשון שדים</b>: ראה גם מאמרי אדה\"ז תקס\"ב כאן ס\"ע קלו. מארז\"ל ריש ע' קלג. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370251\" data-slug=\"torah-or\" data-id=\"3901370251\">תו\"א כאן נו, רע\"א</a>."],["2979","407","<b>שעשה לה דדים במקום בינה</b>: ברכות י, א."],["2980","408","<b>אורחות הוי'</b>: נסמן לקמן סט, ד הערה 27."],["2981","409","<b>יחיינו מיומים</b>: הושע ו, ב."],["2982","410","<b>מח\"ס שנק' טעם כמוס לרצון</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380510\" data-slug=\"likkutei-torah\" data-id=\"4001380510\">לקו\"ת שלח מט, ג</a>. הנסמן במאמרי אדה\"א דברים ח\"ד ע' א'שצב."],["2983","411","<b>אלה המצות כו' וחי בהם</b>: נסמן לקמן פ' בשלח קעה, ד."],["2984","412","<b>מחיי החיים</b>: ראה יומא עא, א."]]],[2300540779,"ימי הספירה<sup data-n=\"2985\">413</sup> עד מ\"ת ועד בכלל), ובחי' מוחי' דגדלות הי' בבהמ\"ק דשלמה שהי' בו גילוי שכינה ממש. והוא ע\"י קיום המצות בא\"י דוקא שאז נק' ארץ טובה ורחבה<sup data-n=\"2986\">414</sup> לקבל בחי' מרחב בגילוי עצמות א\"ס שבפנימי' הרצון העליון שבמצות העליונות, כדוגמא דעוה\"ב שהוא שכר המצות שנק' ג\"כ ארץ כמ\"ש לעולם ירשו ארץ<sup data-n=\"2987\">415</sup> ונק' ארץ חפץ<sup data-n=\"2988\">416</sup> כו'. אך תחלה היו כנ\"י בגלות מצרים בבחי' עיבור והעלם דקטנות דנה\"י שהוא אוי\"ר המסותרת הנ\"ל, ובחי' לידה דנש\"י שנפקחו עיניהם כו' שזהו בחי' היניקה דחלב עד שהיו מוכנים לקבלת התורה פב\"פ שזהו בחי' שלימות דיניקה זאת, והוא כמו השגות פנימית התורה בימות המשיח, שהרי עכ\"ד פרחה נשמתן<sup data-n=\"2989\">417</sup> כו' ואנכי ולא יהי' לך מפי הגבורה<sup data-n=\"2990\">418</sup> שמעו בביטול במציאו' ממש ונמשך להם ב' כתרים<sup data-n=\"2991\">419</sup> כו'. ואמנם כ\"ז הי' עדיין רק הכנה לכניסתם לא\"י ששם קיבלו וקימו התו\"מ בפו\"מ שנעוץ תחב\"ס וסוב\"ת, שהוא גילוי עצם הרצון ותענוג העליון שבמצות למעלה שהוא למעלה גם מטעם הכמוס שברצון כו' כנ\"ל בענין העוה\"ב. וזהו שביקש משה ליכנס לא\"י לקיים מצות התלויות בה אע\"פ שכבר קיבל משה התו\"מ בסיני פב\"פ כו'. וזהו בחי' מוחי' דגדלות שאחר תשלום ימי היניקה שהי' במ\"ת ובמדבר דכתי' כאשר ישא האומן<sup data-n=\"2992\">420</sup> את היונק כו' וד\"ל (והוא בחי' יחיד עצמו שלמעלה מאחד (כמשי\"ת<sup data-n=\"2993\">421</sup> ). וזהו שמי הוי' ממש שבתו\"מ בפו\"מ כמו בא\"י ועוה\"ב שאחר קיום המצות בעוה\"ז, וגם לא במ\"ת שהי' בבחי' פב\"פ בגילוי שלימות הגדלות המוחי' ומדות (בבחי' ח\"ס בטעם כמוס לרצון) לא נודעתי לאבות, אע\"פ שהיו מרכבה לחג\"ת דז\"א היינו רק באל שדי שהוא בחי' יניקה דשדים דאימא להאיר רק בבחי' הקטנות דשם הוי' בנש\"י בבחי' לידה במצרים כמ\"ש ואומר לך בדמייך חיי שדם נעכר ונעשה חלב כנ\"ל. וזהו דכתי' רבבה כצמח השדה<sup data-n=\"2994\">422</sup> [נתתיך] כו' בבחי' גידול דעיבור, ותרבי ותגדלי בגדלו' דיניקה, ותבואי בעדי כו' שדים נכונו במ\"ת פב\"פ וד\"ל. וזהו סדר הפסוקים בפ' שמע ואהבת בכל לבבך בשני יצריך דם נעכר במרירות כו' ודם נהפך למאכל לחבר הנשמה בגוף כו'. ואח\"כ והיו הדברים כו' ודברת בם בשלימות",[["2985","413","<b>מ\"ט ימי הספירה</b>: ראה שו\"ע אדה\"ז הל' פסח סת\"צ, ס\"א."],["2986","414","<b>ארץ טובה ורחבה</b>: שמות ג, ח."],["2987","415","<b>לעולם ירשו ארץ</b>: ישעי' ס, כא."],["2988","416","<b>ארץ חפץ</b>: נסמן לעיל פ' שמות כב, ב."],["2989","417","<b>עכ\"ד פרחה נשמתן</b>: ראה שבת פח, ב. מאמרי אדה\"א ויקרא ח\"א ע' ג. נ\"ך ע' שפא ובהנסמן בהנ\"ל. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670525\" data-slug=\"torat-chaim\" data-id=\"2300670525\">תו\"ח בראשית יז, ב</a>."],["2990","418","<b>ואנכי. . מפי הגבורה</b>: מכות כד, א. ראה מו\"נ ח\"ב פל\"ג. <a class=\"ft-cite\" href=\"#/read/tanya/3401310025\" data-slug=\"tanya\" data-id=\"3401310025\">תניא</a> פ\"כ. לקמן פ' פקודי תנא, ג. מאמרי אדה\"א במדבר ח\"ב ע' תתנב. נ\"ך ע' תמז ואילך וע' תקכ ואילך. אוה\"ת יתרו ע' תתקט."],["2991","419","<b>ונמשך להם ב' כתרים</b>: שבת פח, א."],["2992","420","<b>כאשר ישא האומן</b>: בהעלותך יא, יב."],["2993","421","<b>כמשי\"ת</b>: לפנינו ליתא סיום המאמר."],["2994","422","<b>רבבה כצמח השדה</b>: יחזקאל טז, ז."]]],[2300540790,"דמוחי' דיניקה שזהו במצות ת\"ת כמו במ\"ת פב\"פ כו' כנ\"ל, בחי' מ\"ה שבחכמה דתורה בחי' הביטול דחו\"ב שלמעלה מביטול המדות דאוי\"ר כידוע. ואח\"כ וקשרתם כו' שהוקשו כל התו\"מ לתפילין<sup data-n=\"2995\">423</sup> כו' שזהו בחי' המעשה עצמה דמצות שז\"ש<sup data-n=\"2996\">424</sup> אשר אנכי מצוך לעשות<sup data-n=\"2997\">425</sup> כו' והיום לעשותם דוקא ולמחר לקבל שכרם<sup data-n=\"2998\">426</sup> בעוה\"ב כנ\"ל וד\"ל שזהו בחי' מוחי' דגדלות דוקא כנ\"ל (והוא מ\"ש אשר אהי' בעוה\"ב שזהו בחי' יחיד שלמעלה מאחד כמשי\"ת וד\"ל).\nומעתה הנה יש להבין<sup data-n=\"2999\">427</sup>",[["2995","423","<b>וקשרתם. . לתפילין</b>: ואתחנן ו, ח. עקב יא, יח. ראה קידושין לה, א. לקמן פ' פקודי תס, ד. סידור ערב שבת קסד, ב. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061287\" data-slug=\"likkutei-sichot\" data-id=\"1300061287\">לקו\"ש בא (כרך ו) ע' 277</a> בהערה. עקב (כרך ט) ע' 79 בהערה. פורים (כרך כו) ע' 441 בהערה."],["2996","424","<b>שז\"ש</b>: אגה: שרש."],["2997","425","<b>אשר אנכי מצוך לעשות</b>: עקב ח, א. ראה יג, יט [בדילוג]."],["2998","426","<b>והיום לעשותם. . שכרם</b>: נסמן לעיל ו, ד."],["2999","427","<b>ומעתה. . להבין</b>: אגה: ליתא."]]],[2300540058,"<b>בעז\"ה תורת אדמ\"ו שבת וארא שא' בק' דאקשיץ</b>\n<span data-k=\"pg\">קא</span> ּ<b>לכן</b> אמור<sup data-n=\"3000\">1</sup> לבני ישראל אני הוי' והוצאתי אתכם מתחת סבלות מצרים<sup data-n=\"3001\">2</sup> כו', הנה ידוע דאת זה לעומת זה<sup data-n=\"3002\">3</sup> עשה האלקי' וכמו שיש מצרים בקליפה כמו\"כ יש בחי' מצרים בקדושה<sup data-n=\"3003\">4</sup> האלקית. וכדי להבין זאת יש להקדים הפ' מה יפית ומה נעמת<sup data-n=\"3004\">5</sup> אהבה בתענוגים, כי הנה כתיב עבדו את ה' בשמחה<sup data-n=\"3005\">6</sup> וכן תחת אשר לא עבדת<sup data-n=\"3006\">7</sup> [את] ה' בשמחה ו[ב]טוב לבב כו' וכתיב אם הבנים שמחה<sup data-n=\"3007\">8</sup> כו' דמשמע דכנס\"י נק' שמחה, ויש להבין כ\"ז. והענין הוא דאם לבינה תקרא<sup data-n=\"3008\">9</sup>, ואם הבנים<sup data-n=\"3009\">10</sup> ענינו הוא ההתבוננות באלקים חיים ומלך עולם<sup data-n=\"3010\">11</sup> איך שנשגב שמו כו', פי' כמו שם האדם כשנקרא על איזה דבר לומר שאותו הדבר של ראובן הוא וכדומה הנה אין עצמותו של ראובן על אותו הדבר רק שמו בלבד נק' עליו, והיינו שבחי' התפשטות של ראובן הוא על אותו הדבר ולא עצמותו כו'. כי הרי שם האדם אינו עצמות האדם רק בחי' התפשטות שלו<sup data-n=\"3011\">12</sup> לבד כידוע, ועד\"ז הממשלה של המלך על עמו אינו אלא בחי' שם מל' נקראת עליהם<sup data-n=\"3012\">13</sup>, והיינו התפשטות מדת מל' ולא עצמותו כמ\"ש במ\"א. וזהו משל להבין איך דמלכותא דרקיע ג\"כ עד\"ז שמדת מל' ית' הוא המחי' כל",[["3000","1","<b>לכן אמור</b>: מאמר זה הוא מכ\"ק אדה\"ז (נאמר בש\"פ וארא תקס\"ג). ונמצא בג' נוסחאות, הנדפס כאן (הוא הנחת כ\"ק אדה\"א. ונמצא באריכות הביאור במאמרי אדה\"א שמות ח\"א ע' מו ואילך. ועם הערות וכו' מכ\"ק אדמו\"ר הצ\"צ באוה\"ת שמות כרך ז ס\"ע ב'תקצז ואילך). הנחה ב' (מהר\"מ בן כ\"ק אדה\"ז) ונדפסה במאמרי אדה\"ז תקס\"ג ח\"א ע' קו. הנחה ג' הנדפסה ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370256\" data-slug=\"torah-or\" data-id=\"3901370256\">תו\"א פרשתנו נז, ב</a> (והערות וכו' מהצ\"צ ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316300171\" data-slug=\"or-hatorah-hb\" data-id=\"8316300171\">אוה\"ת שמות כרך א ס\"ע קעא</a> ואילך. ע' רמ ואילך. ע' רסד ואילך). וראה עוד ע\"ד המאמר להלן ברשימת הכת\"י [ושם מפורט ג\"כ סימני האותיות הבאים להלן בהמראי מקומות]."],["3001","2","<b>לכן אמור. . מצרים</b>: וארא ו, ו."],["3002","3","<b>דאת זה לעומת זה</b>: נסמן לעיל פ' שמות לד, ג."],["3003","4","<b>מצרים בקדושה</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370224\" data-slug=\"torah-or\" data-id=\"3901370224\">תו\"א שמות מט, סע\"ד</a>. אוה\"ת כאן (ע' רמ ס\"ג)."],["3004","5","<b>מה יפית ומה נעמת</b>: שה\"ש ז, ז."],["3005","6","<b>עבדו את ה' בשמחה</b>: תהלים ק, ב."],["3006","7","<b>תחת אשר לא עבדת</b>: תבוא כח, מז [ושם: ה\"א]."],["3007","8","<b>אם הבנים שמחה</b>: תהלים קיג, ט."],["3008","9","<b>דאם לבינה תקרא</b>: משלי ב, ג. ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600547\" data-slug=\"or-hatorah-hb\" data-id=\"8316600547\">אוה\"ת משלי כרך א ע' תקמז</a>."],["3009","10","<b>לבינה. . ואם הבנים</b>: נסמן לעיל פ' שמות יז, א."],["3010","11","<b>באלקים חיים ומלך עולם</b>: ע\"פ ברכת יוצר."],["3011","12","<b>שם. . התפשטות שלו</b>: ראה גם מאמרי אדה\"ז על ענינים ע' תיב. מאמרי אדה\"א שמות ח\"א ע' מח. וש\"נ. קונטרסים ס\"ע תקס ואילך. לקמן פ' בא קיג, א."],["3012","13","<b>המלך. . שם מל' נקראת עליהם</b>: ראה גם מאמרי אדה\"ז תקס\"ה ח\"א ע' יב."]]],[2300540096,"הנבראים מאין ליש כידוע אין הארה זו רק בחי' התפשטו' האצי' ולא מן בחי' העצמו' כו', והיינו בחי' שם מל' לבד שנק' שמו ית' עליהם בזה המה חיים וקיימים תמיד כו'. וזהו מלכותך מל' כל עולמים<sup data-n=\"3013\">14</sup>, פי' בבחי' התפשטו' שם מל' בזה אתה מחי' את כולם<sup data-n=\"3014\">15</sup> ואתה מל' כ\"ע מאין ליש כו', וכן ענין יחיד חי העולמים מלך<sup data-n=\"3015\">16</sup>, פי' במה הוא חי העולמים כולם מאין ליש, במה שהוא נק' מלך עליהם לבד כו'. ואמנם כי נשגב שמו לבדו<sup data-n=\"3016\">17</sup> פי' גם שם התפשטו' מדת מל' הוא בבחי' [ה]אצי' גם קודם שנק' שמו עליהם, וע\"כ גם לאחר שנתפשט שמו עליהם אין ערוך כלל בין בורא לנברא ונשגב שמו ומרומם ומובדל ומתנשא עליהם כו' כמו קודם שנברא העולם ממש באין שינוי כלל וכמ\"ש אני הוי' לא שניתי<sup data-n=\"3017\">18</sup> וכמ\"ש במ\"א. וזהו ומביא גואל לבני בניהם למען שמו באהבה<sup data-n=\"3018\">19</sup>, פי' מה שמביא גאולה ושפע חיות לג\"ע עליון ותחתון ארץ ושמים עליונים כו' רק למען התפשטות שמו אשר נק' עליהם, אבל מצד הנבראים מאחר שאין ערוך כלל לבלתי בע\"ג עם בע\"ג כלא חשיבי ממש ולא הי' התעוררות השפע אליהם כלל כו', ואמנם רק למען אהבת שמו כי הי'<sup data-n=\"3019\">20</sup> אחת מצלעותיו מביא גואל להם וד\"ל.\n<b>והנה</b> כל התבוננות כזה באיכות רוממות הבורא ואיך שנשגב שמו לבדו כו' הוא בבחי' בינה שבנפש האלקי' כו' כי אם לבינה תקרא. ואמנם לפעמים הגם שמתבונן בנפשו ומתיישבת רוממות ה' במוחו והשגתו, אין ההתפעלות של אהבה או יראה כלל בגילוי בלבבו, כ\"א שנשאר ההתפעלות במוחו לבד, וה\"ז כמשל הולד בבטן אמו שישנו במציאות רק שאינו יכול להגלות ולצאת לאויר העולם כי חבלי הלידה מעכבים אותו כו'. וכמו\"כ ההתפעלות במוח והשגה הוא הולד אהוי\"ר אך הם מכוסים ונעלמים בבחי' עיבור במעי אימא כו', והמעכב את גילויי' בלב הוא פרעה <span data-k=\"pg\">204</span> ּ עורף<sup data-n=\"3020\">21</sup> דקליפה כו' וכמ\"ש במ\"א, וכשההתפעלות המוח מתגלית בנקודת הלב אזי כתי' אם הבנים שמחה פי' שיצא מן המיצר [שבבחי' עיבור לגילוי בלב שנק' בשם לידה כו', וזהו ענין מצרים דקדושה שהוא בחי' מיצר<sup data-n=\"3021\">22</sup> הגרון המפסיק בין] המוח ללב ושם הי[ו] התפעלות המדות בצמצום גדול ובהעלם עד שנתגלו בלב כו' וד\"ל. ומה שנק' בשם שמחה הוא להיות כי בשמחה נמתקין כל הדינין<sup data-n=\"3022\">23</sup> וצמצומי' כמשל מלך בו\"ד כשיש לו איזה שמחה אזי יוצא הוא מהיכלו וחדריו הפנימי' ומתגלה לכל רואיו בשער חצירו ואזי גם נמחלים כל החטאים לעוברים",[["3013","14","<b>מלכותך מל' כל עולמים</b>: תהלים קמה, יג."],["3014","15","<b>אתה מחי' את כולם</b>: נחמי' ט, ו."],["3015","16","<b>יחיד חי העולמים מלך</b>: נוסח ברוך שאמר. ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370151\" data-slug=\"torah-or\" data-id=\"3901370151\">תו\"א מקץ לב, ג</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370183\" data-slug=\"torah-or\" data-id=\"3901370183\">מ, ג</a>. סידור שחרית לב, ד. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380623\" data-slug=\"likkutei-torah\" data-id=\"4001380623\">לקו\"ת פינחס עה, ד</a>. מאמרי אדה\"ז תקס\"ח ח\"ב ע' תרנ."],["3016","17","<b>כי נשגב שמו לבדו</b>: תהלים קמח, יג. ראה גם לעיל נא, ד. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תשל."],["3017","18","<b>אני הוי' לא שניתי</b>: מלאכי ג, ו."],["3018","19","<b>ומביא גואל. . באהבה</b>: נוסח שמו\"ע."],["3019","20","<b>הי'</b>: אד: הוא. באוה\"ת כאן (ס\"ע ב'תקצח) היא."],["3020","21","<b>פרעה. . עורף</b>: ראה גם לעיל פ' שמות יט, ב ובהנסמן במ\"מ לשם."],["3021","22","<b>בחי' מיצר</b>: ניתוסף ע\"פ: ד."],["3022","23","<b>בשמחה נמתקין כל הדינין</b>: ראה גם סידור סדר סעודת שבת רג, ג. ביאוה\"ז ויחי לד, א ואילך. שמיני סו, ב. תו\"א ח\"ש טו, ד. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' ת. לקמן פה, ג. פ' פקודי תמט, ב."]]],[2300540134,"ופושעים ומורדים כו'. ונמצא השמחה הוא הגילוי מן ההעלם וגם ההמתקה של הדיני' וצמצומים כו', וכמ\"כ עד\"מ כללות נש\"י בהתגלות אהוי\"ר מבינה שבנפש מאחר שהיו תחלה במיצר<sup data-n=\"3023\">24</sup> ומצוק כו' כתיב אם הבנים שמחה וד\"ל. וזהו הטעם דכתיב עבדו את ה' בשמחה דוקא שהוא גילוי אלקות בנקודת הלב לאחר היציאה מן המיצר כנ\"ל, וזה שארז\"ל בכל פ' העיבור<sup data-n=\"3024\">25</sup>, אפי' בשעה שאתה מתמלא עליהם עברה כאשה עוברה כו', פי' בשעה שכנס\"י הם בקטנות המוחין מאד בבחי' עיבור במעי אימא כנ\"ל שהוא המיצר והמצוק<sup data-n=\"3025\">26</sup> ומתגברים הדינים כו' ונתמלא עליהם עברה וזעם כו', עכ\"ז יהי' כל צרכיהם לפניך כו' וד\"ל. [ו]עד\"ז יובן תחת אשר לא עבדת בשמחה ו[ב]טוב לבב דייקא, ועבודה זו קאי על מעשה המצות שצריך להיות [ב]שמחה דוקא כשעושה המצוה, ויש להבין מאחר שהמצוה עבודה הי[א] לקיים דבר המלך לבד מה הצורך להיות שמח בעשייתה כו', אך הענין הוא לפי שהמצות נק' ארחות הוי'<sup data-n=\"3026\">27</sup>, שהקב\"ה מקיים בעצמו כל המצות כידוע בדרז\"ל שהוא מניח תפילין<sup data-n=\"3027\">28</sup> ומתפלל<sup data-n=\"3028\">29</sup> ועושה צדקה<sup data-n=\"3029\">30</sup> כמ\"ש אני מדבר בצדקה<sup data-n=\"3030\">31</sup> כו' וכמ\"ש במ\"א, ולכך אנו אומרים אשר קדשנו במצותיו<sup data-n=\"3031\">32</sup> וכמ\"ש מצותי<sup data-n=\"3032\">33</sup> כו' וד\"ל, וידוע [דרמ\"ח מ\"ע<sup data-n=\"3033\">34</sup> הן רמ\"ח אברי' דמלכא<sup data-n=\"3034\">35</sup> כו' שהרי מצות ה' במה שהוא מניח תפילין וכדומה הוא הגבה] מאד נעלה מכל השתלשלות דאצי' בבי\"ע, וזהו אשר קדשנו כו', וא\"כ כשאינו שמח במעשה המצוה הוא רק בבחי' עיבור למעלה רק להוסיף האור באצי' עצמו, אבל אינו יורד האור בגילוי בבי\"ע [ב]בחי' לידה כנ\"ל, אבל ע\"י השמחה מתגלה בבחי' לידה וזהו תחת אשר לא עבדת כו' וד\"ל.\n<b>והנה</b> כתיב הקל קול יעקב<sup data-n=\"3035\">36</sup>, מה שלא יוכל להוציא מן ההעלם לגילוי בנקודת הלב בתפלה [ו]בשמחה של מצוה יוכל להוציא מן ההעלם ע\"י הקריאה בתורה אחר התפלה, והטעם הוא לפי שהקורא בתורה קורא [בשמותיו<sup data-n=\"3036\">37</sup> של הקב\"ה, ולשון קריאה הוא כאדם הקורא לחבירו שמביאה לגילוי מן ההעלם והמרחק שהי'] בתחלה כו'. כמ\"כ עד\"מ באותיות התורה קורא הוא לאור א\"ס ב\"ה הגנוז בח\"ע כי אורייתא מחכ' נפקת<sup data-n=\"3037\">38</sup> כו', והרי הוא ית' בא לידי גילוי בכללות נש\"י בלבבם כשקוראי' באותיות התורה שבכתב שהוא גנוז בהם בהעלם כידוע מפני שבאתעדל\"ת דנפש האלקי' למטה נעשה אתעדל\"ע<sup data-n=\"3038\">39</sup> והקב\"ה יושב וקורא כנגדו<sup data-n=\"3039\">40</sup>, דהיינו שגם באצי' נמשכים בחי' מוחין",[["3023","24","<b>במיצר</b>: אד: במצור. וראה לקמן הערה 26."],["3024","25","<b>בכל פ' העיבור</b>: נסמן לעיל לא, ג הערה 215. וראה גם לעיל סז, א."],["3025","26","<b>המיצר והמצוק</b>: אד: המצור. א: ומצוק. וראה לעיל הערה 24."],["3026","27","<b>שהמצות נק' ארחות הוי'</b>: תהלים כה, י. ראה ביאוה\"ז וישלח יט, ב ואילך. מאמרי אדה\"א דברים ח\"ג ע' תתקג. וש\"נ. ש\"א לב, א. שה\"א ג, ב ובהערה 6. לעיל סח, ד."],["3027","28","<b>שהקב\"ה. . מניח תפילין</b>: ברכות ו, א."],["3028","29","<b>שהקב\"ה. . ומתפלל</b>: ברכות ז, רע\"א. ראה גם שע\"ת מג, ב ובהנסמן במ\"מ לשם."],["3029","30","<b>שהקב\"ה. . ועושה צדקה</b>: נסמן לקמן פ' בשלח קסט, ד."],["3030","31","<b>אני מדבר בצדקה</b>: ישעי' סג, א. ראה גם מאמרי אדה\"ז תקס\"ז ע' צב."],["3031","32","<b>אשר קדשנו במצותיו</b>: נוסח ברכת המצות."],["3032","33","<b>מצותי</b>: תולדות כו, ה."],["3033","34","<b>מ\"ע</b>: ד: פקודין."],["3034","35","<b>דרמ\"ח. . אברי' דמלכא</b>: נסמן לעיל פ' שמות מו, ב."],["3035","36","<b>הקל קול יעקב</b>: תולדות כז, כב."],["3036","37","<b>שהקורא בתורה קורא [בשמותיו</b>: נסמן לעיל פ' שמות ז, ד."],["3037","38","<b>אורייתא מחכ' נפקת</b>: נסמן לעיל יא א."],["3038","39","<b>שבאתעדל\"ת. . אתעדל\"ע</b>: נסמן לעיל מא, א."],["3039","40","<b>והקב\"ה יושב וקורא כנגדו</b>: נסמן לעיל נח, ג."]]],[2300540171,"דאו\"א הגנוזים ובאים לידי גילוי בז\"א כו' וד\"ל. ואמנם העוסק במקרא מדה ואינה מדה<sup data-n=\"3040\">41</sup>, ומנעו בניכם מן ההגיון<sup data-n=\"3041\">42</sup> כו', והעיקר הוא המשנה שנק' דבר ה' וכמ\"ש ואשים דברי בפיך<sup data-n=\"3042\">43</sup> כו' וגם נק' מלכות מתניתן מלכתא<sup data-n=\"3043\">44</sup> כמ\"ש בי מלכים<sup data-n=\"3044\">45</sup> כו', ויש להבין ההפרש ביניהם. הנה ארז\"ל על א\"י שנק' ארץ צבי<sup data-n=\"3045\">46</sup> מה הצבי אין עורו מחזיק בשרו כו', פי' בשר הצבי כשמתפשט בגידול גם עורו מתפשט עמו כא' ממש וכשכלה הבשר יתקמץ העור ויכלה גם הוא, משא\"כ בשאר בהמה וחי' שגם כשיכלה הבשר העור במקומו עומד כו'. וזהו משל לא\"י שנק' ארץ צבי דהיינו כשיושביה בה <span data-k=\"pg\">קב</span> ּ בהתפשטות והתרחבות גם מקום שטח הארץ מתפשט' וכשכלו יושבי' גמדא<sup data-n=\"3046\">47</sup> כו'. והנה כתיב ונתתי צבי בארץ החיים<sup data-n=\"3047\">48</sup> כו'<sup data-n=\"3048\">49</sup> שגם ארץ החיים דלעילא נמשלה ג\"כ לעור הצבי.\n<b>וביאור</b> הדבר זהו ענין ההפרש בין תשב\"כ לתשבע\"פ, כי הנה בתשב\"כ אין ההבנה והשכל בה עיקר, שהרי כמה ענינים שבה שאין להם הבנה כלל, ויש כמה סיפורי מעשיות שאין להם הבנה מה הכוונה בסיפורם<sup data-n=\"3049\">50</sup> כו', רק האותיות שבה המה העיקר להיות כי הם רמזים לבד, ועד\"מ תלמיד הלומד לפני רבו שהתלמיד משכיל הסברא שלומד מרבו ומשיגה אך אינו משכיל היטב עומק נקודת ההשכלה על בורי' וזה לא יוכל הרב להסביר לו בדבור כ\"א ברמיזא לבד שמרמז לו באצבע על עיקר הנקודה, משא\"כ חיצוניות הסברא כבר הסביר לו בדבור ויוכל להשיגה מדיבוריו אבל נקודת פנימי' של ההשכלה לא יוכל להביא בדבור כ\"א ברמז לבד. וזהו כענין די לחכימא ברמיזא<sup data-n=\"3050\">51</sup>, פי' לחכימא דוקא שכבר משיג חיצוניות השכל והסברא יוכל להבין גם ברמז עיקר הנקודה, כי הרמז אינו אלא על עיקר הנקודה מה שלא [הי'] באפשרי לפרש בצירופי אותיות כו' וד\"ל. וכמ\"כ הנה כל עיקר תשב\"כ הוא בחי' נקודה הפנימי' של תושבע\"פ מה שלא יוכל להגלות בדבור כ\"א בדרך רמז לבד והן הן האותיות שבה שהמה רק רמזים לבד, דהיינו לצייר איכות אופן המשכת נקודת החכמה הנגלית בתשבע\"פ אם כך או כך כו' שהאותיות אינם רק ציורים לבד, והעיקר בתשב\"כ הוא רק ציורי האותיות כי אם יחסר אפי' קוץ א' פסולה<sup data-n=\"3051\">52</sup> כידוע. וה\"ז דומה ג\"כ לאומן הבונה עפ\"י חכמתו אך כדי שלא יטה ימין ושמאל [י]צייר מתחלה ברמזים כל אופני חכמת הבנין ע\"ג לוח כו' וכמ\"ש במ\"א ע\"פ ואהי' אצלו אמון<sup data-n=\"3052\">53</sup> כו' וד\"ל. משא\"כ תושבע\"פ הי'<sup data-n=\"3053\">54</sup> החכמה וההבנה הגלוי' לשכל והשגה שהעיקר בה הדבור",[["3040","41","<b>העוסק במקרא. . מדה</b>: ב\"מ לג, א. ראה גם מאמרי אדה\"א שמות כאן ס\"ע עו."],["3041","42","<b>ומנעו בניכם מן ההגיון</b>: ברכות כח, ב."],["3042","43","<b>ואשים דברי בפיך</b>: ישעי' נא, טז."],["3043","44","<b>מתניתן מלכתא</b>: ביצה כח, ב. אד: מתניתא (וראה לקמן הערה 59) — כתובות סא, ב."],["3044","45","<b>בי מלכים</b>: משלי ח, טו."],["3045","46","<b>א\"י שנק' ארץ צבי</b>: ראה ירמי' ג, יט. דניאל יא, טז. מא. גיטין נז, א."],["3046","47","<b>מה הצבי </b>[אד: צבי]<b>. . בשרו. . גמדא</b>: ראה גיטין שם. מאמרי אדה\"א שמות ח\"א ע' סו."],["3047","48","<b>ונתתי צבי בארץ החיים</b>: יחזקאל כו, כ [ושם: חיים — ראה לקמן ע, ד. עב, א ובהערה 45. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370259\" data-slug=\"torah-or\" data-id=\"3901370259\">תו\"א כאן נח, א</a>. מאמרי אדה\"ז תקס\"ג כאן ס\"ע קיב. אוה\"ת כאן ס\"ע ב'תרב. מאמרי אדה\"א נ\"ך ע' תג. וש\"נ]."],["3048","49","<b>כו'</b>: א ובאוה\"ת כאן (ס\"ע ב'תרב): ליתא."],["3049","50","<b>בסיפורם</b>: באוה\"ת כאן (ע' ב'תרג): מציין לפרדס שער כז ומעתיק ממנו."],["3050","51","<b>די לחכימא ברמיזא</b>: נסמן לעיל נו, א"],["3051","52","<b>יחסר אפי' קוץ א' פסולה</b>: כ\"ה גם ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600551\" data-slug=\"or-hatorah-hb\" data-id=\"8316600551\">אוה\"ת כאן (ע' ב'תרג</a>). מאמרי אדה\"א שמות כאן (ע' עא). ראה מנחות כט, א. וראה גם כלה רבתי פ\"י, הי\"ט: דעקר לכולי מילתא. . לתגא. מאמרי אדה\"ז הקצרים ע' תקנא. תקס\"ג ח\"א ע' קיא. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201562\" data-slug=\"likkutei-sichot\" data-id=\"1300201562\">לקו\"ש בראשית (כרך כ) ע' 550</a>."],["3052","53","<b>ואהי' אצלו אמון</b>: משלי ח, ל. ראה גם מאמרי אדה\"א בראשית ע' (תט) תי-תיד. נ\"ך ע' (נה) נט. ע' תד ואילך."],["3053","54","<b>הי'</b>: אד: הוא."]]],[2300540208,"בהסבר להטע[י]ם הסברא בגילוי דוקא, כמשל השגת התלמיד מה שלומד מרבו כו' ולא ברמז כו'. ולהיות כן הנה יובן למשכיל שזהו ההפרש ביניהם, שהדבור בהסבר בגילוי אין תלוי האורך ורוחב שבו אלא לפי אופן ההשגה שבגילוי, אם הי' באורך ורוחב בהתפשטות גדולה גם הדבורי' יהי' ממילא ומאליהם בהתפשטות גדולה באותיות רבים כו' [ואם הוא בצמצום ובקצרה גם האותיות הדיבור יהי' בקצרה וצמצום כו'], וא\"כ אין האותיות שבדבור מצד עצם<sup data-n=\"3054\">55</sup> כלום כי ממילא נעשו כנראה בחוש שלא יחשוב האדם מתחלה איך לדבר השכל כי הדבור מאליו יתנהג כפי אופן השכל<sup data-n=\"3055\">56</sup> וכמ\"ש במ\"א דאבא יסד ברתא<sup data-n=\"3056\">57</sup> כו' וד\"ל. אבל ציורי אותיות שבכתב אינם תלויים בהבנה ושכל כלל מאחר שהן רק רמזים לבד כנ\"ל, א\"כ אדרבה הציור בדקדוק גדול הוא ולא יגרע ולא יוסיף ממנו אפי' קוץ א' כי ישתנה איכות ההבנה מפני שינוי הקוץ כו', משא\"כ הדבור בהסבר השכל אין בהם דקדוק כלל אם יסביר בצירופי אותיות כאלו דוקא או באופן אחר רק שיובן מהם ההשגה והטעם שהוא העיקר כו'. וזהו שתשבע\"פ שנק' סיפור ולא ספר אין קפידא בשינוי ציורי אותיות משא\"כ בתשב\"כ שנק' ספר<sup data-n=\"3057\">58</sup> כמ\"ש בזהר וד\"ל. וזהו שארץ החיים הוא תושבע\"פ נמשלה דוקא לעור הצבי שכפי ערך הבשר כן יתפשט העור וזהו משל שלפי ערך האור והשכל כן יתרחבו האותיות ממילא ובלתי האור והשכל ממילא כלא <span data-k=\"pg\">206</span> ּ יהיו, משא\"כ בתשב\"כ שציורי האותיות במהותם יתקיימ[ו] בל יגרע[ו] ובל יוסיפו עליהם כנ\"ל וד\"ל. ומפני טעם זה דאותיות תשבע\"פ הם בתכלית הביטול ממציאותם לגבי מקור הסברא והשכל המנהיגם כנ\"ל [וד\"ל], לזאת יתרון מעלתם בזה על תשב\"כ עד שהעוסק במקרא מדה ואינה מדה כו' ועל המשנה נאמר ואשים דברי בפיך כו', כי אוא\"ס ב\"ה אינו שורה כ\"א על תכלית הביטול ממציאותו<sup data-n=\"3058\">*59</sup> כידוע ובדבור שבתשבע\"פ כששונה ההלכה והסברא אין הדבור כלום מצד עצמו לכך מתניתן<sup data-n=\"3059\">59</sup> מלכתא כמלך הגוזר<sup data-n=\"3060\">60</sup> על<sup data-n=\"3061\">61</sup> עבדו ושלוחו שאין השליח תופס מקום בעצמו כו' וכמ\"ש במ\"א, משא\"כ באותיות תשב\"כ אע\"פ שקוראי' בשמותיו כו' הנה האותיות יש ודבר מה כי מחכמה עילאה נפקת והחכמה היא יש ודבר מה לגבי אור א\"ס ב\"ה כידוע וד\"ל. וכמ\"כ גם האהבה בתענוגי' שבתפלה שהוציאה מן ההעלם לגילוי בנקודת הלב הוא יש ודבר מה שהרי יש מי שאוהב כו', ואעפ\"י שנאמר בה מה יפית ומה נעמת כו' אין אור א\"ס שורה בה כמו בדבור בתשבע\"פ מטעם הנ\"ל בקריאה בתשב\"כ וד\"ל. וזהו אין להקב\"ה",[["3054","55","<b>עצם</b>: אד: עצמו."],["3055","56","<b>הדיבור. . כפי אופן השכל</b>: נסמן לעיל פ' שמות יב, א הערה 538."],["3056","57","<b>דאבא יסא ברתא</b>: נסמן לעיל מז, ב."],["3057","58","<b>שתשבע\"פ. . בתשב\"כ שנק' ספר</b>: נסמן לעיל ט, ג."],["3058","*59","<b>אוא\"ס. . שורה. . הביטול ממציאותו</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310011\" data-slug=\"tanya\" data-id=\"3401310011\">תניא פ\"ו</a>."],["3059","59","<b>מתניתן</b>: א: מתניתא (וראה לעיל הערה 44). ד: נק' משנה."],["3060","60","<b>כמלך הגוזר</b>: ראה מאמרי אדה\"ז על פרשיות התורה ח\"א ע' קפט. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370128\" data-slug=\"torah-or\" data-id=\"3901370128\">תו\"א וישב כז, ב</a>."],["3061","61","<b>על</b>: א: ע\"י."]]],[2300540240,"בעולמו אלא ד\"א של הלכה<sup data-n=\"3062\">62</sup>, וכן ענין מי שתורתו אומנתו<sup data-n=\"3063\">63</sup> פטור מן התפלה היינו מטעם הנ\"ל להיות כי לית מחשבה<sup data-n=\"3064\">64</sup> אפי' חש\"ב מ\"ה<sup data-n=\"3065\">65</sup> דחכמה עילאה תפיסא בעצמות אור א\"ס כידוע, אבל הדבור בתושבע\"פ להיותו תכלית הביטול שם הוא נתפס והם ד' אותיות<sup data-n=\"3066\">66</sup> שלו כו', וזהו שנתאוה הקב\"ה להיות לו דירה בתחתונים<sup data-n=\"3067\">67</sup> דוקא וד\"ל.\n<b>וזהו</b> שמסיים כאן<sup data-n=\"3068\">68</sup> בפ' זו אחר והוצאתי אתכם מתחת סבלות מצרים כו' והבאתי אתכם אל הארץ אשר נשאתי את ידי לתת אותה לאברהם כו' ונתתי לכם מורשה<sup data-n=\"3069\">69</sup> כו', כי הנה אחר שיצאו ממצרים דגרון ובא לידי גילוי בחי' לידה הנ\"ל כתיב ואראך מתבוססת בדמיך<sup data-n=\"3070\">70</sup> כו' דהיינו כמשל הלידה גשמיות שיוצא הולד מטונף מאד בדם נדות ודברים זרים ומאוסים מאד וצריך שישטפוהו מהם כידוע. וענין טינוף זה הוא לתועלת הולד כ\"א הי' הפסולת הזה מובלע בבשרו הי' רע מאד במכאובים רבים כו' וע\"י שנתקבץ ונאסף הפסולת שלו למקום א' ונבדלו הימנו ויצאו בלידה לחוץ ישאר הולד נקי מכל<sup data-n=\"3071\">71</sup> פסולת כו'. כמ\"כ עד\"מ האהוי\"ר שנתגלו בבחי' לידה מן העלם העיבור במעי הבינה כנ\"ל יצא עמם הפסולת שלהם נבדלים בפ\"ע והולכים לאיבוד חוצה כו', היינו תגבורת המחשבות זרות שנתגברו בעת נקודת גילוי הלב ויבלבלו אותו [והמה] הרהורי שטות בלתי ימצא בהם איזה תועלת כלל אפי' למילי דעלמא וה\"ז כמשל דברים המאוסים שבלידה כנ\"ל, וכ\"ז לתועלת האהוי\"ר שיצא נקי בלב בלתי תערובות רצונות נכריות עמם כו' רק רצון א' לה' תמים לבדו ואין זר אתו כמ\"ש נקי כפים ובר לבב<sup data-n=\"3072\">72</sup> כו' וד\"ל. וזהו ואראך לכנס\"י מתבוססת בדמייך בחי' דם הלידה שנאחזים בהם מותרי השפע לחיצוני' כו' ואומר לך בדמייך חיי<sup data-n=\"3073\">73</sup> שיהי' לך לתועלת הבירור מכל סיג כנ\"ל וד\"ל. וזהו והבאתי אתכם אל הארץ כו' כי כאשר יאבד הפסולת הנ\"ל ותתברר שם ב\"ן אזי כתיב אשת חיל עטרת בעלה<sup data-n=\"3074\">75</sup> למעלה משם מ\"ה<sup data-n=\"3075\">74</sup> כמ\"ש במ\"א, ותהי' עטרת תפארת<sup data-n=\"3076\">76</sup> [לאברהם] וליצחק כו'. וזהו אשר נשאתי את ידי לתת אותה לאברהם כו', פי' להיות להם למוחין ומקור החיות כי נכון יהי' הר בית ה' בראש ההרים<sup data-n=\"3077\">77</sup> כו' כמ\"ש בזהר. וביאור דבר זה <span data-k=\"pg\">קג</span> ּ הוא מה שאמר אשר נשאתי את ידי פי' עד\"מ כשאדם מגביה איזה חפץ",[["3062","62","<b>אין. . ד\"א של הלכה</b>: ראה ברכות ח, א. מאמרי אדה\"ז תקע\"א ע' צח. לקמן פ' תרומה שיז, ב ואילך. מאמרי אדה\"א ויקרא ח\"ב ע' תמד. הנחות תקע\"ז ע' ש ובהנסמן בהנ\"ל."],["3063","63","<b>מי שתורתו אומנתו</b>: שבת יא, א. ראה גם לקמן פ' יתרו רנו, א."],["3064","64","<b>לית מחשבה. . תפיסא</b>: ת\"ז בהקדמה (יז, א)."],["3065","65","<b>מחשבה. . חש\"ב מ\"ה</b>: זהר בראשית כד, א. ת\"ז תס\"ט (קיב, ב). ראה גם שעה\"י קלז, א."],["3066","66","<b>אותיות</b>: אד: אמות."],["3067","67","<b>שנתאוה. . דירה בתחתונים</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא</a> רפל\"ו (וראה הנסמן בליקוט פירושים לשם). ביאוה\"ז תזריע עב, ג. מאמרי אדה\"א הנחות תקע\"ז ע' שכט. ש\"א צז, ב."],["3068","68","<b>כאן</b>: אד: ליתא."],["3069","69","<b>והבאתי אתכם. . מורשה</b>: וארא ו, ח [בדילוג]."],["3070","70","<b>ואראך מתבוססת בדמיך</b>: יחזקאל טז, ו."],["3071","71","<b>מכל</b>: אד: מבלי."],["3072","72","<b>נקי כפים ובר לבב</b>: תהלים כד, ד."],["3073","73","<b>ואומר לך בדמיך חיי</b>: יחזקאל שם."],["3074","75","<b>אשת חיל עטרת בעלה</b>: משלי יב, ד."],["3075","74","<b>ב\"ן. . למעלה משם מ\"ה</b>: ראה מאמרי אדה\"ז תקס\"ב ח\"א ע' קצ. ח\"ב ע' תקלט. תקס\"ג ח\"ב ע' תשכה. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380280\" data-slug=\"likkutei-torah\" data-id=\"4001380280\">לקו\"ת בחוקותי מז, ג</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670498\" data-slug=\"torat-chaim\" data-id=\"2300670498\">תו\"ח בראשית טז, ג</a> ובהערה 36. לקמן פ' תשא שפה, ג."],["3076","76","<b>עטרת תפארת</b>: ישעי' סב, ג."],["3077","77","<b>נכון. . בראש ההרים</b>: ישעי' ב, ב. ראה זהר תשא קפט, ב."]]],[2300540271,"מן מקום הנמוך הרי יוכל להגביהו עד למעלה מראשו [כי היד יש בו כח ההשפלה למטה מטה מרגליו הרבה וגם ענין ההגבה עד למעלה מראשו] הרבה [כו'], והרי הטובע בנהר<sup data-n=\"3078\">78</sup> אעפ\"י שראשו מוטבע אם ידיו פשוטות עדיין למעלה מהנהר יוכל להנצל מטביעתו כו' כי פשיטת היד למעלה מהראש בגובה הרבה כו' וכמ\"ש במ\"א בענין נשיאת כפים<sup data-n=\"3079\">79</sup> כו'. ועד\"ז יובן גם כאן אשר נשאתי ידי הגבהת ידי למעלה מן הראש הרבה פי' ידי יד כהה<sup data-n=\"3080\">80</sup> דבחי' מל' דאצי' אשר הי' ראש לשועלים<sup data-n=\"3081\">81</sup> דבי\"ע כידוע, ולע\"ל כתיב בה כי תהיו אתם ארץ חפץ<sup data-n=\"3082\">82</sup>, וכמ\"כ כתי' ונתתי צבי בארץ החיים פי' חפץ ורצון העליון של המאציל הנק' כתר<sup data-n=\"3083\">*83</sup> עליון שלמעלה הרבה מהראש ומוחין דחו\"ב דאצי' כידוע, ישרה בארץ החיים מל'<sup data-n=\"3084\">83</sup> דאצי' כי תהי' עטרת בעלה כעטרה המקפת על הראש ומוחין כו' וכמ\"ש במ\"א, וזהו ג\"כ ענין צבי שהוא לשון רצון<sup data-n=\"3085\">*84</sup> כידוע וד\"ל. וזהו המשך דברי הפסוק הנ\"ל והבאתי אתכם כללות נש\"י אל הארץ אשר תקרא לע\"ל בשם ארץ חפץ העליון כו' אשר נשאתי אותה בידי למעלה מן הראש להיות לעטרת תפארת כו' לאברהם וליצחק ונתתי לכם מורשה להיות כי גם אתם נק' בשם ארץ חפץ זו כידוע דכנס\"י היא בחי' מל'<sup data-n=\"3086\">84</sup> דאצי' ע\"כ תהי' לכם דוקא מורשה וד\"ל. ובכ\"ז יובן ענין הסמיכות שאחר היציאה מסבלות מצרים יביא אותם אל ארץ חפץ כו' שהן הן ענין תשב\"כ ותשבע\"פ הנ\"ל, שע\"י הקריאה בתשב\"כ הם יוצאים מסבלות מצרים מן ההעלם לגילוי כנ\"ל ואח\"כ בדבור בתשבע\"פ הנק' ארץ החיים ארץ טובה ורחבה פי' האור עם הכלי מתרחבים כא' כמו משל עור הצבי כנ\"ל בזאת הוא מביאם אל ארץ חפץ דוקא, לפי שלע\"ל יהי' תשבע\"פ למעלה מתשב\"כ מטעם הנ\"ל וד\"ל. ובזה יובן הטעם למה המצוה לזכור יציאת מצרים דוקא יותר משאר ד\"ת כמו ק\"ש ותפילין וכדומה, דכתיב למען תזכור את יום צאתך מאמ\"צ כל ימי חייך לרבות הלילות<sup data-n=\"3087\">85</sup> שמצוה להזכיר גם בערב כמו בבוקר כידוע. אך הענין הוא להיות כי בכל יום אדם יוצא ממצרים עורף דקליפה הוא הרצון הזר כידוע המעכב את הלידה כנ\"ל מחמת מיצר הגרון כו', וע\"י יציאה זו מן העלם העיבור באה הנשמה האלקי' למדריגת חפץ העליון להקרות בשם ארץ חפץ כנ\"ל וכמ\"ש בר\"מ כ\"א חפץ בה המלך<sup data-n=\"3088\">86</sup> ונקראה בשם כו' כי נעוץ תחלתן בסופן<sup data-n=\"3089\">87</sup>, ע\"כ בכל יום החיוב לזכור יציאת",[["3078","78","<b>הטובע בנהר</b>: השוה מאמרי אדה\"ז על מארז\"ל ע' תסב."],["3079","79","<b>בענין נשיאת כפים</b>: ראה גם לקמן עב, ב ובהנסמן שם."],["3080","80","<b>ידי יד כהה</b>: ראה גם לקמן עב, ב. מאמרי אדה\"א שמות (כאן) ע' צב."],["3081","81","<b>מל'. . ראש לשועלים</b>: נסמן לעיל נד, ב."],["3082","82","<b>כי תהיו. . חפץ</b>: מלאכי ג, יב."],["3083","*83","<b>ורצון. . הנק' כתר</b>: נסמן לקמן עט, א."],["3084","83","<b>כתר עליון. . מל'</b>: ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תתיט. לקמן קא, ב."],["3085","*84","<b>צבי. . רצון</b>: במאמרי אדה\"ז תקס\"ג כאן (ע' קיב): מלשו' צבא צביונו. וראה לקמן עב, א. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370265\" data-slug=\"torah-or\" data-id=\"3901370265\">תו\"א (כאן) נט, ג</a>. וראה גם מאמרי אדה\"א שמות (כאן) ע' פו. נ\"ך ע' תג."],["3086","84","<b>דכנס\"י. . מל'</b>: ראה זהר בלק קצז, א."],["3087","85","<b>למען תזכור. . הלילות</b>: פ' ראה טז, ג. ראה ברכות יב, ב [במשנה]. שו\"ע אדה\"ז הל' ק\"ש סס\"ז, ס\"א."],["3088","86","<b>כ\"א חפץ בה המלך</b>: אסתר ב, יד. ראה גם מאמרי אדה\"א שמות ח\"ב ע' תקעט. וש\"נ. שע\"ת סא, א ובהערה 5. מאמרי אדה\"ז תקס\"ה ח\"א ע' קכד. וראה גם לקמן פ' בא קכה, ד. וש\"נ."],["3089","87","<b>נעוץ תחלתן בסופן</b>: ראה ס\"י פ\"א, מ\"ז."]]],[2300540300,"מצרים כי בכל יום יצרו של אדם מתגבר<sup data-n=\"3090\">88</sup> באופן חדש<sup data-n=\"3091\">89</sup> כו', וגם בלילה המצוה לזכור כמו ביום לפי שבלילה האור [יותר] נפלא ומבהיק<sup data-n=\"3092\">90</sup> להאיר את החשך כו' ובלילה מתגברים החיצוני' לינק ממותרי השפע דבחי' יסוד כו'. ואמנם בלידה הוא גילוי האור להאיר את החשך ולהבריח את יניקת החיצונים וכמ\"ש בעמוד אש לילה<sup data-n=\"3093\">91</sup> ולע\"ל כתיב ולילה כיום יאיר<sup data-n=\"3094\">92</sup> מטעם זה כי יולד משיח דכתי' בי' אני היום ילדתיך<sup data-n=\"3095\">93</sup> כו' וד\"ל.",[["3090","88","<b>בכל יום יצרו. . מתגבר</b>: ראה סוכה נב, סע\"א."],["3091","89","<b>באופן חדש</b>: ראה קידושין ל, ב."],["3092","90","<b>שבלילה האור. . ומבהיק</b>: ראה שו\"ע אדה\"ז הלכות פסח סתל\"ג, ס\"ה."],["3093","91","<b>בעמוד אש לילה</b>: בשלח יג, יא [בדילוג. ושם: ולילה]. בהעלותך יד, יד־ נחמי' ט, יב [ושם: ובעמוד]."],["3094","92","<b>ולילה כיום יאיר</b>: תהלים קלט, יב."],["3095","93","<b>אני היום ילדתיך</b>: נסמן לעיל א, ג."]]],[2300540059,"<b>ביאור על הנ\"ל</b>\n<b>להבין</b> שרש כל הדברים<sup data-n=\"3096\">1</sup> הנ\"ל. הנה [תחלה יש] להבין שרש ענין מצרים דקדושה<sup data-n=\"3097\">2</sup> הוא מ\"ש בלק\"ת ע\"פ ופרעה עומד<sup data-n=\"3098\">3</sup> על היאור שהיאור הוא בחי' יסוד אימא שמסתיים בחזה דז\"א כו', והעורף דפרעה הוא העומד ומעכב את הלידה כו', והגרון הוא מצר מ\"י שבו נתצמצם מוחין דאו\"א במיצר גדול דקטנות כשבאו להתגלות בלב כו'. וביאור כ\"ז, <span data-k=\"pg\">208</span> ּ הנה מבשרי אחזה<sup data-n=\"3099\">4</sup> להיות כי אנו רואים באדם התחתון שמן השכל שבמוח יהיו<sup data-n=\"3100\">5</sup> הולדת המדה אהבה או יראה, ויש להבין בזה איך יומשך מהות המדה ממהות השכל מאחר שאינה ממציאות א' כלל כי הרי אין מהות האהבה אפי' מעין ודוגמא של מהות השכל כו'. אך הענין הוא דיש בחי' ממוצעת ביניהם שבו יתחברו וישתתפו עד שיומשך המדה מן השכל, והיינו להיות כי לאחר שנולדה האהבה בלב כבר נסתלק השכל לגמרי ובהיות השכל של המדה במוח עדיין לא הי' קצת רמז למציאות אהבה שבלב. וא\"כ היתה רגע א' שלא הי' בה לא הארת השכל שבמוח ולא מהארת המדה שבלב, והיינו לאחר סילוק השכל במוח ובא להוליד המדה בלב ועדיין לא נולדה אז ברגע ההיא הי' הפסק וחלל ביניהם במציאות א' שאינו לא ממהות השכל ולא ממהות [ה]מדה כו', ומציאות מהות זה שאינו לא שכל ולא מדה הוא בחי' הממוצעת [ביניהם] שע\"י יתחברו כו', והיינו מקום ההיפוך שהשכל מתהפך למדה ונק' מקום החתך כו'.\n<b>וביאור</b> הדבר להיות כי ידוע דשכל וטעם של האהבה או יראה מתחלת נביעתו במקורו במוח הוא בהתרחבות גדול",[["3096","1","<b>להבין שרש כל הדברים</b>: ביאור זה הוא ג\"כ מכ\"ק אדה\"ז (נאמר במוצאי שבת פ' וארא תקס\"ג). ונמצא בג' נוסחאות א) הנדפס כאן והוא הנחת כ\"ק אדה\"א, ב) הנחת הר\"מ בן כ\"ק אדה\"ז במאמרי אדה\"ז תקס\"ג ח\"א ע' קיג. ג) תו\"א פרשתנו נח, ב (זהה להנחת הר\"מ בשינויים והוספות). והערות הצ\"צ (על נוסח התו\"א) ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316300177\" data-slug=\"or-hatorah-hb\" data-id=\"8316300177\">אוה\"ת שמות כרך א ע' קעז</a>. ראה עוד ע\"ד המאמר להלן ברשימת הכת\"י [ושם מפורט ג\"כ סימני האותיות הבאים להלן בהמראי מקומות]."],["3097","2","<b>מצרים דקדושה</b>: ראה גם לעיל סט, ב. וש\"נ."],["3098","3","<b>בלק\"ת ע\"פ ופרעה עומד</b>: ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370260\" data-slug=\"torah-or\" data-id=\"3901370260\">תו\"א כאן (נח, ב</a>) מציין: בלקו\"ת פ' וישב (ד\"ה ועתה נבאר סוד יוסף) [וישב מ, א. וראה גם שם מ, ח]."],["3099","4","<b>מבשרי אחזה </b>[ג: ניתוסף: אלקה]: נסמן לקמן פ' בא צח, ב."],["3100","5","<b>יהיו</b>: א: יהי'. ג: נעשה."]]],[2300540097,"באותיות מחשבה ועיון כו', ואח\"כ הולך ומתקצר ומתצמצם עד שנעשה באותיות קצרים מאד לפי אופן [צמצום המדה בלבד ואמנם עכ\"ז ממהות שכל הוא עדיין. אך להיות כי נתצמצם כ\"כ לפי אופן] המדה אזי יש בו משיתוף והתחברות שניהם ממהות השכל וממהות המדה, אבל הוא בתכלית הקטנות של השכל ותכלית המיצר ולגבי המדה הוא שרש ומקור להגדילה ולהרחיבה אח\"כ בהעלם כו' כי כשתתגלה המדה תסתתר גם היא בה כידוע וד\"ל. ועד\"ז יובן ממש בעבודת ה' בתפלה לפעמים ההתבוננות דאם הבנים<sup data-n=\"3101\">6</sup> הי[א] מתיישבת<sup data-n=\"3102\">7</sup> במוח היטב להעמיק בגדולת ה' כו', אך עורף הוא רצון דקליפה חומר הגוף מעכב הלידה שהוא היציאה של המוחין אלו לגרון לבא בגילוי הלב כו' ונשארת במוח התפעלות המדה בבחי' עיבור תלת גו תלת<sup data-n=\"3103\">8</sup> ראשו בין ברכיו<sup data-n=\"3104\">9</sup> כו' כמ\"ש במ\"א, והיינו חבלי לידה דפרעה המעכב כו'. ואמנם כשהמוחין יוצאין מהעלם העיבור ובאים להתצמצם בגרון היינו שבאים לבחי' ממוצע בין ההתבוננות והתפעלות האהבה ואז הוא תכלית המיצר של התרחבות ההתבוננות כנ\"ל, ומחמת המיצר והצמצום דגרון כשבאים בגילוי אח\"כ בלב וחזה כו' אזי הם כדוגמת שאון רעש מים רבים כשמסתירים ומעמידים אותם במסך ואח\"כ בפתע פתאום יעבירו המסך כמ\"ש במ\"א, שזהו סיבת קיבוץ האורות ומוחין דאו\"א בחזה דז\"א ברעש באה ההתלהבות בלב כו', והיינו מסיבת המצר שלהם בגרון בתחלה יוצאים אח\"כ ברעש כו' וד\"ל. וזהו אם הבנים שמחה<sup data-n=\"3105\">10</sup> פי' כשמוחין דאימא מסתיימים בחזה הלב ברעש כנ\"ל אז כנס\"י נק' שמחה להיות כי מל' יוצאה מבחי' נקב החזה מאחורי[י'] ולכך נק' נקבה<sup data-n=\"3106\">11</sup> כידוע והוא בחי' אחוריים דז\"א, ונק' כלת משה<sup data-n=\"3107\">12</sup> בבחי' פנימי' ז\"א כאשר עדיין מקבלת ג\"כ קיבוץ גילוי אורות דאו\"א בחזה הלב כו'. והוא ההפרש בין פנימיות הדבור לחיצוניות הדבור, דהיינו האמירה בהבל הלב מהחזה בתגבורת שהוא המקור וכח המדבר כו' נק' פנימי' הדבור והוא לב דכנס\"י הנק' <span data-k=\"pg\">קד</span> ּ שושנה<sup data-n=\"3108\">13</sup> עילאה שנמשלה לשושנה גשמיות שבין החוחים<sup data-n=\"3109\">14</sup> כו' שהי' בחי' חיצוניות הדבור בה' מוצאות שהוא כבר כשיצאה מבחי' נקב שבחזה מאחוריו כו' וד\"ל. ולכך כשהמל' בבחי' פנימיות ז\"א נק' שמחה מפני שאם הבנים שמחה אז ג\"כ בקיבוץ המוחין ברעש מחמת יציאתה מן המיצר דגרון כנ\"ל וכמשל שמחת מי שיצא מבית האסורים. וכן ענין השמחה בכ\"מ הוא תגבורת הקיבוץ והאסיפה מגבוה לנמוך<sup data-n=\"3110\">15</sup> כו' שלא לפי המדה",[["3101","6","<b>דאם הבנים</b>: נסמן לעיל יז, א."],["3102","7","<b>דאם. . מתיישבת</b>: ג: דא\"ס נקלט."],["3103","8","<b>תלת גו תלת</b>: נסמן לעיל לח, ד."],["3104","9","<b>ראשו בין ברכיו</b>: נדה ל, ב. ראה גם לעיל פ' שמות לא, ג. לקמן פ' בא קכח, א."],["3105","10","<b>אם הבנים שמחה</b>: תהלים קיג, ט."],["3106","11","<b>מל'. . נק' נקבה</b>: ראה ע\"ח שער הכללים פ\"י. (שער תיקון הנוקבא) של\"ד, פ\"ב כלל ט."],["3107","12","<b>מל'. . כלת משה</b>: ראה זהר הרקיע ר\"פ בראשית. ס' הדרת מלך סקנ\"ו (פו, ב). מאמרי אדה\"ז תקס\"ח ח\"ב ע' תריד. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381286\" data-slug=\"likkutei-torah\" data-id=\"4001381286\">לקו\"ת שה\"ש לט, סע\"ג</a> ואילך."],["3108","13","<b>דכנס\"י הנק' שושנה</b>: זהר בהקדמה א, א."],["3109","14","<b>לשושנה. . שבין החוחים</b>: שה\"ש ב, ב."],["3110","15","<b>השמחה. . מגבוה לנמוך</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370473\" data-slug=\"torah-or\" data-id=\"3901370473\">תו\"א שמות קז, א</a>."]]],[2300540135,"כמ\"ש במ\"א וד\"ל. וע\"ד כל הנ\"ל יובן למעלה באצי' כשז\"א דאצי' בבחי' עיבור במעי אימא תלת גו תלת הוא מחמת פרעה העליון כו', היינו ענין תכלית העלם המדות דאצי' במקורם בבינה דאצי' ואז הם בתכלית הקטנות דהיינו רק בבחי' נה\"י לבד כמשל הולד המקופל כו' ומחמת זה יורדי' מותרי השפע לג' שרי פרעה<sup data-n=\"3111\">16</sup> שר המשקים ושר הטבחים כו'. לפי שנתצמצמו מאד הפנימי' מוחין דאו\"א בכ\"ע<sup data-n=\"3112\">17</sup> דקדושה אז יש מקום יותר להמשכת ויניקת אחוריים דכתר ונק' פרעה<sup data-n=\"3113\">18</sup> כידוע, ואח\"כ יצאו המדות דאצי' בבחי' גילוי מן ההעלם וכמ\"ש בכוונת דפסח ויוציאנו הוי' אלקינו<sup data-n=\"3114\">19</sup> חו\"ב ממצרים דגרון כו', ומתחלה הי' יציאתם העיקרי מן אחוריים דכתר המעכב לידתם כנ\"ל, וזהו שהיו משועבדים לפרעה כו' אנו ובנינו<sup data-n=\"3115\">20</sup> כו' ואח\"כ יצאו מבחי' העיבור לגילוי, אבל נתצמצמו במאד בגרון הנק' מצרים. והוא ענין תכלית קטנות המוחין דאו\"א דאצי' כשבאין לבחי' ממוצע להיות מתהוה מהם מציאות מדה דאצי' אור חסד או אור גבורה וכדומה וכנ\"ל, עד שהוציאם ממצרים ויצאו לגילוי גמור במהות מדות בחזה דז\"א בהתרחבות והגדלה בין במדות בין במוחין שלהם כמבואר ע\"פ משל הנ\"ל וד\"ל.\n<b>והנה</b> הקל קול יעקב<sup data-n=\"3116\">21</sup> כו' היינו חכמות בחוץ תרונה<sup data-n=\"3117\">22</sup> תרין חכמות תשב\"כ ותשבע\"פ, ותשב\"כ נק' חכמה עילאה ושבע\"פ נק' חכמה תתאה<sup data-n=\"3118\">23</sup>, ושניהם יוצאים ע\"י הקול דקנה אלא שבכתב הוא בלשון קריאה ושבע\"פ הוא בלשון משנה כו'. ויש להבין תחלה איך ע\"י המקרא יוצא העלם העיבור לגילוי בנקודת הלב כו', הנה אנו רואים שהקול יש בו מהרכבת שני דברים מן המוח ומן הלב, שהרי הוא יוצא מהבל הלב ונמשך בקנה שהוא יוצא מן המוח כו'. והענין הוא דלהיות כי הקנה הגשמי מורה על צמצום ומצר המוחי' והוא כאשר ירצו להתהפך למדה כנ\"ל הרי הקנה ממוצע גמור בין המוח ללב, ולכך בקול ד\"ת שהקנה מוציא מהבל הלב בזה הוא מחבר את המוחין דאורייתא ללב דכנס\"י להיות יציאתם מן ההעלם לגילוי, וזהו ענין הקריאה שהוא להוציא ההעלם של המוחין עליונים לגילוי בכללות נש\"י כו' וד\"ל. והנה ההפרש בין תשב\"כ לתשבע\"פ מבואר שהעיקר בתשב\"כ הן האותיות דוקא וכו', ושרש הדברים הוא כך כי האותיות הן רמזים לבד לצייר אופן ההמשכה איך תהי' כך או כך אבל לא שיש בהם עצמם השגה וטעם כלל, דהיינו הבי\"ת מורה אופן ההמשכה באורך ורוחב ימין ושמאל כו', והוי\"ו אופן ההמשכה מלמעלה למטה וכדומה, הרי אין בבי\"ת שום השגה עדיין רק שמרמזת ומציירת איכות אופן ההמשכה וכמשל",[["3111","16","<b>לג' שרי פרעה</b>: וישב מ, א ואילך. לז, לו. ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370453\" data-slug=\"torah-or\" data-id=\"3901370453\">תו\"א ויחי קב, ג</a>. מאמרי אדה\"ז תקס\"ג ח\"א ע' פא. מאמרי אדה\"א בראשית ע' תעא ואילך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670048\" data-slug=\"torat-chaim\" data-id=\"2300670048\">תו\"ח לך צא, ב</a> ובהערה 21."],["3112","17","<b>בכ\"ע</b>: א: בכתר עליון."],["3113","18","<b>אחוריים דכתר ונק' פרעה</b>: ראה גם לעיל פ' שמות לב, ד. וש\"נ."],["3114","19","<b>ויוציאנו הוי' אלקינו</b>: נוסח ההגדה. נסמן לקמן פ' בא פט, ב הערה 109."],["3115","20","<b>משועבדים. . ובנינו</b>: ע\"פ נוסח ההגדה."],["3116","21","<b>הקל קול יעקב</b>: תולדות כז, כב."],["3117","22","<b>חכמות בחוץ תרונה</b>: נסמן לעיל פ' שמות י, א."],["3118","23","<b>ותשב\"כ. . ושבע\"פ נק' חכמה תתאה</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370024\" data-slug=\"torah-or\" data-id=\"3901370024\">תו\"א בראשית ו, ג</a>. שע\"ת סח, ג. לקמן פ' בשלח ריא, ב. ויקהל תלג, ד."]]],[2300540172,"המרמז לתלמיד כו'. וכמ\"כ ציורי אותיות תשב\"כ הן שרשים ומקוריים לחכמה הנגלית בהשגה בתושבע\"פ דהיינו באיזה אופן יומשך חכמה <span data-k=\"pg\">210</span> ּ וטעם פלוני כו', וא\"כ עדיין המה הגבה למעלה מהחכמה וההשגה ולכך נק' ח\"ע שלמעלה מן השגה כו', מאחר שהן מו[ר]ין איך תומשך השגה פלונית שבתושבע\"פ וכו' וד\"ל. משא\"כ בתשבע\"פ שעיקרה בבינה<sup data-n=\"3119\">24</sup> [הוא] הדבור בחכ' תתאה כו' והיינו שהעיקר הוא ההשגה והטעם למה זה כשר וזה פסול כו' וצירופי האותיות שבתשבע\"פ אינם אלא לפי אופן השכל והטעם כן יתהוו צירופים, וכל שהשכל והטעם יותר בריבוי כן יתרבו ממש האותיות, ולא שיהי' קפידא בציורם כי מאחר שכבר הם נלקחים מן השכל והגילוי של השגה א\"כ אין מרמזין כלום לציור כו' רק הם כדבר א' נחשבים ממש עם השכל שכפי אופן אורך ורוחב השכל כן יהי' אורך ורוחב הצירופים. ועד\"מ הנה כשישכיל סברת והשגת איך שהוא ית' אדון העולם במוחו יתהוו צירופי אותיות אדון העולם ממילא כו' וכשיעמיק יותר שכלו בזה יתהוו ממילא צירופים אחרים נוספי' על תיבות אדון עולם כו', ונמצא האור עם הכלי שהן האותיות נובעים כא' והעדר ומיעוט הכלי הוא רק מהעדר ומיעוט האור ובריבוי האור ירבו הכלי[ם] והרי אין לכלי שום סיבה במיעוטה וריבויה מצד עצמותה כ\"א מחמת מיעוט וריבוי האור כו', והטעם מובן להיות כי הכלי נעשה מהתעבות האור<sup data-n=\"3120\">25</sup> כידוע ולית לי' מגרמי' כלום ואינו תלוי רק באור כו' וד\"ל. וזהו שא\"י דוקא נק' ארץ טובה ורחבה<sup data-n=\"3121\">26</sup> כו' כעור הצבי שאין עורו מתפשט כ\"א בהתפשטות בשרו כו' וכנז' בגמ' גמדא<sup data-n=\"3122\">27</sup> לה כו', לפי שמדת מל' הוא בחי' אותיות הדבור<sup data-n=\"3123\">28</sup> ולית לה מגרמה כלום<sup data-n=\"3124\">29</sup> וכל ריבוייה או מיעוטה אינו אלא ע\"פ ריבוי או מיעוט האור כנ\"ל. וזהו הטעם שלא מצינו ענין העליות וירידות פעם בקטנות ופעם בגדלות כ\"א במדת מל' וכנז' בע\"ח בשער נוק' דז\"א<sup data-n=\"3125\">30</sup> דלפעמים הי[א] רק בחי' נקודה תחת היסוד כו' ולפעמים מגדלת<sup data-n=\"3126\">*31</sup> מעט להיות מתלבשי'<sup data-n=\"3127\">31</sup> נה\"י דז\"א ולפעמים יותר בגדלות עד שתהי' בנין שלם בבחי' אצי' כו', ועליות וירידות מן הקצה אל הקצה כאלו לא מצינו בכל הפרצופים. כי הגם שבז\"א יש ג\"כ יניקה וגדלות היינו מיעוט האורות והמוחין או ריבויי' אבל הכלים שלו לא יגדלו ולא ימעטו מפני מיעוט או ריבוי האורות והמוחין כו', משא\"כ במל' נתרבה ונגדל הכלים ואותיות שלה ע\"י אופן ריבוי האורות ומוחין בה כו' וד\"ל. וזהו ארץ טובה מאירה בריבוי מוחין אז רחבה ביותר לפי אופן הריבוי טובה כו', ועד\"ז יובן ג\"כ בתשבע\"פ שהוא הדבור דוקא לפי אופן השכל והטעם הוא כנ\"ל, משא\"כ בציורי אותיות תשב\"כ שהן בפרצוף אבא שהכלים שלו",[["3119","24","<b>בתשבע\"פ שעיקרה בבינה</b>: ראה גם לעיל פ' שמות ט, ב ובהערה 411."],["3120","25","<b>הכלי נעשה מהתעבות האור</b>: נסמן לעיל מט, ד."],["3121","26","<b>ארץ טובה ורחבה</b>: שמות ג, ח."],["3122","27","<b>כעור הצבי. . גמדא</b>: ראה לעיל ע, א."],["3123","28","<b>מל'. . הדבור</b>: נסמן לעיל פ' שמות לד, א."],["3124","29","<b>מל'. . ולית לה מגרמה כלום</b>: נסמן לעיל נה, ג."],["3125","30","<b>בע\"ח בשער נוק' דז\"א</b>: ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370265\" data-slug=\"torah-or\" data-id=\"3901370265\">תו\"א כאן (נט, ג</a>): בכהאריז\"ל. ראה ע\"ח (שער מיעוט הירח) של\"ו, פ\"א. שע\"ת קא, ג ובהערה 22. לקו\"ב — לר\"ה — לשער היחוד אות מז [קה\"ת תשנ\"ה ע' 388. וש\"נ]."],["3126","*31","<b>מגדלת</b>: כנצ\"ל: מתגדלת."],["3127","31","<b>מתלבשי'</b>: אג: מלבשת."]]],[2300540209,"לא ירבו ולא ימעטו בשביל ריבוי ומיעוט האור כו' לכך הקפידא בציורים כו' וד\"ל.\n<b>ועתה</b> יובן ענין הקל קול יעקב כו' כי ע\"י הקריאה בתשב\"כ מרמז להמשכת חכמה איך תהי' אופן יציאתה לגילוי מן ההעלם אבל בתשבע\"פ הנגלית אין מצות הקריאה עיקר אלא ההשגה וטעם וממילא יתרחבו האותיות כנ\"ל, והנה מה שלא יוכל להוציא ממצרים דגרון לגילוי הלב בתפלה ובמעשה המצות כו' יוכל להוציא מן ההעלם ע\"י הקריאה בתשב\"כ אחר התפלה ע\"י הקנה המחבר המוח ללב כנ\"ל. ואמנם ענין לימוד תושבע\"פ הוא גבוה מכל עיקר ענין התפלה וכמו רשב\"י שהי' תורתו אומנתו<sup data-n=\"3128\">32</sup> כו'. <span data-k=\"pg\">קה</span> ּ והטעם הוא לפי שיש יתרון מעלה בתשבע\"פ דכתיב ביה<sup data-n=\"3129\">33</sup> מלכים ימלוכו<sup data-n=\"3130\">34</sup> כו' ומתניתין מלכתא<sup data-n=\"3131\">35</sup> כמלך הגוזר ואומר לעשות כך ולא כך כו' והוא מחמת בחי' ביטול שבחכמה שהי[א] הגבה למעלה מאהבה בתענוגים, כי גם הקורא בתשב\"כ ומוציא לגילוי הלב מן העלם המוחין עליונים כנ\"ל, עכ\"ז אהבה רבה זו הי[א] יש ודבר מה שהרי יש מי שקורא כו'. ואמנם העיון בתושבע\"פ הוא תכלית הביטול במציאות שאינו מרגיש עצמותו כלל רק שהוא בחי' כלי לדבר ה' זו הלכה<sup data-n=\"3132\">36</sup> שבפיו לגזור אומר כשר פסול כו' וכמ\"ש ואשים דברי בפיך<sup data-n=\"3133\">37</sup> כו'. ועוד זאת יתרון מעלת תושבע\"פ על תשב\"כ להיות כי אשת חיל עט\"ב<sup data-n=\"3134\">38</sup>, והגם דאורייתא מח\"ע נפקת<sup data-n=\"3135\">39</sup> הי[א] תשב\"כ, אבל שרש תשבע\"פ היא הגבה למעלה מן החכמה והיינו מבחי' כתר עליון שרש החכמה ולכך נק' ארץ חפץ, שהרי אנו רואים שהרצון העליון בפירוש איך לעשות לא ימצא כתוב ומפורש בתושב\"כ כ\"א בתושבע\"פ דוקא, וכמו פ' ציצית שלא היינו יודעים איך לעשות ציצית כ\"א ע\"פ המפורש בתושבע\"פ וכמ\"ש זה בארוכה במ\"א בענין תר\"ך עמודי אור<sup data-n=\"3136\">40</sup> כו', שלזה הטעם נק' ארץ חפץ שרצון העליון שורה בסוף כל דרגין דוקא כי נעוץ תחלתן בסופן<sup data-n=\"3137\">41</sup> כו' וסוף מעשה במחשבה תחלה<sup data-n=\"3138\">42</sup> כו', משא\"כ תשב\"כ שרשה בבחי' יסוד אבא<sup data-n=\"3139\">43</sup> כידוע. וזהו שאשת חיל הוא [בחי'] הדבור דתושבע\"פ יהי' לע\"ל עטרת בעלה כי כצנה רצון תעטרנו<sup data-n=\"3140\">44</sup> כו' וד\"ל.\n<b>וזהו</b> ונתתי צבי בארץ חיים<sup data-n=\"3141\">45</sup> פי' צבי הוא לשון רצון<sup data-n=\"3142\">46</sup> ע\"פ התרגום וצביתי ברעות נפשי<sup data-n=\"3143\">47</sup> כו', וגם ענין צבי הוא צביוני<sup data-n=\"3144\">48</sup> כו', וביאור הדבר היינו שיתגלה בחי' הארת אריך דאצי'",[["3128","32","<b>רשב\"י שהי' תורתו אומנתו</b>: שבת יא, א."],["3129","33","<b>ביה</b>: א: בה בי. ג: בי."],["3130","34","<b>בי מלכים ימלוכו</b>: משלי ח, טו."],["3131","35","<b>ומתניתין </b>[אג: ומתניתא]<b> מלכתא</b>: נסמן לעיל ע, א."],["3132","36","<b>לדבר ה' זו הלכה</b>: עמוס ח, יב. שבת קלח, ב."],["3133","37","<b>ואשים דברי בפיך</b>: ישעי' נא, טז. ראה גם לקמן בפ' פקודי תמה, ד. תמח, ב. מאמרי אדה\"ז תקס\"ב ח\"ב ע' שפו."],["3134","38","<b>אשת חיל עט\"ב</b>: משלי יב, ד."],["3135","39","<b>דאורייתא מח\"ע נפקת</b>: נסמן לעיל יא, א."],["3136","40","<b>בענין תר\"ך עמודי אור</b>: ראה אגה\"ק סכ\"ט."],["3137","41","<b>נעוץ תחלתן בסופן</b>: ראה ס\"י פ\"א, מ\"ז."],["3138","42","<b>וסוף מעשה במחשבה תחלה</b>: פיוט לכה דודי."],["3139","43","<b>תשב\"כ. . יסוד אבא</b>: ראה ע\"ח (שער דרושי נקודות) ש\"ח, פ\"ו. שער הכללים פי\"א. פע\"ח (שחה\"מ) שכ\"א, פ\"ז (ברוך המקום)."],["3140","44","<b>כצנה רצון תעטרנו</b>: תהלים ה, יג."],["3141","45","<b>ונתתי צבי בארץ חיים </b>[אג: החיים]: נסמן לעיל ע, א."],["3142","46","<b>צבי. . רצון</b>: ראה גם לעיל ע, ד."],["3143","47","<b>וצביתי ברעות נפשי</b>: ראה רמב\"ם הל' גירושין פ\"ד, הי\"ב."],["3144","48","<b>צבי הוא צביוני</b>: ראה כתובות קיא, א. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370265\" data-slug=\"torah-or\" data-id=\"3901370265\">תו\"א כאן (נט, ג</a>)."]]],[2300540241,"במל' הנק' ארץ חיים מטעם הנ\"ל שהרצון העליון עיקרו בתושבע\"פ דוקא וד\"ל. ובזה יובן מה שמסיים בפ' זו והבאתי אתכם<sup data-n=\"3145\">49</sup> אל הארץ אשר נשאתי את ידי וכו', פי' חג\"ת דא\"א נק' בשם יד הגדולה יד החזקה<sup data-n=\"3146\">50</sup> להיות שהן מתפשטים בלי גבול מפני שהם למעלה מן החכמה כידוע ועליהם נאמר ואת ארבע הידות<sup data-n=\"3147\">51</sup> כו' וד\"ל. כי חו\"ג כ\"א כלול מב' [מדות כו', ולהיות כי הרבה הן גבוהים מן המוח שבראש לכך יכולים] להגביה הידים הגבה למעלה מן הראש וכמ\"ש במ\"א בענין נשיאת כפים וישא אהרן [את] ידיו<sup data-n=\"3148\">52</sup> כו' ששרש הידים הוא בבחי' רדל\"א שהחכ' ומוחין שבראש הוא סוף מדרגתו בחי' מל' שבו כו'. וזהו אשר נשאתי את ידי יד כהה<sup data-n=\"3149\">53</sup> דמל' דאצי' שירדה בסתר המדרגות נשאתי אותם<sup data-n=\"3150\">*54</sup> הגבה למעלה מראשו כו', והן בחי' חג\"ת דא\"א שיכולים להשפיל עצמם למטה מטה ולהגביה למקום הגבוה מאד נעלה מן הראש ומוחין וכמ\"ש ומתחת זרועות עולם<sup data-n=\"3151\">54</sup> כו' וכמ\"ש במ\"א וד\"ל. וזהו עיקר ההוראה על עוצם הפלאת מדרגתם למעלה [מן] הראש במה שיכולים להשפיל עצמם מאד למטה מטה כו', וכמ\"ש במ\"א בענין ימינך פשוטה<sup data-n=\"3152\">55</sup> [מטה מטה] לקבל השבים מחמת שהי[א] יד הגדולה הגבה למעלה מן הראש כו' וד\"ל. והיינו שעליות המל' יהי' מהארת הכתר דוקא וכמ\"ש וגאלתיך אנכי<sup data-n=\"3153\">56</sup> מי שאנכי<sup data-n=\"3154\">57</sup> כו' מטעם הנ\"ל שנעוץ <span data-k=\"pg\">212</span> ּ תחלתן בסופן כי אשת חיל עט\"ב לפי שהרצון עיקרו בתושבע\"פ, וכמ\"ש ונתתי צבי בארץ החיים כנ\"ל וד\"ל.\n<b>וזהו</b> אשר נשאתי אותה והעליתיה כ\"כ בעליות המדריגות עד שתהי' עטרת תפארת<sup data-n=\"3155\">58</sup> לאברהם וליצחק כו' וכמ\"ש והיית עטרת תפארת כו' צניף מלוכה בכף אלקיך<sup data-n=\"3156\">59</sup>, פי' עטרת תפארת ידוע כי הפאר שבעטרה שעל הראש של אדם זה לא ידמה לפאר עטרת זו בראשו של אדם א[חר] נמוך ממנו במדרגה וכיוצא בזה. אמנם העטרה בעצמה כשאינה בראש כל אדם רק תלוי' ועומדת הנה הי[א] כלולה מכל מיני פאר שבעולם שהרי כאשר ילבשנה אדם זה יתפאר בה באופן פרטי ואדם אחר יתפאר באופן אחר, אבל בעצמותם הי'<sup data-n=\"3157\">60</sup> גבוה מאד נעלה מן ההתפארות לגמרי, כי ההתפארות הוא ע\"י האדם שהוא בחי' כלי אליה ולפי אופן הכלי יהי' בה אור הפאר וההידור, משא\"כ כשהי[א] בלא כלי הרי ההתפארות בה בעצם<sup data-n=\"3158\">61</sup> ולא בפועל וכמ\"ש במ\"א וד\"ל. וזהו עטרת שהי[א] תפארת לכל לובשה כו', וע\"ד משל זה יובן למעלה דכתר",[["3145","49","<b>והבאתי אתכם</b>: וארא ו, ח."],["3146","50","<b>תג\"ת דא\"א. . יד הגדולה יד החזקה</b>: בשלח יד, לא. בא יג, ט. ראה גם שעה\"י קכז, ב. שע\"ת קג, ד. מאמרי אדה\"א ויקרא ח\"א ע' ריג. וש\"נ."],["3147","51","<b>ואת ארבע הידות</b>: ויגש מז, כד [ושם: וארבע]."],["3148","52","<b>וישא אהרן [את] ידיו</b>: שמיני ט, כב. ראה גם לקמן פ' בשלח רה, ד. תצוה שנה, ב. מאמרי אדה\"א ויקרא ח\"א ע' ריח. דברים ח\"ד ע' א'שצג. וש\"נ. נ\"ך ע' שמו. וש\"נ."],["3149","53","<b>את ידי יד כהה</b>: ראה גם לעיל ע, ד הערה 80."],["3150","*54","<b>אותם</b>: אוצ\"ל: אותה."],["3151","54","<b>ומתחת זרועות עולם</b>: ראה גם לעיל נה, ד. וש\"נ."],["3152","55","<b>ימינך פשוטה</b>: תפלת נעילה. ראה גם לקמן פ' בשלח רד, ב. מאמרי אדה\"א בראשית ע' תקח וע' תקנז."],["3153","56","<b>וגאלתיך אנכי</b>: רות ג, יג."],["3154","57","<b>אנכי מי שאנכי</b>: נסמן לעיל סג, ד."],["3155","58","<b>עטרת תפארת</b>: נסמן בהערה הבאה."],["3156","59","<b>והיית עטרת. . אלקיך</b>: ישעי' סב, ג [ושם: וצניף]."],["3157","60","<b>בעצמותם הי'</b>: אג: בעצמותו הוא."],["3158","61","<b>ההתפארות בה בעצם</b>: ראה גם מאמרי אדה\"א קונטרסים ע' תקע. בראשית ע' שיט. וש\"נ."]]],[2300540272,"דז\"א מת\"ת דאימא<sup data-n=\"3159\">65</sup><sup data-n=\"3160\">62</sup> ה\"ז ענין תפארת פרטי לז\"א הנק' אדם<sup data-n=\"3161\">63</sup> העליון כידוע, ואמנם בחי' ת\"ת דאימא שהוא כתר לאו\"א<sup data-n=\"3162\">64</sup> הוא ענין הפאר בעצם ולא בפועל כמ\"ש<sup data-n=\"3163\">66</sup> העטרה בעצמה כנ\"ל. וזהו והיתה עטרת תפארת עד שתשלח הארת ההתפארות להיות כתר גם לז\"א בעלה כמ\"ש עטרת בעלה כו' וכ\"ז הוא מסיבת העליות המל' ישכיל עבדי<sup data-n=\"3164\">67</sup> ירום ונשא וגבה מאד עד שתהי' צניף מלוכה בכנף<sup data-n=\"3165\">68</sup> אלקיך פי' בחג\"ת דא\"א כנ\"ל וד\"ל.",[["3159","65","<b>דאימא</b>: א: דאריך. ג: דא\"א. וראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670142\" data-slug=\"torat-chaim\" data-id=\"2300670142\">תו\"ח נח סה, ב</a> ובהערה 23."],["3160","62","<b>דכתר דז\"א מת\"ת דאימא</b>: נסמן לעיל נג, א."],["3161","63","<b>לז\"א הנק' אדם</b>: נסמן לעיל נה, ג."],["3162","64","<b>ת\"ת דאריך. . לאו\"א</b>: ראה ע\"ח (שער א\"א) שי\"ג, פ\"ז."],["3163","66","<b>כמ\"ש</b>: אג: וכמשל."],["3164","67","<b>ישכיל עבדי</b>: ישעי' נב, יג."],["3165","68","<b>בכנף</b>: א: בכף."]]],[2300540060,"<b>בעז\"ה תורת אדמו\"ר הרב ר' דובער פרשה וארא באברוסק שנת תקפ\"ד יום א.</b>\n<span data-k=\"pg\">קו</span> ּ<b>הוא</b> אהרן ומשה<sup data-n=\"3166\">1</sup> אשר אמר ה' להם<sup data-n=\"3167\">2</sup> כו' הם המדברים אל פרעה כו' הוא משה ואהרן<sup data-n=\"3168\">3</sup>, הנה בכדי לתרץ כל הדקדוקים שבפ' זו יש להקדים תחלה בשרש ענין משה ואהרן [כ]ידוע שהתורה נצחית<sup data-n=\"3169\">4</sup> בכל דור ובכל זמן ובכל אדם מישראל, וגם עתה יש בחי' משה ואהרן המוצ[י]אים מארץ מצרים והם המדברים כו'. והנה ידוע בזהר בכמה מקומות דמשה נק' שושבינא דמלכא<sup data-n=\"3170\">5</sup> ואהרן נק' שושבינא דמטרוניתא<sup data-n=\"3171\">6</sup>, והענין הוא כידוע בענין שושבינא שהוא המנהיג ומוליך את הכלה ומביאה<sup data-n=\"3172\">*7</sup> מבית אביה לבית החתן ולייחד אותה עם החתן בחופה תחלה ואח\"כ ליחוד גמור כו'. וכך הוא ענין אהרן שושבינא דמטרוניתא שמוליך ומביא לכנ\"י שנק' כלה ומעלה אותה לייחדה בהקב\"ה שנק' חתן<sup data-n=\"3173\">7</sup> כידוע, [וכמו] ביצ\"מ דכתיב וארשתיך לי באמונה<sup data-n=\"3174\">8</sup> כו', שהי' אהרן מעורר לבנ\"י שיקבלו תומ\"צ ע\"י משה שהי' שליח מה' אליהם שלזה נק' משה שושבינא דמלכא להוריד ולהביא את החתן לגבי הכלה כו'. וכמו\"כ במ\"ת הי' אהרן המעלה ומביא לכנ\"י לקבל התורה ע\"י משה ומשה הי' שוש' דמלכא להיות שע\"י נמשך גילוי אור הוי' לדבר י' דברות כמ\"ש וירד ה'<sup data-n=\"3175\">9</sup> כו' וכתיב משה ידבר<sup data-n=\"3176\">10</sup> כו' וד\"ל. וכך הוא בכל דור ובכל זמן יש",[["3166","1","<b>הוא אהרן ומשה</b>: המאמר מיוסד על שני דרושי אדה\"ז. חלק הראשון [עד לקמן פד, ג] מיוסד על ד\"ה הוא אהרן ומשה שנדפס במאמרי אדה\"ז תקס\"ג ח\"א ע' קכב ואילך. [ובע' קלה שם נמצא ביאור על המאמר. וקיצור מהצ\"צ על המאמר נדפס במאמרי אדה\"ז תקס\"ב ח\"א ע' רצא]. חלק השני [ד\"ה ומעתה — לקמן פד, ג] כנראה מיוסד על סיום ד\"ה וידבר. . ויצוום משנת תקס\"ח, הנדפס באוה\"ת וארא ע' רח. וראה עוד ע\"ד מאמר זה וזמן אמירתו להלן ברשימת הכת\"י [ושם ג\"כ מפורט סימני האותיות הבאים להלן בהמראי מקומות]."],["3167","2","<b>הוא אהרן. . להם</b>: וארא ו, כו. בתו\"ח כאן: בפסוק הוא אהרן — אבל בכל הכת\"י ליתא."],["3168","3","<b>הם המדברים. . ואהרן</b>: וארא שם, כז."],["3169","4","<b>שהתורה נצחית</b>: נסמן לעיל פ' שמות א, א."],["3170","5","<b>דמשה נק' שושבינא דמלכא</b>: נסמן לעיל פ' שמות יא, ג."],["3171","6","<b>ואהרן. . דמטרוניתא</b>: ראה זהר (רע\"מ) ויקרא כ, א. הנסמן במאמרי אדה\"א דברים ח\"א ע' קג. שמות ח\"ב ע' שטו וע' שמ."],["3172","*7","<b>את הכלה ומביאה</b>: בד: ומביא את הכלה."],["3173","7","<b>לכנ\"י שנק' כלה. . חתן</b>: וכל שה\"ש מיוסד ע\"ז, כידוע במדרש רז\"ל. ראה גם לקמן פ' תצוה שמה, ד. שמח, א. מאמרי אדה\"א נ\"ך ע' רלא. וש\"נ. הנחות תקע\"ז ע' שסה."],["3174","8","<b>וארשתיך לי באמונה</b>: הושע ב, כב."],["3175","9","<b>וירד ה'</b>: יתרו יט, כ."],["3176","10","<b>משה ידבר</b>: יתרו שם, יט."]]],[2300540098,"בחי' אהרן המעלה ומביא לבנ\"י<sup data-n=\"3177\">11</sup> לנש\"י שנק' כלה שיתעוררו באה\"ר ותשוקה שלימה לדבקה בו ית' ע\"י תומ\"צ כו', ובחי' משה שהוא המעורר החתן להיות גילוי אור אלקות מלמעלה למטה בנש\"י בתומ\"צ, שהם עושים כמו שהי' במ\"ת ממש כידוע וד\"ל. והנה כללות ענין העלאה דכנ\"י למעלה הי' ע\"י אהרן בהדלקת נרות המנורה בבהמ\"ק דכתיב בהעלותך את הנרות<sup data-n=\"3178\">12</sup> שהן כללות נש\"י ששרשם בשבעה מדות דאצי' וכל מדה כלולה מעשר שהן ע' נפש דיעקב כידוע, ומשם נמשך לכל הענפים [הפרטים] המסתעפי' בכל דור עד ימוהמ\"ש עד ניצוץ קטן שבישראל שנק' נר ה' כמ\"ש נר ה' נשמת אדם<sup data-n=\"3179\">13</sup> וכתיב כי אתה תאיר נרי<sup data-n=\"3180\">14</sup> וכן כי אתה נרי ה'<sup data-n=\"3181\">15</sup> וקאי בכללות נש\"י ובפרטי פרטות גם בהיותם בגלות שנק' חושך וכמ\"ש וה' יגיה חשכי<sup data-n=\"3182\">16</sup> כמ\"ש במ\"א. וז\"ש רז\"ל גבי מנורה וכי לאורה הוא צריך<sup data-n=\"3183\">17</sup> אלא עדות הוא שהשכינה שורה בישראל, והוא ע\"י העלאת אהרן דוקא כמ\"ש בהעלותך את הנרות שהוא המעלה לנש\"י שנק' נרות שיהיו מאירים מאור ה' תמיד (ולכך נק' שודמ\"ט, אבל גבי משה אמר ואתה תצוה<sup data-n=\"3184\">18</sup> [כו'] ויקחו אליך כו' כתית למאור שהוא בחי' המשכת האור ממקורו לבנ\"י ע\"כ נק' שוש' דמלכא כמו במ\"ת כו').\n<b>ולהבין</b> ביאור זה הנה יש להקדים ענין הידוע בטעם ירידת הנשמה בגוף שהוא לצורך עלי'<sup data-n=\"3185\">19</sup> למעלה ממקור חוצבו דוקא, ויש להקדים תחלה ענין ההשתל' שנק' ממכ\"ע שעז\"נ המחדש בכל יום מע\"ב<sup data-n=\"3186\">20</sup> פי' מחדש מאין ליש [ממש] כידוע, להיות ידוע שזהו עד\"מ התלבשות הנפש בגוף ממש שחיות הרוחני של הנפש מורכב בדם ובשר ואיברים להחיותם תמיד מחדש, ובהסתלקות החיות הרוחני' אף רגע א'<sup data-n=\"3187\">21</sup> אין להם קיום כו' (והוא ענין אדם א' דם<sup data-n=\"3188\">22</sup> שזה שא' כי הדם הוא הנפש<sup data-n=\"3189\">23</sup> כידוע). כך הוא ענין התפשטות והתלבשות אור וחיות אלקי בכל העולם כנפש בגוף וכמ\"ש ואתה מחי' את כולם<sup data-n=\"3190\">24</sup> גם עולמות העליוני' הרוחני' כג\"ע העליון והתחתון וכל רבוא רבבות מלאכים וצבאות<sup data-n=\"3191\">25</sup> שבג' עולמות בי\"ע עד ע\"ש<sup data-n=\"3192\">26</sup> וצבא השמים",[["3177","11","<b>לבנ\"י</b>: בד: ליתא."],["3178","12","<b>בהעלותך את הנרות</b>: בהעלותך ח, ב. ראה מאמרי אדה\"א במדבר ח\"ג ע' תתפא ואילך. וש\"נ. שערי אורה ע' 82."],["3179","13","<b>נר ה' נשמת אדם</b>: משלי כ, כז. ראה גם מאמרי אדה\"ז תקס\"ה ח\"א ע' קכד ואילך."],["3180","14","<b>כי אתה תאיר נרי</b>: תהלים יט, כט."],["3181","15","<b>כי אתה נרי ה'</b>: שמואל-ב כב, כט."],["3182","16","<b>וה' יגיה חשכי</b>: המשך הכתוב כי אתה נרי. ראה גם מאמרי אדה\"ז תקס\"ה שם ע' קכז. תקס\"ח ח\"ב ע' תרנ וע' תרנז. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370185\" data-slug=\"torah-or\" data-id=\"3901370185\">תו\"א מקץ מא, א</a>. ג."],["3183","17","<b>וכי לאורה הוא צריך</b>: שבת כב, ב."],["3184","18","<b>ואתה תצוה</b>: תצוה כז, כ."],["3185","19","<b>ירידת הנשמה. . לצורך עלי'</b>: נסמן לעיל ד, ג."],["3186","20","<b>המחדש </b>[בד: מחדש]<b>. . מע\"ב</b>: ע\"פ ברכת יוצר."],["3187","21","<b>א'</b>: בד: ליתא."],["3188","22","<b>אדם א' דם</b>: ראה מבו\"ש ש\"ה, ח\"ב פ\"ה. של\"ה (בהקדמת ב\"י ב\"ד) כא, א. הנסמן במאמרי אדה\"א דברים ח\"ד ע' א'תמב. תו\"ח בראשית לה, א ובהנסמן במ\"מ לשם."],["3189","23","<b>כי הדם הוא הנפש</b>: פ' ראה יב, כג."],["3190","24","<b>ואתה מחי' את כולם</b>: נחמי' ט, ו."],["3191","25","<b>מלאכים וצבאות</b>: במאמרי אדה\"ז תקס\"ג כאן (ע' קכג): צבאות המלאכים והנשמות."],["3192","26","<b>ע\"ש</b>: ע' שרים. בד: עשי'. גט: כבפנים."]]],[2300540136,"<span data-k=\"pg\">214</span> ּ והארץ וכל אשר בה מדצח\"מ וארמ\"ע כו', הכל חיים וקיימים מאור שפע אלקי ממקור חיים העליונים שהוא א\"ס ב\"ה שנק' חיי החיים<sup data-n=\"3193\">27</sup> שמתלבש במדת מל' דאצי' כידוע במ\"ש מלכותך מכ\"ע<sup data-n=\"3194\">28</sup> ומל' בכל משלה<sup data-n=\"3195\">29</sup>, וזה האור וחיות האלקי מתחדש בכל יום ועת ושעה ממש כו'. וזהו מחדש בכ\"י מע\"ב באור וחיות חדש ממש (כידוע די\"ב שעות<sup data-n=\"3196\">30</sup> היום הן י\"ב צירופי הוי'<sup data-n=\"3197\">31</sup> י\"ב שעות הלילה הן י\"ב צירופי אד' כו' כמ\"ש במ\"א), וכתיב חדשים לבקרים רבה אמונתך<sup data-n=\"3198\">32</sup> שבכל בוקר מתחדש אמונתך שהוא אור וחיות אלקי בעולמות מאין ליש, והוא ע\"י העלאת מ\"ן דמלאכים שאומרים שירה בכל בוקר כמ\"ש ברן יחד כוכבי בוקר<sup data-n=\"3199\">33</sup> [ויריעו] כו' בבחי' ביטול היש לאין שממשיכי' המשכת<sup data-n=\"3200\">34</sup> אור אלקי חדש מאין ליש כמ\"ש והחיות רו\"ש<sup data-n=\"3201\">35</sup> כו', כמו עד\"מ באור וחיות הרוחני שבנפש שע\"י העלא' הדם באברים [ב]דופק שבלב חוזר ונמשך חיות חדש כו' כידוע. ונמצא ע\"ד<sup data-n=\"3202\">36</sup> כמו שהנפש הרוחני מתפשטת מהעלאה דחיי בשר כך למעלה בנפש כל חיי העולמים שהוא בחי' מדת מל' מתפעלת מהעלא' מ\"ן דמלאכים ונשמות שבג' עולמות בי\"ע, וז\"ש חדשים לבקרים כו'. ואע\"פ שנאמר כי עמך מק\"ח [כו'], עמך טפל ובטל וכלא חשיב ממש כל בחי' מקור חיים העליונים ותחתונים שמחי' את כולם, לפי שאין זה רק בחי' הארה דהארה לבד מעצם כח ומהות כח [ו]אור האלקי דמדת מל' כמ\"ש באורך<sup data-n=\"3203\">37</sup> נראה אור של תולדה כידוע ומבואר במ\"א מפני שהוא ע\"י צמצום והסתר דשם אלקי' כו' (והוא ע\"י המסך המפסיק בין א[צילות ל]בי\"ע כו'), עכ\"ז מחדש בכ\"י מע\"ב ע\"י העלאת מ\"ן דעולמות כו'<sup data-n=\"3204\">38</sup> להיות מתצמצם ומתלבש בבחי' כח ואור חיות נפש בגוף כו'<sup data-n=\"3205\">50</sup> וכמ\"ש אתה אל מסתתר<sup data-n=\"3206\">39</sup> כו' וכתיב ה' מלך גיאות לבש<sup data-n=\"3207\">40</sup> בבחי' התלבשות כנ\"ל<sup data-n=\"3208\">41</sup> וד\"ל.\n<b>והנה</b> כ\"ז הוא [נק' בחי' ממכ\"ע שהוא שם אלקים ושם אד' דאשתמודע אדון על כולא<sup data-n=\"3209\">42</sup> כו' אבל בחי' סוכ\"ע הוא] הנק' קדוש שקדוש ומובדל ומרומם בערך מכל ההשתל' הזאת דשם אלקים הנק' ממכ\"ע הנ\"ל והוא שם הוי' דאצי' כידוע. והענין הוא שאין זה האור בא בבחי' השפעות והמשכות אור וחיות להוות מאין ליש כחיי הנפש בגוף ולהיות מתפעל מהעלאת מ\"ן כו', אלא הוא בבחי' סובב ומקיף לכל ההשתלשלו' [העולמות]",[["3193","27","<b>חיי החיים</b>: יומא עא, א."],["3194","28","<b>מלכותך מכ\"ע</b>: תהלים קמה, יג."],["3195","29","<b>ומל' בכל משלה</b>: תהלים קג, יט."],["3196","30","<b>די\"ב שעות. . הוי'. . אד'</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310046\" data-slug=\"tanya\" data-id=\"3401310046\">תניא פמ\"א (נח, ב</a>). מכתב לר\"י פייגין נדפס ברשימות חוברת קמא. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתב. שיחת אחרון של פסח תשמ\"ז סי\"א, נדפס בהתוועדויות ח\"ג ע' 127."],["3197","31","<b>י\"ב צירופי הוי'</b>: נסמן לעיל פ' שמות כ, ג."],["3198","32","<b>חדשים לבקרים רבה אמונתך</b>: איכה ג, כג. ראה גם לקמן פ' בא צג, ד. וש\"נ."],["3199","33","<b>ברן יחד כוכבי בקר</b>: איוב לח, ז. וראה גם לקמן עד, א בשם הזהר."],["3200","34","<b>המשכת</b>: בד: ליתא. ג: כבפנים."],["3201","35","<b>והחיות רו\"ש</b>: יחזקאל א, יד."],["3202","36","<b>ע\"ד</b>: בד: שלפ\"ע. ט: שלפ\"ז."],["3203","37","<b>כי עמך. . באורך</b>: תהלים לו, י. נסמן לעיל ס, ב הערה 24."],["3204","38","<b>כו'</b>: בד: כנ\"ל."],["3205","50","<b>כו'</b>: בד: כלל."],["3206","39","<b>אתה אל מסתתר</b>: ישעי' מה, טו."],["3207","40","<b>ה' מלך גיאות לבש</b>: תהלים צג, א."],["3208","41","<b>כנ\"ל</b>: בד: עכ\"פ כו' כידוע."],["3209","42","<b>דאשתמודע אדון על כולא</b>: ת\"ז בהקדמה (יז, ב)."]]],[2300540173,"כולם מראש לסוף יחד בהשוואה א' ממש בלי חילוק מדרגות כלל וכלל עד ששוין לפניו ג\"ע העליון וגעה\"ת מהחל ועד<sup data-n=\"3210\">*43</sup> סוף ותחתית המדרגות בעוה\"ז השפל כמ\"ש בשמים ממעל<sup data-n=\"3211\">43</sup> ועל הארץ מתחת אין עוד בשוה כו' וכמ\"ש כחשיכה כאורה<sup data-n=\"3212\">44</sup> כו' רוחני' וגשמי' שוין קטן וגדול<sup data-n=\"3213\">45</sup> כו'. וזהו המלך הגדול<sup data-n=\"3214\">46</sup> והקדוש בשמים ו[ב]ארץ [קדוש בשמים ובארץ] בשוה וכן אמר המגביהי לשבת המשפילי<sup data-n=\"3215\">47</sup> לראות בשמים ובארץ בשוה כו', והטעם הוא [לפי] שכל אור ושפע האלקי הבא בהשתל' העולמות אינו רק זיו והארה דהארה לבד ולא מעצם מהות אלקות, להיותו בא בריבוי הצמצומים והעלמות במיעוט אחר מיעוט שמפני זה בא האור והגילוי בחילוק מדרגות רבות מעליון לתחתון כו' (ועד\"מ הנפש בגוף שאין זה רק הארה בעלמא מעצם הנפש). אבל שם הוי' דבחי' סובב כ\"ע הוא מהות ועצמות אור האלקי ששם כלא חשיבי גם כל מקור החיים כנ\"ל כמ\"ש כי עמך מקו\"ח כו'<sup data-n=\"3216\">48</sup> <span data-k=\"pg\">קז</span> ּ ע\"כ אני ה' לא שניתי<sup data-n=\"3217\">49</sup> כו' בין קודם שנבה\"ע וכמאמר אתה הוא<sup data-n=\"3218\">51</sup> כו', ולכך נק' סוכ\"ע בשם מקיף לכולם יחד בהשוואה אחת ממש בלי חילוק מדריגות כלל כידוע. וזהו כל עיקר ענין יחוד קוב\"ה ושכינתי' [ש]זש\"א וידעת היום<sup data-n=\"3219\">52</sup> כו' כי ה' הוא האלקים כולא חד<sup data-n=\"3220\">53</sup> מטעם הנ\"ל, וגם שם אלקים המתצמצם גם הוא קדוש ומובדל מן העולמות כמ\"ש המלך המרומם<sup data-n=\"3221\">54</sup> לבדו [מתנשא] מימ\"ע (וחיות<sup data-n=\"3222\">55</sup> הנפש בגוף גם הוא רוחני' ונכלל בעצם הנפש כו').\n<b>וזהו</b> הטעם שסדרו אנכה\"ג לומר הודו<sup data-n=\"3223\">56</sup> קודם פסוד\"ז דוקא כי הנה מבואר למעלה שהוא כענין<sup data-n=\"3224\">57</sup> ב' מדרגות ממכ\"ע וסוכ\"ע<sup data-n=\"3225\">*58</sup> שהן ב' שמות דהוי' ואלקי'<sup data-n=\"3226\">58</sup>, וסדרו בסדר המדרגות מלמטה למעלה שהוא בבחי' ההודאה להוי' כמ\"ש הודו להוי' בבחי' סוכ\"ע קראו בשמו<sup data-n=\"3227\">59</sup> שהוא שם אלקים בשמו<sup data-n=\"3228\">*60</sup> הנק' שם הפעולה שהוא התפשטות פעולתו בעולמות כמ\"ש לכו חזו<sup data-n=\"3229\">60</sup> מפעלות אלקי' אשר כו'. וזהו קראו בשמו שהקריאה הוא המשכה בגילוי למטה, אבל בהוי' אינו יכול להשיג רק בהודאה מרחוק להיותו למעלה מן ההשתל' ונק' קדוש כו'. והודאה זו היא הכנה לפסוד\"ז ששם הוא ההלל והשבח לשם הוי' כמו הללו את הוי'<sup data-n=\"3230\">61</sup> כו' הללי נפשי את הוי'<sup data-n=\"3231\">62</sup> וכה\"ג, לכך התחלת פסוד\"ז בתהלה לדוד<sup data-n=\"3232\">63</sup> ארוממך אלקי המלך ומעלה לבחי'<sup data-n=\"3233\">64</sup> המל' כו'.",[["3210","*43","<b>וגעה\"ת מהחל ועד</b>: בד: וגעה\"ת מהכל עד. ג: הכל עם. טיט: מהכל עד. כ: וגעה\"ת עד."],["3211","43","<b>בשמים ממעל</b>: ואתחנן ד, לט."],["3212","44","<b>כחשיכה כאורה</b>: תהלים קלט, יב."],["3213","45","<b>קטן וגדול</b>: איוב ג, יח."],["3214","46","<b>המלך הגדול</b>: ברכת ישתבח."],["3215","47","<b>המגביהי. . המשפילי</b>: תהלים קיג, ה. ו."],["3216","48","<b>כנ\"ל. . מקו\"ח כו'</b>: בד: כו'. . כו' כנ\"ל."],["3217","49","<b>אני ה' לא שניתי</b>: מלאכי ג, ו."],["3218","51","<b>אתה הוא</b>: נוסח תפלת השחר."],["3219","52","<b>וידעת היום</b>: ואתחנן ד, לט."],["3220","53","<b>כולא חד</b>: נסמן לעיל ס, א."],["3221","54","<b>המלך המרומם</b>: ע\"פ ברכת יוצר."],["3222","55","<b>וחיות</b>: בד: כמשל חיות."],["3223","56","<b>שסדרו אנכה\"ג לומר הודו</b>: וכ\"ה במאמרי אדה\"ז תקס\"ג כאן (ריש ע' קכד). וראה שער הכולל פ\"ה, ס\"א-ב."],["3224","57","<b>שהוא כענין</b>: בד: בענין."],["3225","*58","<b>ממכ\"ע וסוכ\"ע</b>: זהר (רע\"מ) פינחס רכה, א."],["3226","58","<b>ממכ\"ע וסוכ\"ע. . דהוי' ואלקי'</b>: ראה גם מאמרי אדה\"ז תקס\"ו ע' קכא. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680144\" data-slug=\"torat-chaim\" data-id=\"2300680144\">תו\"ח וישב קצט, ד</a> ובהערה 62. לקמן פ' בא צב, א. קי, ד. בשלח קסב, א. יתרו רנב, ב. רסח, ג. תצוה שלט, ג. שסד, ג. ויקהל שפח, ג."],["3227","59","<b>הודו להוי'. . קראו בשמו</b>: דהי\"א טז, ח."],["3228","*60","<b>בשמו</b>: גט: אחד משמותיו."],["3229","60","<b>לכו חזו</b>: נסמן לעיל ס, ד."],["3230","61","<b>הללו את הוי'</b>: תהלים קמח, א."],["3231","62","<b>הללי נפשי את הוי'</b>: תהלים קמו, א."],["3232","63","<b>בתהלה לדוד</b>: תהלים קמה, א."],["3233","64","<b>ומעלה לבחי'</b>: בד: למעלה לבחי'. גט: למעלה מבחי'."]]],[2300540210,"ואמנם יש עוד ענין בהודאה זו כנ\"ל שאדם<sup data-n=\"3234\">65</sup> נותן תודה להוי' בצאתו מן החשך לאור כמו היוצא מבית הסוהר וכה\"ג (וכעין ענין ד' צריכין להודות<sup data-n=\"3235\">66</sup> אשר יצאו מן המות לחיים בגשמיות כך הוא ברוחני' בצאתו מן המות לחיים ברוחני'). כי הנה ידוע שהנשמה [ה]אלקי' טבעה לעלות ולידבק במקור חוצבה באלקים חיים כמ\"ש רוח האדם העולה<sup data-n=\"3236\">67</sup> כו', אך מצד התלבשות חומר גס הגופני שמורכב מד\"י גשמיים ומעורב ברע גמור דק\"נ שהוא יצר לב האדם רע בטבעו כו', ומה גם שמצד ההסתר אור אלקי בתכלית בעוה\"ז השפל שבא שם האור אחר רבוי הצמצומי' היותר אחרון כו' (והן מ\"ח צירופי'<sup data-n=\"3237\">68</sup> אחרונים דשם אלקים, שמקבלים יניקה מע\"ס<sup data-n=\"3238\">69</sup> דנוגה דעשי') שלזה נראה העולם ומלואו לבחי' יש ודבר נפרד מיחוד אלקות עד שיכולים לומר עזב ה' את הארץ בדרכי הטבע כו'. ואע\"פ שהנשמה אלקי' מכרת ליוצרה שהוא מקור כל העולמות ונראה מושג בראי' השכל התהוות הברואי' מאין ליש כמו שאו מרום עיניכם<sup data-n=\"3239\">70</sup> כו'<sup data-n=\"3240\">71</sup> וראו מי ברא אלה כו' איך שהטפל בטל לעיקר כמו צבא השמים שמשתחוים בביטול היש לאין תמיד ומחדש מע\"ב בכ\"י כנ\"ל. אבל מצד בחי' [גסות] החומרי דנה\"ט מחשיך אורה ולבוש שק דק\"נ שהוא התגשמות זה העולם השפל ומסתירים ומחשיכים לנשמה לאור האלקי המאיר עלי' [מכל צד] כו' עד שאין בכחו כלל להשיג ולהכיר בוראו כלל<sup data-n=\"3241\">72</sup>, וכש\"כ שלא יש בכחה להאיר במוח [ו]לב בשר הגופני כו' וה\"ז ממש כמו שיושב בבית האסורים בבור עמוק בחושך ואפילה שלא יראה אור כלל (או כמו חולה המסוכן שהגיע לשערי מות וכה\"ג). אך כאשר יצא מבית האסורים ויראה אור יתפעל מאד ויחי' נפשו בחיות חדש ממש על יציאתו מאפילה לאור גדול כו' שאז יתן תודה להוי'. וכך הוא ממש בנשמה האלקי' בצאתו ממאסר חושך הגופני המחשיך עליו ביותר כנ\"ל שזהו כמו יצא<sup data-n=\"3242\">73</sup> מבית האסורים בראותה אור האלקי שתשוב לאלקים ותאיר באור החיים\n<span data-k=\"pg\">216</span> ּ(והיינו ממש כמו שיצא מן המות לחיים גשמיים כו'). וזהו ענין יצ\"מ שחייב אדם בכ\"י<sup data-n=\"3243\">74</sup> לראות א\"ע כאלו יוצא ממצרים שהן נש\"ט<sup data-n=\"3244\">75</sup> דק\"ן וכמו שיצא[ו] ממצרים מאפילה לאור גדול<sup data-n=\"3245\">76</sup> מטעם זה כידוע וד\"ל. וענין יציא' מצרים [היינו] יציא' מן המיצר דנה\"ט שהחשיך ביותר שזהו כמו מאסר ותפיסא ממש (כי גם ביצי[\"מ]",[["3234","65","<b>כנ\"ל שאדם</b>: בד: כו' כאדם. גט: כאדם."],["3235","66","<b>ד' צריכין להודות</b>: ברכות נד, ב."],["3236","67","<b>רוח האדם העולה</b>: קהלת ג, כא [ושם: בני האדם]."],["3237","68","<b>מ\"ח צירופי'</b>: נסמן לעיל ל, ב."],["3238","69","<b>מע\"ס</b>: בד: משם ע\"ש ע' שרים."],["3239","70","<b>שאו מרום עיניכם</b>: ישעי' מ, כו."],["3240","71","<b>עיניכם כו'</b>: כ\"ה גם בבד. ג: כו'."],["3241","72","<b>כלל</b>: בד: ליתא."],["3242","73","<b>כמו יצא</b>: בד: כיוצא."],["3243","74","<b>שחייב אדם בכ\"י</b>: ראה מאמרי אדה\"ז תקס\"ג כאן (ע' קכד): כידוע בדרז\"ל. <a class=\"ft-cite\" href=\"#/read/tanya/3401310052\" data-slug=\"tanya\" data-id=\"3401310052\">תניא פמ\"ז</a>. מאמרי אדה\"א שמות ח\"א ס\"ע צב ואילך. וש\"נ. ויקרא ח\"א ע' סה. שה\"א ע' לט."],["3244","75","<b>נש\"ט</b>: נסמן לעיל פ' שמות מא, ד."],["3245","76","<b>מאפילה לאור גדול</b>: פסחים קטז, ב [במשנה]. הגש\"פ פיסקא לפיכך."]]],[2300540242,"הרי הנשמה נכנסה בגוף בע\"כ כמו שמורידים ומושיבים אדם בבור אסור בנחושתים וז\"ש ואתה נפחת בי<sup data-n=\"3246\">77</sup> בע\"כ נכנסה לגוף רק אתה נפחת בי כו') (כמו באדה\"ר דכתי' ויפח באפיו נ\"ח<sup data-n=\"3247\">78</sup> שבודאי ירד בע\"כ מעצמות אוא\"ס<sup data-n=\"3248\">79</sup> ב\"ה לחומר גופני וכו') שזהו כמו נפילה וירידה מאיגרא רמה<sup data-n=\"3249\">80</sup> לבירא עמיקתא וע\"כ אתה חי, ובצאתו<sup data-n=\"3250\">81</sup> מן המאסר הגופני נק' יצ\"מ שיצא מן המיצר כו' וד\"ל. ועכ\"ז בפטירת הנשמה מן הגוף קשה לה פרידתה<sup data-n=\"3251\">82</sup> מן הגוף ביותר כמ\"ש בזהר, לפי שכל חייו בגוף הי' שפע אור האלקי במוח ולב הגופני באוי\"ר האלקי' ובתומ\"צ כו' שזהו כיחוד דכר ונוק'<sup data-n=\"3252\">83</sup> כו' ע\"כ קשה לה פרידתה, וראי' מתחה\"מ לכל נשמה אלקי' תחזור לגופה<sup data-n=\"3253\">84</sup> דייקא כו', וזהו ע\"כ אתה חי וע\"כ אתה מת<sup data-n=\"3254\">85</sup> וקאי על נש\"י שתחל[ת]ה בע\"כ וסופה בע\"כ כו'. אבל לכאו' זה סותר ענין הנ\"ל ביצ\"מ שזהו כיוצא מן המאסר וכו', והאמת הוא דגם הגוף עולה עמה<sup data-n=\"3255\">86</sup> בבחי' הודאה זו (כמשי\"ת), וזהו פי' הודו לה' שהנשמה תתן תודה לה' כאדם שנותן תודה לה' ביציאתו מן החושך לאור כנ\"ל וד\"ל.\n<b>ועוד</b> יתפרש [ב]ענין הודאה זו כאדם המודה לחבירו ע\"ד שנתווכח עמו שהאמת כדבריו ולא כמו שהי' סבור בתחלה, והענין הוא שכאשר תאיר אור האלקי על הנשמה בצאתה מ[ן החשך] חומר גופני תתן הודאה על האמת, שהאמת הוא שהבורא ית' הוא עיקרא ושרשא דכל עלמין<sup data-n=\"3256\">87</sup> כו' הוא מקור כל החיים והנבראים, מאמיתות המצאו<sup data-n=\"3257\">88</sup> נמצאו כל הנבראים<sup data-n=\"3258\">89</sup> מאין ליש, וכולא קמי' כ\"ח<sup data-n=\"3259\">90</sup> ממש, היפוך ממש [ממה] שהי' תחלה בדמיון האנושי הכוזב שעושה טפל לעיקר, להיות שההסתר וצמצום [ה]גדול אשר בעוה\"ז [השפל] מחשיך ומסתיר על האמת ומראה העולם ליש ודבר בפ\"ע נפרד מיחודו ית' (וזהו מארז\"ל ישראל שבח\"ל דוקא עע\"א בטהרה<sup data-n=\"3260\">91</sup> לפי שע\"ס<sup data-n=\"3261\">92</sup> דק\"נ מסתירים ביותר כאלו עע\"א בטהרה הן, לפי שעושים מהטפל עיקר [כמו] במס\"נ בשפע הפרנסה שבאמת אין מזל לישראל<sup data-n=\"3262\">93</sup> כי חלק הוי' [נק'] עמו<sup data-n=\"3263\">94</sup> כו' רק שנמשך ע\"י מזל בדרך התלבשות כמו גרזן ביד החוצב<sup data-n=\"3264\">95</sup> ובסוד גלות השכינה בע\"ש, וזהו כעובד לטפל כמ\"ש אותי עזבו כו' לחצוב להם בורות<sup data-n=\"3265\">96</sup> נשברים כו', משא\"כ בא\"י שאין ההסתר דלבוש שק<sup data-n=\"3266\">97</sup> שם כ\"כ ובפרט בזמן",[["3246","77","<b>ואתה נפחת בי</b>: ברכות ס, ב. ברכת אלקי נשמה. ראה לקמן פ' בשלח קלג, ד. תרומה שיג, ב. ויקהל שצד, ג. הנסמן במאמרי אדה\"א בראשית ע' עא. קונטרסים ע' קו. דרושי חתונה ח\"ב ע' תקצ."],["3247","78","<b>ויפח באפיו נ\"ח</b>: בראשית ב, ז."],["3248","79","<b>מעצמות אוא\"ס</b>: בד: מאוא\"ס. גט: כבפנים."],["3249","80","<b>מאיגרא רמה</b>: נסמן לעיל ד, ג."],["3250","81","<b>אתה חי ובצאתו</b>: בגדט: בצאתו."],["3251","82","<b>קשה לה פרידתה</b>: ראה מועד קטן כח, סע\"ב ואילך. זהר נשא קכו, ב. סה\"מ תרנ\"ט ס\"ע ז ואילך. תרמ\"ט ע' רלד. המשך תרס\"ו ע' תצא. לקו\"ש אבות (כרך ד) ע' 1218."],["3252","83","<b>הנשמה. . בגוף. . דכר ונוק'</b>: ראה זהר (ס\"ת) לך עט, א. (מדהנ\"ע) ח\"ש קכד, סע\"ב."],["3253","84","<b>מתחה\"מ לכל נשמה. . לגופה</b>: ראה סנהדרין צא, ב. ב\"ר ר\"פ צ\"ה. מאמרי אדה\"א הנחות תקע\"ז ס\"ע קפג. וש\"נ."],["3254","85","<b>ע\"כ אתה חי. . מת</b>: אבות ספ\"ד."],["3255","86","<b>עמה</b>: בתו\"ח באו כאן התיבות: ביציאתו מן החושך לאור כנ\"ל וד\"ל. ונשתרבבו לכאן מלהלן שו\"ה ביציאתו."],["3256","87","<b>עיקרא ושרשא דכל עלמין</b>: זהר בהקדמה יא, ב."],["3257","88","<b>מאמיתות המצאו</b>: ראה רמב\"ם ריש הל' יסוה\"ת."],["3258","89","<b>כל הנבראים</b>: בגד: ונבראו."],["3259","90","<b>וכולא קמי' כ\"ח</b>: נסמן לעיל פ' שמות לח, א."],["3260","91","<b>ישראל שבח\"ל. . עע\"א בטהרה</b>: נסמן לעיל פ' שמות לח, א."],["3261","92","<b>שע\"ס</b>: בד: שע\"ש שע' שרים."],["3262","93","<b>אין מזל לישראל</b>: נסמן לעיל פ' שמות ב, א."],["3263","94","<b>כי חלק הוי'. . עמו</b>: האזינו לב, ט."],["3264","95","<b>גרזן ביד החוצב</b>: ראה מו\"נ ח\"ג פכ\"ט. ישעי' י, טו."],["3265","96","<b>אותי עזבו. . בורות</b>: נסמן לעיל ב, א."],["3266","97","<b>בא\"י. . דלבוש שק</b>: ראה פרדס (שער אבי\"ע) שט\"ז, ספ\"א. ע\"ח (שער סדר אבי\"ע) שמ\"ז, ספ\"ו. מאמרי אדה\"א דברים ח\"ב ע' תצד. וש\"נ. קונטרסים ע' תקלג. וש\"נ. לקמן פ' בשלח קלד, א."]]],[2300540273,"בהמ\"ק כידוע וכה\"ג), וזהו כאדם המודה לחבירו שהאמת אתו כו'. וזהו מודים אנחנו לך<sup data-n=\"3267\">98</sup> בהודאה על האמת שאתה ה' כו'. וע\"כ גזרו אומר דמאן דלא כרע במודים<sup data-n=\"3268\">99</sup> אינו קם בתחה\"מ, לפי שלע\"ל יהי' גילוי אלקות על כל הנבראים וכמ\"ש וראו כל בשר<sup data-n=\"3269\">100</sup> כמד\"א וייראוך<sup data-n=\"3270\">101</sup> כל המעשים וישתחוו כו' שידע כל פעול<sup data-n=\"3271\">102</sup> כי אתה פעלתו בראי' חושי' ממש היפך מהסתר אלקו' דעכשיו כמ\"ש קודם חטא עה\"ד כו'<sup data-n=\"3272\">103</sup> וכמ\"ש ואת רוח<sup data-n=\"3273\">104</sup> הטומאה כו'. וראי' מחמורו של רפב\"י<sup data-n=\"3274\">105</sup>, וכבר הי' כן בפרות גשמיים שנשאו הארון שאמרו שירה<sup data-n=\"3275\">106</sup> <span data-k=\"pg\">קח</span> ּ כמו פני שור שבמרכבה ממש מפני גילוי אור האלקי בבחי' מל' שבארון האלקי, לכך נאמר לע\"ל לא ירעו<sup data-n=\"3276\">107</sup> כו' וגר זאב עם כבש<sup data-n=\"3277\">108</sup> כו'. אבל מאן דכרע במודים הגם שהוא הודאה חיצוני' נמשך בגרמי'<sup data-n=\"3278\">109</sup> שבשדרתו גילוי אלקות ויחי' ברוח אלקי ממש כמתים שהחי' יחזקאל<sup data-n=\"3279\">110</sup> כו', וזש\"א ועתה אלקינו<sup data-n=\"3280\">111</sup> מודים אנחנו לך עתה דוקא הודאה [זו] מרחוק ולע\"ל יהי' זה מצד בחי' גילוי אור ה' ממש וד\"ל.\n<b>והנה</b> הודאה זאת בהודו לה' כו' בא מצד הדעת והכרה באור האלקי המהווה את הכל ונק' הודאה שמצד השכל משום דבינה עד הוד אתפשטת<sup data-n=\"3281\">112</sup> כמו מזמור לתודה<sup data-n=\"3282\">113</sup> הריעו לה' דעו כי ה' כו' והוא<sup data-n=\"3283\">114</sup> עשנו כו' עד בואו שעריו בתודה<sup data-n=\"3284\">115</sup> כו', אבל כדי שיוכל להיות הודאה זו הקדימו אכנה\"ג בתחלה לומר ברכ[ו]ת השחר<sup data-n=\"3285\">116</sup> שהוא ענין הכנה להודו להוי' והוא שורש התחלת הודאה זו שבדעת והכרה, והוא לפי שברכ[ו]ת השחר תקנו לומר מיד שיקום האדם<sup data-n=\"3286\">117</sup> בבוקר מן השינה דוקא כידוע בפוסקי'. וכמו שהוא למעלה במלאכים עליונים דכתיב ברן יחד כוכבי בקר ויריעו כל בני אלקי' כו' וכתיב חדשים לבקרים רבה אמונתך, לבקרים<sup data-n=\"3287\">118</sup> דוקא, שכל שירה של המלאכים הוא בבוקר<sup data-n=\"3288\">119</sup> אור דוקא כמ\"ש בזהר וד\"ל.",[["3267","98","<b>מודים אנחנו לך</b>: תפלת שמו\"ע."],["3268","99","<b>דמאן דלא כרע במודים</b>: ראה ב\"ק טז, סע\"א. הנסמן במאמרי אדה\"א דברים ח\"א ע' שכג. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670438\" data-slug=\"torat-chaim\" data-id=\"2300670438\">תו\"ח נח נד, א</a> ובהערה 4. לקמן פ' בשלח קס, ג. פקודי תנא, ב. מאמרי אדה\"ז תקס\"ו ע' קמט ואילך."],["3269","100","<b>וראו כל בשר</b>: ישעי' מ, ה. וראה גם לקמן פ' בשלח קצה, ד. תצוה שכה, ב. שכט, ב. מאמרי אדה\"א נ\"ך ע' שפא. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680408\" data-slug=\"torat-chaim\" data-id=\"2300680408\">תו\"ח תולדות קנז, א</a>."],["3270","101","<b>כמד\"א </b>[ כמו דאמר ג: וכמ\"ש]<b> וייראוך</b>: תפלת העמידה לימים נוראים."],["3271","102","<b>שידע כל פעול</b>: תפלת העמידה לר\"ה."],["3272","103","<b>כמ\"ש. . כו'</b>: בד: כמו שהי'. . גט: ממש."],["3273","104","<b>וכמ\"ש ואת רוח</b>: זכרי' יג, ב. בד: מאחר שא' ורוח. — נסמן לעיל פ' שמות לט, ג."],["3274","105","<b>מחמורו של רפב\"י</b>: נסמן לקמן פ' בשלח קצה, ד."],["3275","106","<b>בפרות. . שאמרו שירה</b>: שמואל-א ו, יב. ראה גם מאמרי אדה\"א דברים ח\"ג ע' תתלד. וש\"נ."],["3276","107","<b>לא ירעו</b>: ישעי' יא, ט. סה, כה."],["3277","108","<b>וגר זאב עם כבש</b>: ישעי' יא, ו."],["3278","109","<b>בגרמי'</b>: ב: בכריע'. גדט: בגרמא — ראה מאמרי אדה\"א הנחות תקע\"ז ע' ריח. וש\"נ."],["3279","110","<b>כמתים שהחי' יחזקאל</b>: יחזקאל פל\"ז."],["3280","111","<b>ואתה אלקינו</b>: דהי\"א כט, יג."],["3281","112","<b>דבינה עד הוד אתפשטת</b>: נסמן לעיל טו, ג."],["3282","113","<b>מזמור לתודה</b>: תהלים ק, א."],["3283","114","<b>דעו. . והוא </b>[בד: הוא]: תהלים שם, ג."],["3284","115","<b>בואו שעריו בתודה</b>: שם ק, ד."],["3285","116","<b>הקדימו אנכה\"ג. . ברכ[ו]ת השחר</b>: ראה גם מאמרי אדה\"ז תקס\"ג כאן (ע' קכד). שו\"ע אדה\"ז הל' ברכות השחר רסמ\"ו."],["3286","117","<b>מיד שיקום האדם</b>: ראה גם מאמרי אדה\"ז תקס\"ג כאן. סידור אדה\"ז [לפני ברכת הנותן לשכוי בינה]. שו\"ע אדה\"ז שם ס\"ב ואילך. שער הכולל פ\"א, ס\"ו ואילך."],["3287","118","<b>רבה אמונתך לבקרים</b>: בגד: ליתא."],["3288","119","<b>שירה של המלאכים הוא בבוקר</b>: ראה זהר בראשית מ, ב. וישב קפט, רע\"א. וארא ל, א. מצורע נב, ב. לעיל סא, א. וש\"נ. לקמן פ' תצוה שכ, ד. אמרי בינה פתח השער ד, ד. ה, א."]]],[2300540301,"<b>וביאור</b> הענין הנה ידוע שבשעת השינה בלילה אילנא דמותא שלטא<sup data-n=\"3289\">120</sup> בגוף שנשאר בלא נשמה האלקית כי לא נשאר רק רושם אור בעלמא באפיו ו[ב]קיסטא דחיותא<sup data-n=\"3290\">121</sup> בליבא וכמ\"ש חדלו כו' אשר נשמה באפו<sup data-n=\"3291\">122</sup> כו', לפי שבחי' רע דק\"נ שנק' אילנא דמותא שלטא ומחשיך על הגוף מבחי' משכא דחויא<sup data-n=\"3292\">123</sup> ממש. וזש\"א שבשינה טועם האדם א' מס' במיתה<sup data-n=\"3293\">124</sup> והוא מות ברוחני' שהוא הסט\"א שנק' מות כמ\"ש בזהר<sup data-n=\"3294\">125</sup> ע\"פ יומת המת מעיקרו<sup data-n=\"3295\">126</sup> כו'. וזהו שאדם רואה [א\"ע מיד] בקומו משינתו התגשמיות החומריות בגופו ביותר מכפי מדתו בכל עניניו כו', ובפרט בהרהורים רעים וחטאים שאין רצונו וחפצו בהם כלל מעולם, וע\"כ העיקר הוא שיתן האדם אל לבו מיד בקומו ממטתו להסיר מיד ברגע הראשונה דעתו ולבו מכל רע וטומאה שנדבק בגופו בעת השינה מאילנא דמותא ס\"ם<sup data-n=\"3296\">127</sup> כו' (שלזה או' בק\"ש שעהמ\"ט ואל יבהלוני חלומות<sup data-n=\"3297\">128</sup> רעים והרהורים רעים כו' שהן באין בלילה מסט' דלילית ונעמה כו' כידוע עד והאר עיני פן אישן המות ממש כו'). וזהו ענין כל עיקר<sup data-n=\"3298\">129</sup> נט\"י בשחרית מיד בקומו ממטתו כדי להסיר הרוח רעה וכל טומאה שנדבק בחומריות גופו שקיבלה גם הנשמה בשינה במעט רושם הנשאר ממנה, והברכה על נטילה כו'<sup data-n=\"3299\">130</sup> בשחרית באמרו בא\"י כו' היא [ה]התחלה ליציאת הנשמה ממחשך הגס דקליפה ששורה על הגוף והוא ראשית ההתחלה והכנה לבא לבחי' ההודאה שבדעת והכרה בהודו לה', והוא בלתי אפשר אם לא שישליך מעליו טומא' הקליפה הגסה ביותר, וכידוע שמברכת השחר עד ב\"ש<sup data-n=\"3300\">131</sup> ופסוד\"ז הוא רק ענין היציאה מהחשך הגס דק\"נ. וז\"ש מי זאת עולה מן המדבר<sup data-n=\"3301\">132</sup> שהוא בחי' מדבר [ה]עמים<sup data-n=\"3302\">133</sup> דק\"נ כו', ואח\"כ יפה כלבנה בפסוד\"ז שע\"ז אמר בהלו נרו על[י] ראשו<sup data-n=\"3303\">135</sup> כו', ברה כחמה<sup data-n=\"3304\">134</sup> בק\"ש וש\"ע כו', והן ד' מדרגות מטה ושולחן כסא ומנורה שנק' ד' תיקוני שכינתא<sup data-n=\"3305\">136</sup> כמ\"ש במ\"א באורך. <span data-k=\"pg\">218</span> ּ ואחר ברכת נט\"י שהוא הראשית והכלל מפרטי פרטיות כמו בברכת שלא עשני גוי<sup data-n=\"3306\">137</sup> ושלא עשני עבד<sup data-n=\"3307\">138</sup>",[["3289","120","<b>אילנא דמותא שלטא</b>: ראה זהר במדבר קיט, א."],["3290","121","<b>ו[ב]קיסטא דחיותא</b>: נסמן לעיל פ' שמות לח, ג."],["3291","122","<b>חדלו. . באפו</b>: ישעי' ב, כב."],["3292","123","<b>משכא דחויא</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310036\" data-slug=\"tanya\" data-id=\"3401310036\">תניא פל\"א</a>. הנסמן במאמרי אדה\"א נ\"ך ע' תלד."],["3293","124","<b>שבשינה. . א' מס' במיתה</b>: ברכות נז, ב."],["3294","125","<b>בזהר</b>: בד: ליתא. גט: כבפנים."],["3295","126","<b>יומת המת מעיקרו</b>: פ' שופטים יז, ו. ראה זהר (רע\"מ) שופטים ערה, א. וראה גם הנסמן במאמרי אדה\"א דברים ח\"ב ע' תרכו. ח\"ג ע' א'קלה."],["3296","127","<b>ס\"ם</b>: בד: ליתא."],["3297","128","<b>ואל יבהלוני חלומות</b>: ברכת המפיל בסידור הרמ\"ק. ט: ואל יבהלוני רעיוני וחלומות."],["3298","129","<b>ענין כל עיקר</b>: בד: כל ענין. גט: כל עיקר ענין."],["3299","130","<b>כו'</b>: בד: זו."],["3300","131","<b>שמברכת השחר עד ב\"ש</b>: ראה מאמרי אדה\"א דברים ח\"ב ע' תו. וש\"נ. שמות ח\"ב ע' תרא."],["3301","132","<b>מי זאת עולה מן המדבר</b>: שה\"ש ג, ו. ח, ה. ראה גם לקמן פ' בא קכב, ד. וש\"נ."],["3302","133","<b>מדבר [ה]עמים</b>: יחזקאל כ, לה. ראה מאמרי אדה\"א נ\"ך ע' שפד. הנסמן במ\"מ לשע\"ת ד, ב."],["3303","135","<b>בהלו נרו על[י] ראשו</b>: איוב כט, ג."],["3304","134","<b>יפה כלבנה. . ברה כחמה</b>: שה\"ש ו, י. ראה גם לקמן פ' בא קכב, ד. וש\"נ."],["3305","136","<b>מטה. . ד' תיקוני שכינתא</b>: ראה זהר תרומה קלג, א. הנסמן במאמרי אדה\"א דברים שם. נ\"ך ע' טז. לקמן פ' משפטים רצד, ד. תצוה שמט, א. ויקהל תכז, א ואילך."],["3306","137","<b>שלא עשני גוי</b>: ראה גם מאמרי אדה\"א ויקרא ח\"ב ע' תשג. וש\"נ. מאמרי אדה\"ז כתובים ח\"ב ע' צח. לקמן פ' בשלח קלז, סע\"ג ואילך."],["3307","138","<b>ושלא עשני עבד</b>: ראה גם מאמרי אדה\"א נ\"ך ע' שיט. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680142\" data-slug=\"torat-chaim\" data-id=\"2300680142\">תו\"ח וישלח קפב, ב</a>. לקמן פ' בשלח שם."]]],[2300540326,"ושלא עשני אשה שהן ג' מיני קליפות דנוגה דבי\"ע כידוע. ולכאורה אין מהצורך לברכה זו שלא עשני גוי דהאיך יוכל להיות ישראל גוי כו' אלא כמ\"ש בס' הקבלה שלא נדבק בו נשמת גוי ועבד כו', והוא שלא נדבק בנשמתו בשינה (בהילוכה לג\"ע דרך אויר היכלות הקליפות שנאחזים בה מצד התמשכות הגוף כל היום אחר תאוות<sup data-n=\"3308\">139</sup> ומ\"ז שנק' לבושי' צואים של הנשמה כו' ורוח אייתי רוח<sup data-n=\"3309\">140</sup> כו', ע\"כ יוכל לידבק בה נשמת גוי ועבד כו' מסט\"א המחשיך מאד אור הנשמה והן רבוי המ\"ז שמבלבלין מאד). והנה ג' ברכות אלה הן כללות ענין היציאה מק\"נ (וע\"כ אומ[רם] באחרונה). ואמנם פרטיות המדרגות לפי ציור קומת האדם בגופו כסדר תחלה פוקח עורים<sup data-n=\"3310\">141</sup> שהוא שיסיר העו[ר]ון החומרי ויראה בראיית עיני השכל באלקים [חיים] כמו ראו מי ברא אלה<sup data-n=\"3311\">142</sup> [(ובאומה\"ע נאמ'] עינים להם ולא יראו<sup data-n=\"3312\">143</sup> כו'), וזהו פוקח עורים עינים לראות<sup data-n=\"3313\">144</sup> תומ\"י בהקיצו<sup data-n=\"3314\">145</sup> מן השינה, ואח\"כ מתיר אסורים<sup data-n=\"3315\">146</sup> בידים ורגלים שהוא מאסר חומר הגוף שיושב וקשור בחושך כו', וזוקף כפופים<sup data-n=\"3316\">147</sup> להיות בחי' אדם בקומה זקופה להכיר בוראו ולא כרוח הבהמה שיורד למטה כו', וכן סומך נופלים<sup data-n=\"3317\">148</sup> להקים הנופל בפח יקוש דק\"נ כו', עד המכין מצעדי גבר<sup data-n=\"3318\">149</sup> לילך בדרכי ה' לאור<sup data-n=\"3319\">150</sup> באור החיים כי בדרך שאדם רוצה<sup data-n=\"3320\">151</sup> כו', ונותן ליעף כח<sup data-n=\"3321\">152</sup> שהוא כח קדישא<sup data-n=\"3322\">153</sup> דנש\"י כמו ענין העונה איש\"ר בכל כחו<sup data-n=\"3323\">154</sup> כו'. ואח\"כ מסדר בבחי' מקיף בלבושים מרגל במנעלים שז\"ש שעשה לי כל צרכי<sup data-n=\"3324\">155</sup>, ואח\"כ אוזר ישראל בגבורה<sup data-n=\"3325\">156</sup> כו' במתניים שהן קיום המדות שבלב שנק' גופא, ואח\"כ עוטר ישראל בתפארה כו' במקיף דתפילין<sup data-n=\"3326\">157</sup> שהם ג' מדריגות המקיפים דחב\"ד חג\"ת נה\"י, וכך הוא בבחי' אור פנימי בגוף באו\"כ פוקח עורים בבחי' חב\"ד ומתיר אסורים בידים שהוא במדות וכפופים ונופלים<sup data-n=\"3327\">158</sup> בנה\"י כו'. ואחר כל אלה הפרטים או' המעביר שינה מעיני כו' שיוצא מן המות [ד]שינה הנ\"ל וע\"כ<sup data-n=\"3328\">159</sup> ממילא תרגילנו במצותיך<sup data-n=\"3329\">160</sup> ואל תביאנו לא<sup data-n=\"3330\">161</sup> לידי חטא כו' ואל ישלוט בנו יצה\"ר כו' ויסיר כל קטרוג שנק' דבר רע כו' (וקודם הברכות הללו או' הנותן לשכוי בינה<sup data-n=\"3331\">162</sup> להבחין בין יום כו', לפי שעיקר הסיבה ליציאה מן החושך דמות דק\"נ להאיר אור<sup data-n=\"3332\">163</sup> האלקי הוא בבוקר אור דוקא שאז נפסק שליטת אילנא דמותא כו', וכידוע דמחצות לילה",[["3308","139","<b>תאוות</b>: בג: ניתוסף: עוה\"ז. גט: כבפנים."],["3309","140","<b>ורוח אייתי רוח</b>: נסמן לעיל סג, ג."],["3310","141","<b>פוקח עורים</b>: ראה גם לעיל נ, א. וש\"נ."],["3311","142","<b>ראו מי ברא אלה</b>: ישעי' מ, כו [ושם: וראו]."],["3312","143","<b>עינים להם ולא יראו</b>: תהלים קטו, ה. קלה, טז."],["3313","144","<b>עורים עינים לראות</b>: בד: עינים. גט: העינים."],["3314","145","<b>בהקיצו</b>: בגד: ליתא. ט: בקומו."],["3315","146","<b>מתיר אסורים</b>: ראה גם אוה\"ת ענינים ע' שו."],["3316","147","<b>וזוקף כפופים</b>: ראה גם מאמרי אדה\"ז תקס\"ז ע' שעה. ענינים ע' רמט. שע\"ת ז, ג ובהערה 37. אוה\"ת שם."],["3317","148","<b>סומך נופלים</b>: כ\"ה גם בהכת\"י. וראה גם מאמרי אדה\"א שמות ח\"ב ע' תקפח. לקמן הערה 158."],["3318","149","<b>המכין מצעדי גבר</b>: ראה גם אוה\"ת שם."],["3319","150","<b>לאור</b>: בגד: ליתא."],["3320","151","<b>בדרך שאדם רוצה</b>: מכות י, ב."],["3321","152","<b>ונותן ליעף כח</b>: ראה גם אוה\"ת שם."],["3322","153","<b>כח קדישא</b>: ראה גם שע\"ת פא, א ובהערה 18. לקמן פ' ויקהל תלו, ג."],["3323","154","<b>העונה איש\"ר בכל כחו</b>: ראה שבת קיט, ב. הנסמן במאמרי אדה\"א בראשית ע' שסד."],["3324","155","<b>במנעלים. . שעשה לי כל צרכי</b>: ברכות ס, ב. ראה גם אוה\"ת שם ע' שז."],["3325","156","<b>אוזר ישראל בגבורה</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316520245\" data-slug=\"or-hatorah-hb\" data-id=\"8316520245\">אוה\"ת שם</a>. וראה גם מאמרי אדה\"א שמות ח\"ב ע' תקפט. המשך וככה תרל\"ז פס\"ב."],["3326","157","<b>עוטר ישראל. . דתפילין</b>: ראה שו\"ע אדה\"ז הל' תפילין סכ\"ה, ס\"ט. ראה גם מאמרי אדה\"א ואוה\"ת שם."],["3327","158","<b>ונופלים</b>: ראה הערה 148."],["3328","159","<b>וע\"כ</b>: בד: ועי\"ז."],["3329","160","<b>במצותיך</b>: בגד: בתורתך."],["3330","161","<b>לא</b>: בגד: ליתא."],["3331","162","<b>הנותן לשכוי בינה</b>: ראה גם תו\"א תשא פו, ריש ע\"ב. מאמרי אדה\"א שמות ח\"ב ע' תרה ואילך. המשך תער\"ב ח\"ב ע' תשלט."],["3332","163","<b>להאיר אור</b>: גט: לאור."]]],[2300540349,"ואילך מתחיל הארת אור החסד<sup data-n=\"3333\">164</sup>. אך העיקר הוא בבוקר אור שאז הוא גילוי אור החסד<sup data-n=\"3334\">165</sup> והוא הבחנת התרנגול ביום כו' והוא מ\"ש בזהר דרוח חסד האלקי בטש בגדפוהי דתרנגולא<sup data-n=\"3335\">166</sup> ובזה נמשך התעוררות התשובה בבנ\"א כו', והיינו להבחין יתרון האור מן החשך דקליפה שהוא ראשית [ה]הכנה להודא[ת] [ה]אמת שע\"י הדעת והכרה וזהו הנותן לשכוי בינה כו'. וכמ\"כ במלאכים עליונים הוא הטעם שבאור הבקר דוקא או' שירה כנ\"ל כמ\"ש ברן יחד כו' כמ\"ש בזהר, כמו שישמח אדם באור הבוקר במה שיצא מן החשך שקדם לו שנק' קדרותא דצפרא<sup data-n=\"3336\">167</sup>, ע\"כ אמר שמחה בצפרא כו'<sup data-n=\"3337\">168</sup> ורננה ברמשא כו' כי חסד אל כל היום<sup data-n=\"3338\">169</sup> וכו') (ובכ\"ז יובן מ\"ש אלקי נשמה כו' קודם בה\"ש<sup data-n=\"3339\">170</sup> אחר ברכת נט\"י דוקא לפי שזה כמו ענין תחה\"מ לע\"ל כמ\"ש ואתה משמרה בקרבי [ואתה עתיד לטלה ממני ולהחזירה בי לעתיד לבא וכל זמן שהנשמה בקרבי] מודה אני לפניך כו' <span data-k=\"pg\">קט</span> ּ והוא ע\"י נט\"י מטעם הנ\"ל וד\"ל<sup data-n=\"3340\">171</sup>, ולא קודם נט\"י שא\"א לו לומר נשמה שנתת בי טהורה [היא] מצד אחיזת רוח הטומאה בגופו בשינה כו' ולכך מסיים המחזיר כנ\"ל<sup data-n=\"3341\">172</sup> וד\"ל).\n<b>והנה</b> אחר בהש\"ח שהיא הכנה הנאמנה<sup data-n=\"3342\">173</sup> לצאת מחושך גמור לאור יכול לבוא לבחי' הכרה והודאה בדעת גמור בהודו לה' כו' כאדם שיצא לאור גדול שנפתחו עיניו לראות [ו]להכיר את האמת ע\"פ ראית השכל היפוך [ממש] מכמו שהי' בדמיונות כוזבות בתחלה כו', וזהו הטעם שתקנו הודו לה' שהוא הודאה כללית לשם הוי' אחר היציאה מהחושך דוקא כנ\"ל. אך לא כל האדם יכול לבא בנפשו לבחי' הודאה אמיתי' זאת הגם שבירך ברכת השחר כנ\"ל מצד ריבוי עוונות וח\"נ ורוב המשכת תאוות חומריות ביותר, וגם מתאוות היתר נעשה שמטמטם ללב ביותר ואפי' בעוונות שאדם דש בעקביו<sup data-n=\"3343\">174</sup> ואינו מחשיב לחטא ועון כלל הרי נעשה מזה מחיצה ש\"ב<sup data-n=\"3344\">175</sup> להפסיק בינו לאביו שבשמים, ומחיצה של ברזל זו ודאי מפסקת לגמרי לבלתי יוכל האדם להעביר מאתו הרוח הגסות דק\"נ בכל אשר הלך שובב בדרך לבו דרוח אייתי רוח וכו' ולא יצא מן החשך לאור [ל]עולם ואיך יאמר הודו לה' בהודאה שיצא מצד הכרה והדעת. הנה לזאת תקנו אכה\"ג לומר בהודו פסוק והוא רחום יכפר עון",[["3333","164","<b>דמחצות. . אור החסד</b>: ראה זהר לך צב, סע\"ב."],["3334","165","<b>בבוקר. . אור החסד</b>: ראה זהר שמות כא, ב. בשלח סג, א. יתרו פא, א."],["3335","166","<b>בטש בגדפוהי דתרנגולא</b>: ראה זהר בהר קז, סע\"ב ואילך. שלח קעא, ב. מאמרי אדה\"ז תקס\"ב ח\"ב ע' שצז. שע\"ת קלה, א הערה 8. לקמן פ' יתרו רעג, א."],["3336","167","<b>קדרותא דצפרא</b>: נסמן לעיל סז, ד."],["3337","168","<b>שמחה בצפרא כו' </b>[בד: ליתא]: זהר ויחי רכט, ב."],["3338","169","<b>חסד אל כל היום</b>: תהלים נב, ג."],["3339","170","<b>בה\"ש</b>: בד: ברכות השחר."],["3340","171","<b>וד\"ל</b>: בד: ליתא."],["3341","172","<b>כנ\"ל</b>: בד: כו'."],["3342","173","<b>הנאמנה</b>: בד: הראשונה."],["3343","174","<b>בעוונות שאדם דש בעקביו</b>: ע\"ז יח, א. הנסמן במ\"מ למאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תתצג."],["3344","175","<b>מחיצה ש\"ב </b>[בד: של ברזל]: ע\"פ פסחים פה, ב. ראה גם ברכות לב, ב וברש\"י שם. אוה\"ת תצוה ע' א'תרצא."]]],[2300540372,"כו' שיכפר על [ה]עון וחטא לבלתי יפסיק מחיצה של ברזל כו', והן<sup data-n=\"3345\">176</sup> פסוקים שאח\"ז שאומר אתה ה' [לא תכלה רחמיך] כו', [זכור רחמיך ה' כו', תנו עוז כו', לה' הישועה כו', ה' צבאות עמנו כו' עד הושיעה את עמך כו', שכ\"ז הוא לעורר ר\"ר<sup data-n=\"3346\">177</sup> וחסדים העליוני' לעוזר ולהושיע לצאת מהיכלות הטומאה והסט\"א שיוכל לבא להודו לה' ברינה וזמרה בפסוד\"ז מב\"ש עד יוצר אור כו'. וע\"כ תקנו הודו קודם ב\"ש לפי נוסח האריז\"ל<sup data-n=\"3347\">178</sup> וד\"ל]. והנה כ\"ז הוא רק הכנה בלבד לפסוד\"ז כנ\"ל שעיקר פסוד\"ז הוא ההלל וכן הללויה<sup data-n=\"3348\">179</sup> בהילו נרו כו' יהי אור<sup data-n=\"3349\">180</sup> כו' שזהו ענין הבהקת אור דשם הוי' בנפש האדם שנק' י\"ה<sup data-n=\"3350\">181</sup> שהוא למעלה מבחי' הודאה, ועיקר תחילת פסוד\"ז הוא בתהלה לדוד<sup data-n=\"3351\">182</sup> שצ\"ל ג' פעמים בכ\"י<sup data-n=\"3352\">183</sup> כו' להיותה כללות ענין פסוד\"ז הללוי'<sup data-n=\"3353\">184</sup> כו', כי הנה פי' ת\"ל ארוממך אלקי המלך כו' ידוע שדוד הי' מרכבה לבחי' מל'<sup data-n=\"3354\">185</sup> דאצי' שהוא המלך סתם וא' ארוממך אלקי המלך, להיות מבואר למעלה בבחי' שם אלקים שהוא בחי' ממכ\"ע שאינו רק בחי' זיו ואור המאיר ומתפשט בעולמות בבחי' הארה דהארה לבד כמו הודו על או\"ש<sup data-n=\"3355\">186</sup> כו' הוד שמו שאינו מהות ועצמו' אלקו' וכמ\"ש כי עמך מקו\"ח כו'. וז\"ש ארוממך אלקי המלך בחי' אלקי' ממש שהוא בחי' ממכ\"ע שנק' כח הפועל בנפעל<sup data-n=\"3356\">187</sup> כו' ארוממך לבחי' מהו\"ע אלקי'<sup data-n=\"3357\">188</sup> דבחי' סוכ\"ע שהוא ש' הוי' דאצי' שנק' קדוש ומובדל כנ\"ל והוא יחוד שם אד' בהוי' כו', וכמ\"ש כי עמך מקו\"ח כו' שנכלל ובטל ומתייחד בעצמות אלקות כמ\"ש כי ה' הוא האלקי' כולא חד ממש כו' וד\"ל.\n<b>וביאור</b> הענין ידוע בפי' ה' מלך גיאות לבש<sup data-n=\"3358\">189</sup> שזה שמחי' ומהוה את הכל בבחי' מל' ית' כמ\"ש מלכותך מכ\"ע ומלכותו בכל משלה וכמ\"ש אלקים חיים ומלך עולם<sup data-n=\"3359\">190</sup>, היינו רק בחי' לבוש שמתלבש ומתצמצם להיות בחי' מקור חיי",[["3345","176","<b>והן</b>: בד: וכן."],["3346","177","<b>ר\"ר</b>: ג: לבחי' ר\"ר."],["3347","178","<b>האריז\"ל</b>: גט: סידור האריז\"ל כידוע."],["3348","179","<b>וכן הללויה</b>: בד: והן הללו י\"ה."],["3349","180","<b>יהי אור</b>: לשון הפסוק בראשית א, ג. גט: [ג: ול'] יהל אור — ראה לקמן פ' בא קח, ג. מאמרי אדה\"א דברים ח\"ג ע' א'נח. וש\"נ. בראשית ע' שעב. וש\"נ. הנחות תקע\"ז ע' שדמ. ש\"א מה, ב."],["3350","181","<b>י\"ה</b>: בד: נר ה' — ראה לעיל עב, ד."],["3351","182","<b>עיקר. . בתהלה לדוד</b>: ראה שו\"ע אדה\"ז הל' ברה\"ש רסנ\"א. רסנ\"ב."],["3352","183","<b>בתהלה לדוד. . בכ\"י</b>: ברכות ד, ב. מאמרי אדה\"ז תקס\"ג ח\"ב ס\"ע תק ואילך. שו\"ע אדה\"ז הלכות ברכות השחר רסנ\"א. לקמן פ' ויקהל תלג, א. אוה\"ת (יהל אור) תהלים ע' תרעב ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181360\" data-slug=\"likkutei-sichot\" data-id=\"1300181360\">לקו\"ש</a> פינחס (כרך יח) ע' 351 ואילך."],["3353","184","<b>הללוי'</b>: בד: בהללו י\"ה."],["3354","185","<b>שדוד. . מל'</b>: ראה פרדס (שעה\"כ) שכ\"ג, מערכת דוד. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתקט."],["3355","186","<b>הודו על או\"ש</b>: תהלים קמח, יג. ראה גם מאמרי אדה\"א שמות ח\"א ע' מח. וש\"נ. קונטרסים ע' תכד."],["3356","187","<b>כח הפועל בנפעל</b>: ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380500\" data-slug=\"likkutei-torah\" data-id=\"4001380500\">לקו\"ת שלח מז, א</a>: בספרים. וראה הנסמן במ\"מ לשם. ספר הישר (לר\"ת ) סוף ש\"ג."],["3357","188","<b>אלקי'</b>: ג: שם אלקי'. ט: אלקו'."],["3358","189","<b>ה' מלך גיאות לבש</b>: תהלים צג, א. ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370408\" data-slug=\"torah-or\" data-id=\"3901370408\">תו\"א מג\"א צ, ג</a>. מאמרי אדה\"ז תקס\"ו ע' שלז וע' שמ. תקס\"ח ח\"א ע' תטז. ח\"ב ע' תרמד. שה\"א עד, ב. עו, ב. ש\"א לו, א. עג, סע\"ב ואילך. לקמן פ' בא צז, א. בשלח קסח, ד. יתרו רנו, ד. תצוה שכח, ב. ויקהל שצג, ד. תג, ג. תלא, ד."],["3359","190","<b>אלקים חיים ומלך עולם</b>: ברכת יוצר."]]],[2300540393,"העולמים במדה זו דמל' [כי אין מלך בלא עם<sup data-n=\"3360\">191</sup> כו' כמ\"ש וישב ה' מלך לעולם<sup data-n=\"3361\">192</sup> (והוא ענין בשכמל\"ו שזהו שא' כאן ואברכה שמך לעולם כו' כמשי\"ת), אבל בעצם מדת זאת דמל'] הרי הוא למעלה מעלה מהיות בחי' מלך על עם כו' (שאין ערוך כלל להתפשטות והתנשאו' <span data-k=\"pg\">220</span> ּ דמלוכה זו לגבי בחי' התנשאות וגיאות דמצד עצמות הרוממות שלגדולתו אין חקר כלל שנק' מלך מרומם לבדו מתנשא מימ\"ע כו' וכמ\"ש לך ה' הגדולה והגבורה<sup data-n=\"3362\">193</sup> כו' וכמ\"ש כי עמך מקור חיים כו') וזהו ארוממך אלקי ארומם לבחי' אלקים שהוא הארה וזיו דהתפשטות המל' בעולמות לגבי עצם רוממות המלך כמו שהוא מלך יחיד ומרומם לבדו כו' (דלי\"ת רבתי<sup data-n=\"3363\">194</sup> ז\"א<sup data-n=\"3364\">195</sup> כידוע שנק' כמ\"ל<sup data-n=\"3365\">196</sup> בכלל), והיינו לפי שהי' דוד בחי' מרכבה לבחי' מל' [דאצי'] עצמו וע\"י שירות ותשבחות שלו הי' מעלה ומרומם לבחי' כח וחיות אלקי המתפשט בעולמות לעצם הרוממות דמדת מל' דאצי' שנק' המלך סתם (שנק' מלך רב כד מלכא יתיב בהיכלו כו' והוא הנק' המלך הקדוש, משא\"כ כד מלכא יתיב בין עבדוהי מלך זוטא<sup data-n=\"3366\">197</sup> מקרי כמ\"ש בזהר שנק' המלך המשפט<sup data-n=\"3367\">198</sup> כמו וישב ה' מלך לעולם כו'), והוא יחוד שם אד' בהוי' כי מדה זו דמל' המלובש בעולמות נק' בשם אדני<sup data-n=\"3368\">199</sup> [לשון] אדנות ושררה כמו אדון כל הארץ<sup data-n=\"3369\">200</sup> כמ\"ש אד' בם<sup data-n=\"3370\">201</sup> כו', ונק' בשם אלקי'<sup data-n=\"3371\">202</sup> לשון כח<sup data-n=\"3372\">203</sup> וחיות כמו הודו לאלקי האלקי'<sup data-n=\"3373\">204</sup> שהוא מקור וכח לכל הכחות אלקיים פרטים המסתעפים בהשתל' העולמות כמו גדול אדונינו ורב כח<sup data-n=\"3374\">205</sup> כו'. וגם שם אלקים הוא אדנות ושררה<sup data-n=\"3375\">206</sup> כמו עד האלקי' יבא<sup data-n=\"3376\">207</sup> כו', והכל אחד משום שבחי' כח וחיות האלקי המהווה את הכל מאין ליש היינו ע\"י בחי' מל' שהוא בחי' אדנות ושררה כמ\"ש מלכותך מכ\"ע וממשלתך כו' וכן ומלכותו בכל משלה (רק שבחי' המל' ושררה שורה עליהם<sup data-n=\"3377\">208</sup> [עכשיו] בבחי' מקיף בהעלם כמו ואימתך עליהם<sup data-n=\"3378\">209</sup> וכמו שאו' וכולם מקבלים<sup data-n=\"3379\">210</sup> עליהם עומ\"ש, וגם על ע\"ס<sup data-n=\"3380\">211</sup> דנוגה אמר תפול עליהם<sup data-n=\"3381\">212</sup>",[["3360","191","<b>אין מלך בלא עם</b>: בחיי וישב לח, ל. ראה הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"ב לע' תרלא."],["3361","192","<b>וישב ה' מלך לעולם</b>: תהלים כט, י."],["3362","193","<b>לך ה' הגדולה והגבורה</b>: דהי\"א כט, יא."],["3363","194","<b>דלי\"ת רבתי</b>: ראה ד\"ה זה במאמרי אדה\"א דברים ח\"א ע' רפג."],["3364","195","<b>ז\"א</b>: בד: דאחד."],["3365","196","<b>כמ\"ל</b>: ב: מל'. גט: כתר מל'."],["3366","197","<b>מלך רב. . מלך זוטא</b>: ראה זהר ויחי רלט, א. זח\"ג (תוספת) ש, א. ראה גם סידור שער הר\"ח ריא, ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381115\" data-slug=\"likkutei-torah\" data-id=\"4001381115\">לקו\"ת ברכה צז, א</a>. מאמרי אדה\"ז נביאים ע' קצז. תקס\"ח ח\"ב ע' תרעג. שה\"א עו, א. מאמרי אדה\"א נ\"ך ס\"ע תיח. הנחות תקע\"ז ע' ז. לקמן פ' בא קכב, א. ויקהל תו, ג."],["3367","198","<b>המלך הקדוש. . המלך המשפט</b>: ברכות יב, ב. ראה עט\"ר ע' ו ואילך. מאמרי אדה\"א דברים ח\"ג ס\"ע א'יט ואילך."],["3368","199","<b>דמל'. . אדני</b>: ראה זהר ויקרא יא, א. מאמרי אדה\"א בראשית ע' קצז. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670094\" data-slug=\"torat-chaim\" data-id=\"2300670094\">תו\"ח נח סד, ג</a> הערה 44."],["3369","200","<b>אדני. . אדון כל הארץ</b>: נסמן לקמן פ' בא פח, ג."],["3370","201","<b>אד' בם</b>: תהלים סח, יח."],["3371","202","<b>דמל'. . אלקי'</b>: ראה זהר בראשית כב, א. אחרי סה, א. כסא מלך להקדמת ת\"ז יא, ב אות ג. מאמרי אדה\"א ויקרא ח\"א ע' רכט. וש\"נ. בראשית ע' קצז. וש\"נ. שמות ח\"ב ע' תרכב. נ\"ך ע' כ וע' שכט. ש\"א לו, א. וש\"נ."],["3372","203","<b>אלקי' לשון כח</b>: ראה שו\"ע אדה\"ז דין כוונת הברכות ס\"ה, ס\"ג. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560355\" data-slug=\"or-hatorah-hb\" data-id=\"8316560355\">אוה\"ת יתרו ע' תשנא</a>. מאמרי אדה\"ז תקס\"ח ח\"ב ע' תרמד. מאמרי אדה\"א בראשית ע' נט. ויקרא ח\"ב ע' תקמא. שעה\"י קיא, א. ש\"א לו, א. לקמן פ' בא קיב, ד. תרומה שה, א. תצוה שכז, ד."],["3373","204","<b>הודו לאלקי האלקי'</b>: תהלים קלו, ב."],["3374","205","<b>גדול אדונינו ורב כח</b>: תהלים קמז, ה."],["3375","206","<b>אלקים הוא אדנות ושררה</b>: נסמן לעיל ס, א."],["3376","207","<b>עד האלקי' יבא</b>: משפטים כב, ח."],["3377","208","<b>עליהם</b>: תוקן ע\"פ בד. בתו\"ח כאן: עליכם."],["3378","209","<b>ואימתך עליהם</b>: כ\"מ בכ\"מ — ראה מאמרי אדה\"א שמות ח\"א ע' קסא. וש\"נ. ש\"א כה, א. תו\"ח ח\"ש קל, ב הערה 25. לקמן פ' בשלח רכז, ב. משפטים רפב, ד. תרומה שו, ד."],["3379","210","<b>וכולם מקבלים</b>: ברכת יוצר."],["3380","211","<b>ע\"ס</b>: ב: ע\"ש. ראה לעיל הערה 92."],["3381","212","<b>תפול עליהם</b>: בשלח טו, טז."]]],[2300540413,"אימתה ופחד כו' ונק' מלך הגוים<sup data-n=\"3382\">213</sup> כו' [וכתי'] מלך אלקים על גוים<sup data-n=\"3383\">214</sup> כו', ולע\"ל יבא זה בבחי' גילוי גמור ונק' פחד אלקים<sup data-n=\"3384\">215</sup> כמו גלה כבוד מלכותך עלינו<sup data-n=\"3385\">216</sup> [כו' ואו'] ו[ב]כן תן פחדך<sup data-n=\"3386\">217</sup> כו' וייראוך כל המעשים כו', ועכשיו הוא בא רק ע\"י הצמצום דקו המדה, וראי' ממ\"ש הושיט אצבעו<sup data-n=\"3387\">218</sup> קטנה ביניהם<sup data-n=\"3388\">219</sup> [ביתר מכפי המדה] ושרפם שנתבטלו ממציאותן, ועוד ראי' ממה שהשמיע ה' את הוד קולו במחנה סנחריב<sup data-n=\"3389\">220</sup> ששמע[ו] שירת המלאכים ונפלו כולם, וכך הי' בי' מכות באלקי מצרים שנגלה עליהם אור המל' ביתר מכפי הצמצום כו').\n<b>והנה</b> אחר ההעלאה זו שא' ארוממך אלקי כו' לגבי עצם הרוממות דבחי' כ' מל' דאצי' כנ\"ל הרי ודאי זה גורם בחי' המשכה וירידה ממקום שעלה שם דייקא וז\"ש ואברכה שמך כו', אברכה הוא בחי' המשכה וגילוי אור הבא בתוס' מרובה על העיקר והוא שמברך לשמך שיבא בגילוי אור למטה כמו שהוא למעלה ממש, והיינו שיתגלה בחי' מדת מל' דאצי' כמו שהיא בעצמותו ית' שהוא בבחי' א\"ס שאין לו שיעור למעלה כו' מפני שהוא בחי' התנשאות שמצד עצם הרוממות כנ\"ל. וזהו שמך העצמי כי מה שנק' בשם מלך על עולם אינו שם העצם רק שם הפעולה דהיינו מה שמתפשט הארתו בעולמות והוא שם אלקים ושם אד' כנ\"ל וכמ\"ש לכו חזו מפעלות אלקים אשר שם שמות כו'<sup data-n=\"3390\">221</sup> א\"ת שמות אלא שמות<sup data-n=\"3391\">222</sup> ב' שמות דאלקי' ואד' כו', אבל שמך ממש הוא מל' דאצי' [עצמו] ששרשו במל' דא\"ס<sup data-n=\"3392\">223</sup> עצמו כמו אתה קדוש<sup data-n=\"3393\">224</sup> ושמך קדוש כו' וכמאמר <span data-k=\"pg\">קי</span> ּ קודם שנבה\"ע הי' הוא ושמו בלבד<sup data-n=\"3394\">225</sup> כו'. אך צריך שיבא מן בחי' ההעלם שבעצמות לידי גילוי למטה כמו גלה כבוד מל' עלינו כו' (כמו שיהי' לע\"ל [שהוי' ימלוך] שנא' ה' ימלוך לע\"ו<sup data-n=\"3395\">226</sup> ), וז\"ש ואברכה שמך והוא שם דהוי' שבמל' דאצי' שאמר המלך המרומם לבדו מאז כו' וכמ\"ש מי הוא זה מה\"כ<sup data-n=\"3396\">227</sup> להיותו בבחי' מקיף וסוכ\"ע וכמ\"ש המתנשא מימו\"ע ואומר ה' צבאות<sup data-n=\"3397\">228</sup> הוא מה\"כ [וזש\"א] ואברכה שמך לע\"ו כמו לע\"ל דכתיב [ה' ימלוך לע\"ו] דוקא שהוא מצד בחי' גילוי אלקות<sup data-n=\"3398\">229</sup> אור רוממות דמדת מל' בעצם",[["3382","213","<b>מלך הגוים</b>: ירמי' י, ז."],["3383","214","<b>מלך אלקים על גוים</b>: תהלים מז, ט."],["3384","215","<b>פחד אלקים</b>: תהלים לו, ב. דהי\"ב כ, כט."],["3385","216","<b>גלה כבוד מלכותך עלינו</b>: מוסף ליו\"ט."],["3386","217","<b>ו[ב]כן תן פחדך</b>: תפלת העמידה לימים נוראים."],["3387","218","<b>הושיט אצבעו</b>: נסמן לעיל ל, ב."],["3388","219","<b>ביניהם</b>: בדט: ליתא. ג: כבפנים."],["3389","220","<b>שהשמיע. . סנחריב</b>: נסמן לעיל ל, ג."],["3390","221","<b>כו'</b>: בד: בארץ."],["3391","222","<b>א\"ת שמות אלא שמות</b>: ברכות ז, ב. ראה גם לקמן פ' יתרו רנג, א. פקודי תמג, ב. תנג, ג."],["3392","223","<b>מל' דאצי'. . במל' דא\"ס</b>: ראה גם שע\"ת לא, סע\"ב. קמ, סע\"ד."],["3393","224","<b>אתה קדוש</b>: תפלת שמו\"ע."],["3394","225","<b>קודם. . ושמו בלבד</b>: נסמן לעיל נג, ב."],["3395","226","<b>ה' ימלוך לע\"ו</b>: בשלח טו, יח."],["3396","227","<b>מי הוא זה מה\"כ</b>: תהלים כד, י."],["3397","228","<b>ה' צבאות</b>: תהלים שם."],["3398","229","<b>אלקות</b>: בד: ליתא."]]],[2300540433,"כנ\"ל, ע\"כ בא האור בבחי' נצחית דא\"ס ממש וכמ\"ש וע\"י יתיב<sup data-n=\"3399\">230</sup> כו' [מלכותי' מלכות עלם<sup data-n=\"3400\">231</sup> ] מלכותך מכ\"ע<sup data-n=\"3401\">232</sup> (וכמ\"ש במ\"א בענין דוד מ\"י ח\"ו<sup data-n=\"3402\">233</sup> מפני שגם הזמן יהי' נצחי' מפני שיאיר בו מלמעלה מן הזמן וז\"ש עד דוד הגדיל<sup data-n=\"3403\">234</sup> כו' והוא מ\"ש ויעש דוד שם<sup data-n=\"3404\">235</sup> כו'), וזהו ג\"כ ענין בשכמל\"ו [שאחר בחינת העלאה והתכללות ביחוד עליון כשמאריך בד' רבתי דאח\"ד<sup data-n=\"3405\">236</sup> שא' תמליכהו בשמים ובארץ וד' רוחות<sup data-n=\"3406\">237</sup> כו'. רק שעכשיו אומרים בשכמל\"ו] בחשאי<sup data-n=\"3407\">238</sup> מפני שאינו בא בגילוי גמור רק לע\"ל דוקא כנ\"ל ו[ע]\"כ ביוה\"כ דוקא שהוא מעין העוה\"ב<sup data-n=\"3408\">239</sup> דלע\"ל<sup data-n=\"3409\">240</sup> או' בשכמל\"ו<sup data-n=\"3410\">*241</sup> בקול<sup data-n=\"3411\">241</sup> רם<sup data-n=\"3412\">242</sup> וכן היו או' בבהמ\"ק<sup data-n=\"3413\">243</sup> כידוע וד\"ל.\n<b>והנה</b> יתפרש עוד בענין ואברכה שמך לע\"ו בד\"כ יותר והוא בב' מדרגות דהעלם וגילוי שנק' סובב וממלא<sup data-n=\"3414\">244</sup> בכללות, ויובן זה ממה שמצינו ב' מדרגות הללו בבחי' ממכ\"ע שהוא התחלקות המדרגות שיש בעולמות הנמצאי' מאין ליש מבחי' מל' שנק'<sup data-n=\"3415\">245</sup> שם [שאינו רק] זיו ואור המתפשט כנ\"ל, שנק' ג\"כ בשם מעלה ומטה בדרך פרטיות בכל עולם, ובדרך כלל נחלק לב' מדרגות וה\"ע ב' מיני עולמות שנק' עלמין סתימין דלא אתגליין ועלמין דאתגליין<sup data-n=\"3416\">246</sup>, והוא מ\"ש ברוך ה' כו' מן העולם ועד העולם<sup data-n=\"3417\">247</sup> מעלמא דאתכסיא לעלמא דאתגליא. וביאור הענין ידוע עד\"מ באדם התחתון במחו\"ד שהמח' בהעלם והדבור בגילוי וכל מה שבא באותיות המח' יוצא לגילוי בדיבור לפי אופן [ה]צירופים שבמח' ממש, כך כתי' בי\"ה ה' צור עולמים<sup data-n=\"3418\">248</sup> ב' עולמים עלמא דאתכסיא הן עלמין סתימין שנבראו מבחי' אותיות מחשבתו ית' שנק' בשם עלמין ממש רק שהן בבחי' ההעלם [ממש], כמו ג\"ע העליון [עצמו] יש בו בחי' ההעלם והגילוי, והוא מה שנמשך מהעלם אור התענוג שבחכ' שבגעה\"ע<sup data-n=\"3419\">249</sup> לגילוי אור התענוג והשגה<sup data-n=\"3420\">250</sup> נשמות שבג\"ע להיות נהנין מזיו השכינה ממש<sup data-n=\"3421\">251</sup>, ובכל חודש ושבת עולים הנשמות<sup data-n=\"3422\">252</sup> לקבל מעונג<sup data-n=\"3423\">253</sup> העליון [הנעלם] כמו שהוא עדיין בבחי' ההסתר וההעלם [ה]עצמות כו' וז\"ש להשתחוות לפני ה'<sup data-n=\"3424\">254</sup> כו', ואח\"כ נמשך להם האור בגילוי עונג המורגש בהשגה ממש שהוא בבחי'",[["3399","230","<b>וע\"י יתיב</b>: דניאל ז, ט."],["3400","231","<b>מלכותי' מלכות עלם</b>: דניאל ג, לג. ז, כז. ראה מאמרי אדה\"א בראשית ע' רמג. וש\"נ. דברים ח\"א ע' ריב ואילך. שע\"ת כט, ג."],["3401","232","<b>מלכותך מכ\"ע</b>: בגד: ליתא. ט: כבפנים."],["3402","233","<b>דוד מ\"י ח\"ו</b>: מלך ישראל חי וקים — ר\"ה כה, א (נוסח קידוש לבנה). ראה עט\"ר ע' ח. אמ\"ב (ש' הק\"ש) מ, ג. מאמרי אדה\"א דברים ח\"ג ע' תתכב. נ\"ך ע' רכו. לקמן פ' בשלח רכז, ב. רלד, א. פקודי תנז, ג."],["3403","234","<b>עד דוד הגדיל</b>: שמואל-א כ, מא. ראה מאמרי אדה\"ז תקס\"ח ח\"א ע' תקלו."],["3404","235","<b>ויעש דוד שם</b>: שמואל-ב ח, יג. ראה גם לקמן פ' ויקהל תלג, ב."],["3405","236","<b>כשמאריך בד'. . דאחד</b>: ברכות יג, ב."],["3406","237","<b>תמליכהו. . רוחות</b>: ראה זהר (רע\"מ) פינחס רכג, סע\"ב. עקב ערב, א. הנסמן במאמרי אדה\"א בראשית ע' לד."],["3407","238","<b>בשכמל\"ו] בחשאי</b>: פסחים נו, א. ראה שו\"ע אדה\"ז הל' ק\"ש סס\"א, סי\"ג. הל' יוה\"כ סתרי\"ט, ס\"ט. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670483\" data-slug=\"torat-chaim\" data-id=\"2300670483\">תו\"ח נח נה, ב</a>. לקמן פ' ויקהל תד, ד ואילך."],["3408","239","<b>העוה\"ב</b>: בגדט: ליתא."],["3409","240","<b>ביוה\"כ. . מעין דלע\"ל</b>: ראה לקו\"ת להאריז\"ל נח ו, יג. מאמרי אדה\"א דברים ח\"ג ע' תתקיג. ח\"ד ע' א'קפ ובהנסמן בהנ\"ל. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670028\" data-slug=\"torat-chaim\" data-id=\"2300670028\">תו\"ח נח מו, א</a> ובהערה 11."],["3410","*241","<b>העוה\"ב דלע\"ל או' בשכמל\"ו בקול רם</b>: ראה גם לקמן פ' יתרו רנד, ב. ויקהל תה, א."],["3411","241","<b>ביוה\"כ. . בשכמל\"ו בקול רם</b>: ראה שו\"ע אדה\"ז הל' יוה\"כ סתרי\"ט, ס\"ט. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670483\" data-slug=\"torat-chaim\" data-id=\"2300670483\">תו\"ח נח נה, ב</a> ובהערה 21. ש\"א ל, א. לקמן פ' יתרו רנד, ב. ויקהל תד, ד. תו, ד."],["3412","242","<b>בקול רם</b>: תוקן ע\"פ בגדט. ובתו\"ח: בק\"ש."],["3413","243","<b>בשכמל\"ו בקול רם. . בבהמ\"ק</b>: ראה תענית טז, ב."],["3414","244","<b>סובב וממלא</b>: ראה גם בענין סובב וממלא לעיל נז, א ואילך."],["3415","245","<b>שנק'</b>: ניתוסף ע\"פ גט."],["3416","246","<b>עלמין סתימין. . דאתגליין</b>: ת\"ז בהקדמה (יז, א)."],["3417","247","<b>ברוך ה'. . ועד העולם</b>: נסמן לעיל פ' שמות יח, ג."],["3418","248","<b>בי\"ה ה' צור עולמים</b>: ישעי' כו, ד."],["3419","249","<b>שבגעה\"ע</b>: בד: שבעדן העליון."],["3420","250","<b>התענוג והשגה</b>: בד: השגה."],["3421","251","<b>ממש</b>: בד: ליתא."],["3422","252","<b>ובכל חודש ושבת עולים הנשמות</b>: נסמן לעיל לה, ב."],["3423","253","<b>מעונג</b>: ט: מעולם."],["3424","254","<b>להשתחוות לפני ה'</b>: ישעי' סו, כג [בדילוג]."]]],[2300540453,"בינה שבמח'<sup data-n=\"3425\">255</sup> כו' וזהו [כ]משל המח' הבאה לגילוי בדבור כו'. וכמו\"כ בגעה\"ת דיצי' ועשי' יש בו בחי' ההעלם וגילוי בערך זה שהשפע באה להם מהעלם העונג דחכ' דמל' דיצי' או עשי' לגילוי השגה ובכל שבת וחדש עולים נשמות שבגעה\"ת לג\"ע [העליון] וכמו ילכו מחיל אל חיל<sup data-n=\"3426\">256</sup> כו', וכך הוא עד נשמות שבגופים דכל שבת דכתי' וקראת לשבת ענג<sup data-n=\"3427\">257</sup> כו' [וכתי'] אז תתענג על ה'<sup data-n=\"3428\">258</sup> דא<sup data-n=\"3429\">259</sup> צלותא דמעלי שבתא כו' (וכידוע שזהו עיקר ההפרש בין תפלת שבת<sup data-n=\"3430\">260</sup> לתפלת החול להתענג על ה' בעונג האלקי שבעצם שלמעלה מן העונג הבא בהשגת השכל כו'). וכך הוא בדרך פרט בפרטיות ההשתל' עו\"ע שמבחי' העלם העליון בא לידי גילוי בתחתון, וכמו במלאכים <span data-k=\"pg\">222</span> ּ דכתיב וקרא זא\"ז ותרגומו ומקבלין<sup data-n=\"3431\">261</sup> דין מן דין כו' (רק שמבחי' גילוי ההעלם שבעליון נעשה העלם בתחתון כמו דבור שבעליון נעשה מח' בתחתון<sup data-n=\"3432\">262</sup> כמו אותיות מח' [ש]נק' דבור שבמח' בא בהעלם בדבור כו' והיינו וקרא זא\"ז כו' וכמ\"ש במ\"א), ובדרך כלל שרש [ה]נשמות מעלמא דאתכסיא שהוא בחי' המח' ושורש המלאכים מבחי' דבור<sup data-n=\"3433\">263</sup> העליון וכמ\"ש וברוח פיו כ\"צ<sup data-n=\"3434\">264</sup> [בכל עולם] מג' עולמות דבי\"ע כו'. וכמו\"כ יובן בכללות הכל שהוא בחי' העלם וגילוי באוא\"ס שבמל' דאצי' שבא בהתחלקות ב' מדרגות ע\"ד הנ\"ל ממש והוא כמו מה שאו' אתה הוא כו', פי' אתה מדבר לנוכח מפני שהוא בא בגילוי אור האלקי ממש כו' ונק' עלמא דאתגליא בכללות והוא בחי' דבור העליון כמו מאמר יהי אור כו', והן אותיות שנבראו בהן כל העולמות בכלל ו[ב]פרט וכמו גילוי השכינה לנשמות בג\"ע העליון וגעה\"ת בהשגה כנ\"ל וכמו ואתה מחיה את כולם א\"ת<sup data-n=\"3435\">265</sup> ואתה הן<sup data-n=\"3436\">266</sup> כ\"ב אותיות [בכלל] שיוצאים בה' מוצאות הפה העליון וכמ\"ש בס\"י קבען בפה<sup data-n=\"3437\">267</sup> כידוע. ופי' הוא לשון נסתר ונעלם היינו בחי' ההעלם של אותו האור האלקי הנעלה<sup data-n=\"3438\">268</sup> כמו שהוא עדיין למעלה מבחי' המשכה ושפע להוות כל העולמות מאין ליש כו' ונק' עלמא דאתכסיא בכללות וכמשל המח' באדם כנ\"ל בדרך פרט וכו', וזהו בחי' כ\"מ<sup data-n=\"3439\">269</sup> המתנשא מימו\"ע ונק' בבחי'<sup data-n=\"3440\">270</sup> סוכ\"ע [בכלל] כנ\"ל וד\"ל.\n<b>וזהו</b> אתה הוא ב' מדרגות הללו דבחי' העלם וגילוי [ב]כללות שניהם מתייחדים כאחד קודם שנה\"ע ואתה הוא משנבה\"ע באין שינוי כלל וכמ\"ש אני ה' לא שניתי כו', לפי שיש עוד מדריגה שלישית שלמעלה מב' המדרגות דסובב וממלא בבחי'",[["3425","255","<b>שבמח'</b>: בגט: שבמל'."],["3426","256","<b>ילכו מחיל אל חיל</b>: תהלים פד, ח."],["3427","257","<b>וקראת לשבת ענג</b>: ישעי' נח, יג."],["3428","258","<b>אז תתענג על ה'</b>: ישעי' נח, יד. מובא לקמן פ' תרומה שו, א בשם הזהר. ראה הנסמן במאמרי אדה\"א שמות ח\"א ע' קצ."],["3429","259","<b>דא</b>: ניתוסף ע\"פ: גט."],["3430","260","<b>ההפרש בין תפלת שבת</b>: ראה גם שה\"א ע' מו. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680135\" data-slug=\"torat-chaim\" data-id=\"2300680135\">תו\"ח ויחי רמא, ב</a>."],["3431","261","<b>וקרא. . ומקבלין</b>: נסמן לקמן פ' בשלח קמג, ד."],["3432","262","<b>דבור שבעליון נעשה מח' בתחתון</b>: ראה מאמרי אדה\"א קונטרסים ע' תקמז. וש\"נ. שעה\"י קלז, ב הערה 25."],["3433","263","<b>[ה]נשמות. . המח'. . המלאכים. . דבור</b>: ראה גם לעיל פ' שמות לט, ד. וש\"נ."],["3434","264","<b>וברוח פיו כ\"צ</b>: תהלים לג, ו."],["3435","265","<b>א\"ת. . כ\"ב</b>: ראה גם לעיל יט, ג."],["3436","266","<b>ואתה הן</b>: בגדט: ליתא."],["3437","267","<b>קבען בפה</b>: ראה שם פ\"ב, מ\"ג."],["3438","268","<b>הנעלה</b>: בד: הנגלה."],["3439","269","<b>כ\"מ</b>: בד: המל'. גט: כתר מל'."],["3440","270","<b>בבחי'</b>: בד: ליתא."]]],[2300540473,"העלם וגילוי [ה]נ\"ל והוא בחי' עצמות אוא\"ס ממש<sup data-n=\"3441\">271</sup> שלמעלה מבחי' מל' [כו'], ואתה והוא בחי' העלם וגילוי שוין שם ממש להיות למעלה גם מבחי' מקור המשכה והשפעה כלל רק הוא גילוי אור עצמותו לבד כמו שהוא בעצמו ממש ע\"כ לא שייך שם ענין העלם [ה]אור וגילוי האור שאין זה רק לגבי ענין שפע אור עכ\"פ, וע\"כ גם לשון סכ\"ע או המתנשא מימו\"ע לא יתכן לקרותו עדיין ולזה נק' סדכ\"ס<sup data-n=\"3442\">272</sup> שגם מסתימו הוא סתום ולמח\"ת בי' כלל<sup data-n=\"3443\">273</sup> ע\"כ גם בחי' ההעלם נק' גילוי לפניו ואין הפרש כלל בין אתה להוא כו' שאין העלם וגילוי שייך רק בבחי' התפשטות חוץ מעצמותו כו', וזהו ענין<sup data-n=\"3444\">274</sup> אתה הוא קודם כו' וגם אחר שנה\"ע ע\"י צמצום והתפשטות בבחי' העלם וגילוי בכלל ואתה הוא כו' וגם בפרט כמו ב' מדרגות דעלמא סתימא' ואתגליא הנ\"ל שניהם שוין ממש לפניו מטעם הנ\"ל<sup data-n=\"3445\">275</sup>. וראי' לזה ממה שאנו רואים גם בהתהוות העולמות מאין ליש ממש שוין לפניו געה\"ע וגעה\"ת בלי חילוק [מו\"מ<sup data-n=\"3446\">276</sup>] כלל וכלל כמו מאמר<sup data-n=\"3447\">277</sup> בשמים ממעל ועל הארץ מתחת אין עוד בשניהם שוים ממש, וכן או' אם אסק שמים<sup data-n=\"3448\">278</sup> שם אתה ואציעה שאול הנך משום דקמי' כחשיכה כנהורא כו' רוג\"ש<sup data-n=\"3449\">279</sup> שוים, ואע\"פ שנא' לכו חזו מפעלות אלקים כו' שנק' מפעלות לשון רבים מפני שבא <span data-k=\"pg\">קיא</span> ּ האור והשפע האלקי בחילוק מדרגות משם אלקי' בריבוי השתל' וצירופים רבים ושונים כידוע דיש בשם אלקים בכלל ק\"ך צירופים<sup data-n=\"3450\">280</sup> כמ\"ש בס\"י ה' אבנים<sup data-n=\"3451\">281</sup> בונים ק\"ך בתים כו' עד מ\"ח צירופים אחרונים שיורדים למטה מטה מאד להיות להיכלות דק\"נ כמ\"ש את זלעו\"ז<sup data-n=\"3452\">282</sup> עשה האלקי' כו', עכ\"ז אין חילוק כלל בין האור היותר עליון שבגעה\"ע עם הצמצום [ה]יותר אחרון שמתחת לארץ כו' בז' ארצות<sup data-n=\"3453\">283</sup> דשאול כו' וכמ\"ש וגם חשך<sup data-n=\"3454\">284</sup> לא יחשיך ממך, לפי שכל בחי' השתל' דהעלם וגילוי בכלל שוין לפניו ממש מטעם הנ\"ל ע\"כ גם בכל פרטי חילוקי המדרגות שבממכ\"ע שוין [מ]היותר עליון עד היותר תחתון, וז\"ש אתה הוא עד שלא כו' שניהן שוין ע\"כ אתה הוא משנה\"ע שניהם שוין בכלל ובפרט. וראי' לזה מפסוק זה עצמו שא' לכו חזו מפעלות אלקי' אשר שם שמות בארץ כו' והן רבוי השמות שבא בבחי' אור ושפע בעולמות ובכללות היינו ב' שמות דאלקי' ואד' שהוא בחי' העלם וגילוי [ב]בחי' ממכ\"ע עצמו, שבחי' אלקי' הוא בבחי' ההסתר שהוא הצמצום כידוע בענין אלקי' אותיות מי אלה<sup data-n=\"3455\">285</sup> [כו'] וכמו כבוד אלקי' הסתר דבר<sup data-n=\"3456\">286</sup> כו', ושם אד' הנק' אדון כל כו' הוא",[["3441","271","<b>אוא\"ס ממש</b>: בד: א\"ס ב\"ה."],["3442","272","<b>סדכ\"ס</b>: זהר בהקדמה ב, א. ועוד."],["3443","273","<b>ולמח\"ת בי' כלל</b>: ראה ת\"ז בהקדמה (יז, א)."],["3444","274","<b>ענין</b>: ניתוסף ע\"פ: ט."],["3445","275","<b>הנ\"ל</b>: בד: זה וד\"ל."],["3446","276","<b>מו\"מ</b>: בד: מעלה ומטה."],["3447","277","<b>כמו מאמר</b>: גט: כמ\"ש."],["3448","278","<b>אם אסק שמים</b>: תהלים קלט, ח."],["3449","279","<b>כנהורא. . רוג\"ש</b>: בד: כאורה. . רוחניות וגשמיות."],["3450","280","<b>אלקים. . ק\"ך צירופים</b>: נסמן לעיל כ, א."],["3451","281","<b>בס\"י ה' אבנים</b>: נסמן לעיל ס, ג."],["3452","282","<b>את זלעו\"ז</b>: נסמן לעיל פ' שמות לד, ג."],["3453","283","<b>בז' ארצות</b>: ראה זהר בהקדמה ט, ב. פרדס (שער סדר עמידתן) ש\"ו, פ\"ג. מאמרי אדה\"א ויקרא ח\"ב ס\"ע תשמז ואילך. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670055\" data-slug=\"torat-chaim\" data-id=\"2300670055\">תו\"ח בראשית א, ג</a> ובהערה 36. הנחות תקע\"ז ע' מא."],["3454","284","<b>וגם חשך</b>: נסמן לעיל סד, א."],["3455","285","<b>אלקי' אותיות מי אלה</b>: ראה זהר בהקדמה ב, א. הנסמן במאמרי אדה\"א נ\"ך ע' תעב."],["3456","286","<b>כבוד אלקי' הסתר דבר</b>: משלי כה, ב."]]],[2300540491,"מ\"ש כבוד מלכים חקור דבר<sup data-n=\"3457\">287</sup> בגילוי ונק' דינא דמלכותא<sup data-n=\"3458\">288</sup> כו', ועל שניהם [הרי] אמר אשר שם שמות בארץ ששם אותם לבוא בידי השתל' העולמות<sup data-n=\"3459\">289</sup> דבחי' העלם וגילוי, אבל למעלה מבחי' מקור ההשתל' ב' השמות שוין כנ\"ל בענין אתה והוא בכלל ו[ב]פרט, וזהו אשר שם שמות בארץ והן הן גבורות פעולותיו ית' כמ\"ש לכו חזו מפעלות אלקי' במה ששם שמות דהעלם וגילוי בארץ אף שאין העלם וגילוי תופס מקום כלל לפניו כנ\"ל [וזהו] א\"ת שמות כו' וד\"ל.\n<b>וזהו</b> ואברכה שמך לעולם ועד פי' לעולם [ועד בבחי'] נצחי' דא\"ס ממש גם בב' מדרגות דהעלם וגילוי הנ\"ל לפי שבברכה זו היא באה מבחי' עצמיות [אור] א\"ס ב\"ה ממש שלמעלה מבחי' העלם וגילוי בכלל ו[ב]פרט, והוא מ\"ש ואברכה שמך דוקא שהוא מבחי' שמו הגדול כמו שהוא בעצמות ממש שלמעלה גם מבחי' סובב וממלא בכללות הכל, וכידוע דב' מדרגות הללו דהעלם וגילוי שרשם הראשון היותר כללי הוא ב[אור] א\"ס עצמו ג\"כ, והוא מה שידוע דאוא\"ס למעלה מעלה<sup data-n=\"3460\">290</sup> עד אין שיעור כו' שהוא בחי' התנשאות שמצד עצמו שאין לו שיעור למעלה בעילוי אחר עילוי העלם אחר העלם כו' ונק' סובב הכללי ואוא\"ס מתפשט בגילוי אור למטה מטה עד אין תכלית כו', והוא בחי' העלם וגילוי בכללות יותר, ועל שניהם אמר ואברכה שמך שית[ברך] באור גדול [מ]עצמיות ומהות אוא\"ס ב\"ה שלמעלה מבחי' העלם וגילוי הללו שכלולים מכל<sup data-n=\"3461\">291</sup> עצמותו ית' והיינו כאשר ית' שמך ממש שהוא עצם גילוי אורו שלמעלה מכל צמצום<sup data-n=\"3462\">292</sup> והתפשטות אז ממילא יומשך תוס' אור גדול גם בב' מדרגות הללו דהעלם וגילוי סובב וממלא הכללי יותר, וזה לע\"ו גם בהעלם וגילוי דסובב וממלא יהי' תוס' ברכה והמשכה מנצחיות דמהות עצמיות א\"ס ב\"ה <span data-k=\"pg\">224</span> ּ ממש והוא לפי שארוממך אלקי [שנתעלה בחי' אלקי] המלך בחי' ממלא וסובב הנ\"ל בכללות לבחי' העצמו' דא\"ס ממש (והוא ב' מדרגות דא\"ס למעלה עד אין קץ ולמטה עד אין תכלית שהן עכ\"פ שורש לבחי' מעלה ומטה וכלולי' ומתעלים בכח מהות עצמיות<sup data-n=\"3463\">293</sup> ממש שלמעלה לגמרי גם מבחי' צמצום והתפשטות זאת שהוא<sup data-n=\"3464\">294</sup> חו\"ג שבעצמו' שעז\"א כי בי\"ה ה' צור עולמים כו' יו\"ד צמצום ה'<sup data-n=\"3465\">295</sup> התפשטות וההעלם וצמצום הראשון קודם להתפשטות דקו\"ח כו') וע\"כ ממילא יורד ונמשך אחר [ה]העלאה [זו בתוס' ברכה בשמות הללו דסובב וממלא בפרט<sup data-n=\"3466\">296</sup>, וזהו ואברכה<sup data-n=\"3467\">297</sup> כשמתברך אחר ההעלאה] דארוממך אלקי המלך לשני המדרגות דהעלם וגילוי כו' כנ\"ל (וזהו מי כה'",[["3457","287","<b>כבוד </b>[ג: וכבוד]<b> מלכים חקור דבר</b>: משלי שם [ושם: וכבוד — ראה ש\"א כו, א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680366\" data-slug=\"torat-chaim\" data-id=\"2300680366\">תו\"ח ויגש רלו, ב</a> הערה 16]."],["3458","288","<b>אד'. . דינא דמלכותא</b>: נסמן לקמן פ' בא פח, א."],["3459","289","<b>בידי השתל' העולמות</b>: בד: בסדר ההשתלשלות."],["3460","290","<b>דאוא\"ס למעלה מעלה</b>: נסמן לעיל ד, ד."],["3461","291","<b>מבחי'. . מכל</b>: ט: מכל. . בד: מבחי'. ט: בכח."],["3462","292","<b>מכל צמצום</b>: בד: מצמצום. ט: מבחי' צמצום."],["3463","293","<b>בכח מהות עצמיות</b>: בד: בבחי' עצמיות. ט: בכח מהו\"ע."],["3464","294","<b>שהוא</b>: ט: שהן רק."],["3465","295","<b>יו\"ד. . ה'</b>: ניתוסף ע\"פ: ט."],["3466","296","<b>בפרט</b>: ט: בכלל ובפרט."],["3467","297","<b>ואברכה</b>: ט: ניתוסף: שמך."]]],[2300540509,"אלקינו המגביהי לשבת המשפילי<sup data-n=\"3468\">298</sup> לראות כו' מגביהי לשבת בהעלם אחר העלם ומשפילי למטה<sup data-n=\"3469\">299</sup> כו' כמ\"ש במ\"א). וזהו כללות ענין פסוד\"ז שהוא רק להוסיף ולהבהיק אור גדול בשם הוי' וכמו הללו את שם הוי'<sup data-n=\"3470\">300</sup> כו' והעיקר לי\"ה דשם הוי' כמו הלל[ו] י\"ה כו' והן ב' מדרגות דהעלם וגילוי הוא בכללות הנ\"ל<sup data-n=\"3471\">301</sup> כמ\"ש כי בי\"ה כו', והוספה זאת או להבהיק האור צריך שיבא מלמעלה מעלה מב' מדרגות הללו והוא מעצמות ומהות א\"ס ב\"ה ע\"כ העיקר הוא בת\"ל ארוממך אלקי המלך כדי שיתברך שמך העצמי ממש לע\"ו גם בבחי' העלם וגילוי דסובב וממלא [שממילא] יוכל להיות תוס' אור גדול בי\"ה דשם הוי' בכלל ובפרט וד\"ל. וזהו שבפסוק [ראשון] דת\"ל הוא בכמ\"ל ואח\"כ א[ו]מר בכ\"י אברכך כו' בחו\"ב ואח\"כ גדול ה' במדות שלו בחג\"ת<sup data-n=\"3472\">302</sup> ואח\"כ דור לדור כו' במו\"ד שנמשך בעלמין סתימין ועלמין דאתגליין בנשמות ומלאכים<sup data-n=\"3473\">303</sup> שמקבלים מהדר כבוד הוד<sup data-n=\"3474\">304</sup> מל[כותו] הארה דהארה כו', שכ\"ז הוא הכנה להיות גם מלאכים ונשמות מהללים לשם הוי' עד השמים והארץ שאמר הללו את ה' מן השמים וכה\"ג, וכ\"ז הוא בבחי' ההעלאה כדרך שמסדרים שבחו של מלך תחלה ואח\"כ כאשר מבקשים ממנו ברכה מברכים אותו שהוא ענין ויברך דוד את ה' כו' וד\"ל.\n<b>והנה</b> אחר פסוד\"ז אומר שתים לפניה [שהן] יוצ\"א ואה\"ר<sup data-n=\"3475\">305</sup> כו' ברכת יוצ\"א מדבר בביטול המלאכים בשיר ושבחה שכולם משבחים ומפארים כו', והקדים תחלה של<sup data-n=\"3476\">306</sup> שרש המלאכים כמ\"ש מה רבו מעשיך<sup data-n=\"3477\">307</sup> כולם בחכמה עשית ועכ\"ז הוא מלך מרומם לבדו כו' וע\"כ ברחמיך הרבים כו' וכ\"ז עד יוצר המאורות הוא בבחי' ממכ\"ע שהוא שם אלקים שורש העולמות והמלאכים שא\"א להם כלל לעלות וליכלל בשם הוי' דבחי' סובב להיותו למעלה מעלה [מ]מקור חוצבה כידוע. אבל ברכה שני' דאה\"ע אהבתנו מדבר בשרש הנשמות למעלה שהוא [שם הוי' ד]בחי' סובב בכללות כנ\"ל<sup data-n=\"3478\">308</sup>, ע\"כ אמר אה\"ע אהבתנו [כו' שיומשך עוז אה\"ר ששרשה בעצמו' דא\"ס ב\"ה ממש ע\"כ נק' אה\"ע בבחי' נצחי'] כמא' אה\"ר אהבתיך<sup data-n=\"3479\">309</sup> ע\"כ משכתיך חסד פי' שממשיך ומעורר אה\"ר דכנ\"י, וזהו [אבינו] אב כו' עד והאר עינינו בתורתיך ודבק לבינו ויחד לבבינו לאוי\"ר כנ\"ל שכ\"ז הכנה להיות התפעלות האהבה דכל לבבך כו' בק\"ש אמיתי', והוא לפי שאה' זאת דואהבת [את] ה' אלקיך בכל לבבך<sup data-n=\"3480\">310</sup> כו' הוא דוקא למהו\"ע א\"ס ב\"ה [ממש] כי כל מס\"נ [ו]דביקות האמיתי אינו רק למהו\"ע ית' ממש, כמו אליך ה' נפשי אשא<sup data-n=\"3481\">311</sup> אליך ממש וכן",[["3468","298","<b>מי. . המגביהי. . המשפילי</b>: תהלים קיג, ה. ו. ראה סידור תפלת ר\"ה רלז, ב ואילך. מאמרי אדה\"א נ\"ך ע' עט. וש\"נ."],["3469","299","<b>למטה</b>: ט: ניתוסף: מטה."],["3470","300","<b>הללו את שם הוי'</b>: תהלים קיג, א. קלה, א. ט: הללו את הוי' — תהלים קמח, א."],["3471","301","<b>הנ\"ל</b>: בד: הכל."],["3472","302","<b>שלו בחג\"ת</b>: ניתוסף ע\"פ: ט."],["3473","303","<b>ומלאכים</b>: ט: ואח\"כ במלאכים."],["3474","304","<b>הוד</b>: ט: ליתא."],["3475","305","<b>ואה\"ר</b>: בד: ואה\"ע. וכ\"ה בסמוך בפנים."],["3476","306","<b>של</b>: גט: ליתא."],["3477","307","<b>מה רבו מעשיך </b>[ט: ניתוסף: כו']: תהלים קד, כד."],["3478","308","<b>כנ\"ל</b>: בד: ליתא."],["3479","309","<b>אה\"ר אהבתיך</b>: בד: אה\"ע אהבתנו — נוסח ברכת ק\"ש. ט: אה\"ע אהבתיך — נסמן לעיל סב, ג הערה 131."],["3480","310","<b>דואהבת. . לבבך</b>: ואתחנן ו, ה."],["3481","311","<b>אליך ה' נפשי אשא</b>: תהלים כה, א. ראה גם לקמן פ' בשלח קעז, ד."]]],[2300540527,"לדבקה בו<sup data-n=\"3482\">312</sup> ממש כו' וכ[ן] א' בכל קראנו אליו<sup data-n=\"3483\">313</sup> ולא למדותיו<sup data-n=\"3484\">314</sup> פי' גם לא למדותיו הכלולים בעצמותו ית' <span data-k=\"pg\">קיב</span> ּ ממש שהוא בחי' העלם וגילוי דבחי' סומ\"מ בכללות הכל<sup data-n=\"3485\">315</sup> [רק למהו\"ע ית' לבדו דוקא כמו מי לי בשמי'<sup data-n=\"3486\">316</sup> ועמך לא חפצתי בארץ, וידוע ששמים וארץ<sup data-n=\"3487\">317</sup> למטה הן כמו<sup data-n=\"3488\">318</sup> בחי' סובב וממלא] למעלה כי השמים התחתוני' שהן עגולים מקיפים לארץ מכל צד ומשפיעי' רוחני' הד\"[י] ודצח\"מ בארץ, ו[הארץ ה]גם שהכל הוא מן העפר<sup data-n=\"3489\">319</sup> כו' מ\"מ נק' בחי' מקבל השפע ממזל שברקיע כידוע. כך הוא למעלה [ב]בחי' סוכ\"ע שנק' שמים עליונים בחי' מקיף הכללי לכל ההשתל' [ה]בא בגילוי אור וחיות בריבוי התחלקות המדרגות<sup data-n=\"3490\">320</sup> בג\"ע העליון וגעה\"ת כו', ובחי' ארץ הוא בחי' ממכ\"ע שמחי' הכל בחילוק מדרגות וכמו שהארץ למטה מתחלה<sup data-n=\"3491\">321</sup> יצמח הכל כו' ועכ\"[ז] מקבל מבחי' סובב המקיף וכמ\"ש כי עמך מקור החיים כו' כנ\"ל וד\"ל. ועכ\"ז אמר מי לי בשמים בחי' סוכ\"ע ועמך מה שעמך בטל שהוא בחי' ממכ\"ע לא חפצתי בארץ כו' רק למהו\"ע לבדו שהרי בחי' סוכ\"ע<sup data-n=\"3492\">322</sup> גם בכללות אינו רק ב' שמות דהוי' ואלקים כו'<sup data-n=\"3493\">323</sup> אליו ולא למדותיו שהן שמותיו כו' וד\"ל.\n<b>וזהו</b> ואהבת את הוי' אלקיך אחר מצות יחו\"ע במס\"נ בא'<sup data-n=\"3494\">324</sup> ממש שא' הוי' אלקינו ה' אחד שלמעלה מבחי' סובב וממלא הכללי', כי עיקר התשוקה [ל]מס\"נ צריך להיות בעצמותו ומהותו לבדו ולא גם למקיף הכללי שהוא עכ\"פ רק בבחי' שם משמותיו והוא שם הוי', וגם לא יחפוץ לקנות חיי עוה\"ב שהוא נברא ביו\"ד<sup data-n=\"3495\">325</sup> דשם הוי' שנק' ע\"מ לקבל פרס (ומ\"ש אליך הוי' נפשי אשא כו' היינו לשם הוי' שבמהותו ועצמותו ממש כמו ושמי הוי'<sup data-n=\"3496\">326</sup> כו' שהוא בהוי'<sup data-n=\"3497\">327</sup> דחכ' שבתו' שנחשב מעצמותו ממש וכמ\"ש אחר ואהבת כו' ודברת בם<sup data-n=\"3498\">328</sup> כו' וכמו שית'), [ו]כ\"ש שאינו חפץ לגעה\"ע שאינו רק הארה אחת משם אלקי' בבינה שבמל' כו'. וז\"ש מי לי בשמים וכו' עלמא סתימאה ולא בארץ עלמא דאתגליא בכלל ובפרט אע\"פ שגם בהם יש הארה אחת משמותיו משם אלקים ואדני כו' שהרי תדבק נפשו באח\"פ לבדו שלא ע\"מ לקבל פרס ליהנות מזיו כו' וד\"ל.\n<b>אך</b> הנה לכאו' פי' הפשוט דואהבת את<sup data-n=\"3499\">329</sup> הוי' [אלקיך] כו' שיאהוב לשם הוי' שהוא אל[ק]יך כו' שהם בחי' סומ\"מ",[["3482","312","<b>לדבקה בו</b>: נסמן לעיל פ' שמות לג, ב."],["3483","313","<b>בכל קראנו אליו</b>: ואתחנן ד, ז."],["3484","314","<b>אליו ולא למדותיו</b>: במאמרי אדה\"ז תקס\"ג כאן (ע' קכו): שארז\"ל בספרי — ראה פרדס (שער הכוונה) של\"ב, פ\"ב. מאמרי אדה\"א ויקרא ח\"א ע' נ. וש\"נ. נ\"ך ע' לד. וש\"נ."],["3485","315","<b>הכל</b>: בד: ליתא."],["3486","316","<b>מי לי בשמי'</b>: תהלים עג, כה."],["3487","317","<b>ששמים וארץ. . סובב וממלא</b>: ראה גם מאמרי אדה\"ז תקס\"ג כאן (ע' קכו). הנסמן במ\"מ לשה\"א נח, א הערה 2."],["3488","318","<b>כמו</b>: ניתוסף ע\"פ ט."],["3489","319","<b>שהכל הוא </b>[בד: הי']<b> מן העפר</b>: קהלת ג, כ."],["3490","320","<b>המדרגות</b>: ג: ניתוסף: וכמ\"ש והארץ הדום רגלי כו'. ט: ניתוסף: השמים כסאי והארץ הדום רגלי כו' — ישעי' סו, א."],["3491","321","<b>מתחלה</b>: בד: ממנה."],["3492","322","<b>סוכ\"ע</b>: בד: סובב וממלא."],["3493","323","<b>כו'</b>: בד: וכתיב."],["3494","324","<b>במס\"נ בא'</b>: ראה זהר (רע\"מ) משפטים קיט, א. צו לג, א. מאמרי אדה\"א דברים ח\"ב ע' תו. וש\"נ. שמות ח\"א ע' רעח ואילך. הנחות תקע\"ז ע' שא."],["3495","325","<b>עוה\"ב שהוא נברא ביו\"ד</b>: מנחות כט, ב."],["3496","326","<b>ושמי הוי'</b>: וארא ו, ג."],["3497","327","<b>בהוי'</b>: ג: שם הוי'."],["3498","328","<b>ודברת בם</b>: ואתחנן ו, ז."],["3499","329","<b>את</b>: ניתוסף ע\"פ ט."]]],[2300540545,"בכללות כנ\"ל וד\"ל<sup data-n=\"3500\">330</sup>, ולא לשלול האהבה זו לשם<sup data-n=\"3501\">331</sup> הוי' אע\"פ שכוונתו רק למהו\"ע ית', הענין הוא כידוע ד[תי'] ואהבת בגימט' ב\"פ אור<sup data-n=\"3502\">332</sup> או\"י ואו\"ח רו\"ש כו', והענין הוא דיש באהבה זאת בחי' כלות הנפש כמ\"ש אפילו הוא נוטל את נפשך<sup data-n=\"3503\">333</sup> כו' והוא מ\"ש בכל לבבך בשני יצריך<sup data-n=\"3504\">334</sup> למסור רצון הטבעי ולמאוס בחיי הגוף כו', וגם נכלל בזה ממילא שלא יחפוץ שום דבר קבלת שכר לעצמו כלום אפ[י'] לעוה\"ב רק אליו לבדו ית' נושא את נפשו כו' כי אינו חפץ רק ליכלל ולידבק במהותו ועצמותו לבדו כו' והוא בחי' או\"ח בחי' רצוא, והב' הוא אהבה ותשוקה בקרבת ה' שיהי' קרוב אליו בגילוי אור מלמעלה למטה בחי' שוב כו' בחי' או\"י, ומתכללים או\"ח [ו]או\"י שבאהבה זו כא' כמ\"ש ואהבת שהוא גימט' ב\"פ אור, ובזה נעשה ג\"כ יחוד בב' שמות דהוי' ואלקים שהוא ג\"כ ב' מדרגות דאו\"י ואו\"ח כידוע. והיינו פי' ואהבת שיהי' ע\"י אהבה כזאת למהו\"ע ית'<sup data-n=\"3505\">335</sup> דוקא ולא למדותיו עד שמתכללים או\"י ואו\"ח כא' יחוד גמור בהוי' [ו]אלקי' שהם ג\"כ או\"י ואו\"ח שמתייחדי' כא' [ויוכללו] במהותו ועצמותו שלמעלה מבחי' סובב וממלא וחוזר ונמשך מלמעלה מעלה<sup data-n=\"3506\">336</sup> אא\"ס ב\"ה תוס' אור בהוי' אלקי' ע\"י תומ\"צ והוא מ\"ש והיו הדברים האלה<sup data-n=\"3507\">337</sup> (כמשי\"ת בע\"ה).\n<b>וזהו</b> הוא אהרן ומשה אשר אמר ה' להם הוציאו את ב\"י כנ\"ל, דהנה אהרן הוא מז<sup data-n=\"3508\">339</sup>' רועים<sup data-n=\"3509\">338</sup> המפרנסי' לכנ\"י <span data-k=\"pg\">226</span> ּ ואהרן הוא בחי' החסד<sup data-n=\"3510\">340</sup> וענין פרנסה זו כמו הרועה צאן שמפרנס במרעה טוב כמ\"ש דוד ה' רועי<sup data-n=\"3511\">341</sup> כו' [בנאות דשא<sup data-n=\"3512\">342</sup> ירביצני כו'], כך כנ\"י שנק' צאן קדשים מפרנסם הרוע[ה] במרעה טוב [כ]משה שנק' רע\"מ<sup data-n=\"3513\">343</sup> כו' שהמשיך להם תומ\"צ כמ\"ש תורה צוה לנו משה<sup data-n=\"3514\">344</sup> [כו'] והוא בבחי' לחמה של תורה ואהרן הוא הרועה המפרנס להמשיך בלבם [ב]תומ\"צ<sup data-n=\"3515\">345</sup> האהבה והתשוקה רבה הנ\"ל במהו\"ע ית' [דוקא] ולכך נק' שודמ\"ט כו', וכמו בהעלותך את הנרות שהן כללות נש\"י עד\"מ המדליק את הנר ואהרן נק'<sup data-n=\"3516\">346</sup> כה\"ר העליון הוא המדליק ומעלה בכל ניצוץ מישראל שתאיר נשמתו באור האלקי והוא בבחי' התפעלות אה\"ר הנ\"ל שמדליק התפעלות רשפי אש התשוקה אלקי בהמשכה מלמעלה למטה דוקא כי אתה תאיר נרי כו', והוא",[["3500","330","<b>וד\"ל</b>: ט: ליתא."],["3501","331","<b>זו לשם</b>: בד: זולת שם."],["3502","332","<b>ואהבת בגימט' ב\"פ אור</b>: נסמן לעיל סה, ג."],["3503","333","<b>אפי' הוא </b>[בד: ליתא]<b> נוטל את נפשך</b>: ראה ספרי ואתחנן ו, ה. ברכות נד, א (במשנה)."],["3504","334","<b>בכל לבבך בשני יצריך</b>: ואתחנן ו, ה. ספרי וברכות שם."],["3505","335","<b>ית'</b>: ניתוסף ע\"פ ט."],["3506","336","<b>מלמעלה מעלה</b>: גט: עי\"ז מעצמות."],["3507","337","<b>והיו הדברים האלה</b>: ואתחנן ו, ו."],["3508","339","<b>מז' רועים</b>: נסמן לעיל פ' שמות ה, ד הערה 261."],["3509","338","<b>אהרן הוא מז' רועים</b>: ראה תיקונים לז\"ח קד, א. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201655\" data-slug=\"likkutei-sichot\" data-id=\"1300201655\">לקו\"ש חנוכה (כרך כ) ע' 643</a>. לקמן פ' תצוה שנו, א."],["3510","340","<b>ואהרן. . חסד</b>: נסמן לעיל לז, ג."],["3511","341","<b>ה' רועי</b>: תהלים כג, א."],["3512","342","<b>בנאות דשא</b>: תהלים שם, ב."],["3513","343","<b>[כ]משה שנק' רע\"מ</b>: ראה זהר וירא קו, א. שמות ח, ב. ועוד. פתיחתא דאיכ\"ר כד. יל\"ש איכה סוף רמז תתקצז. מאמרי אדה\"ז תקס\"ו ע' קמז. לקמן פ' בא צב, א. קיח, ב. בשלח קנה, ד. משפטים רפב, ב. תשא שפא, א. ויקהל תיא, ג."],["3514","344","<b>תורה צוה לנו משה</b>: ברכה לג, ב."],["3515","345","<b>[ב]תומ\"צ</b>: ט: בחי'."],["3516","346","<b>ואהרן נק'</b>: גט: ממש כך אהרן."]]],[2300540562,"ענין שנמשך אהבה [ר]בה זו<sup data-n=\"3517\">347</sup> העליונה למשוך לב כנ\"י שיהי' בהם התעוררות האה\"ר כו', וזהו שרועה ומפרנס לכנס\"י [ב]אה\"ר זו כו'. והטעם הוא<sup data-n=\"3518\">348</sup> שאהרן דוקא הוא הרועה לפרנס בהמשכה א[הבה] מלמעלה כו', הנה זהו הנרמז בתיבת שם<sup data-n=\"3519\">349</sup> אהרן שהוא א' ה\"ר ו[נו\"]ן פשוטה, וי\"ל תחלה ענין תי' ה\"ר שבשם אהרן, הנה בחי' התפעלות אהבה בלב נק' הר להיותו בבחי' התפשטות והגבה למעלה<sup data-n=\"3520\">350</sup> לעלות ולידבק למעלה בהתנשאות בעילוי אחר עילוי, כי פי' התפעלות הוא שנתפעל הלב וניזוז ממקומו שהוא רוח העולה ומתנשא למעלה מעלה כו', וכמו עד\"מ ההר בארץ שמוגבה ומרומם על כל שטח הארץ כדבר המתנשא ועולה למעלה, ואע\"פ שההר עפר דומם הוא<sup data-n=\"3521\">351</sup> כשאר הארץ ולמה יובדל משאר חלקי הארץ להתנשא בגובה כו' אך<sup data-n=\"3522\">352</sup> שבעפר זה דהר יש בחי' צומח שבא ע\"י יסוד הרוח<sup data-n=\"3523\">353</sup> שבעפר ונק' צומח שבדומם (כאלמוגים דים<sup data-n=\"3524\">354</sup> ) אע\"פ שאין שינוי בעצם העפר דהר מהעפר שבשאר חלקי הארץ כלל מ\"מ אנו רואים שיש<sup data-n=\"3525\">355</sup> ארץ הרים ובקעות וארץ מישור ויש הרים גדולים וקטנים וזהו הכל לפי המקום שבו נצמח הר גדול או קטן וכתיב כי ההרים ימושו<sup data-n=\"3526\">356</sup> כו' וכענין גדא דהר<sup data-n=\"3527\">357</sup> כו'). וכך יובן בענין התפעלות האה' אלקי' בלב דהיינו בבחי' יסוד הרוח שבלב שטבעה להתפעל ולעלות ולידבק למעלה והוא בבחי' רוח האדם העולה למעלה דוקא, כי הגם שנפש הטבעי' הוא בבחי' דומם ועפר שיסודו מעפר שמחמת זה רוח הבהמה יורדת למטה<sup data-n=\"3528\">358</sup> אחר גופני' וגשמי' כשור שנמשך אחר העשב ואין לו הכרה למעלה, אך רוח האדם הוא העולה למעלה להכיר את בוראו הוא מה שיש בטבע נפשו האלקי' ליכלל ולעלות ולידבק ביוצרה כידוע. ואמנם גם בבחי' דומם דרוח הבהמה ימצא בחי' הרוח האדם לעלות גם הוא למעלה ע\"י התגברות התפעלות אה\"ר דרוח האדם שגובר גם בלב בשר שיתפעל גם הוא בעליות והתכללות למעלה היפוך טבע רוח הבהמה, וכנראה בחוש שגם לב החומר[י] יתפעל מאד ויזוז ממקומו גם בתשוקה<sup data-n=\"3529\">359</sup> דרוח נשברה ובתשוקה דאה\"ר<sup data-n=\"3530\">360</sup> אלקי' וזהו כמו ההר שנק' צומח שבדומם כו' וד\"ל.\n<b>והנה</b> האבות נק' הרים<sup data-n=\"3531\">361</sup> כמו שמעו הרים<sup data-n=\"3532\">362</sup> כו' וגם אמרו לא כאברהם שקראו הר<sup data-n=\"3533\">363</sup>, לפי שהי' עבודת אברהם בבחי' התפעלות האהבה בדביקות שנק' אברהם אוהבי<sup data-n=\"3534\">364</sup>, רחימא",[["3517","347","<b>זו</b>: ט: ליתא."],["3518","348","<b>הוא</b>: ניתוסף ע\"פ ט."],["3519","349","<b>שם</b>: ניתוסף ע\"פ ט."],["3520","350","<b>למעלה</b>: ט: ליתא."],["3521","351","<b>הוא</b>: ניתוסף ע\"פ ט."],["3522","352","<b>אך</b>: גט: וצ\"ל."],["3523","353","<b>דהר. . צומח. . יסוד הרוח</b>: ראה גם מאמרי אדה\"א דברים ח\"ב ע' תרסד. וש\"נ. לקמן פ' בשלח קצט, ד. וש\"נ."],["3524","354","<b>כאלמוגים דים</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670347\" data-slug=\"torat-chaim\" data-id=\"2300670347\">תו\"ח בראשית כד, סע\"ב</a> ובהנסמן במ\"מ לשם."],["3525","355","<b>אנו רואים שיש</b>: ניתוסף ע\"פ: גט. ובתו\"ח כאן: יש."],["3526","356","<b>כי ההרים ימושו</b>: ישעי' נד, י."],["3527","357","<b>וכענין גדא דהר</b>: תוקן ע\"פ גט. בד: ליתא. ובתו\"ח כאן: והענין דהר — חולין מ, א."],["3528","358","<b>רוח הבהמה יורדת למטה</b>: קהלת ג, כא."],["3529","359","<b>בתשוקה</b>: בד: בתשו'."],["3530","360","<b>דאה\"ר</b>: גט: ואהבה."],["3531","361","<b>אבות נק' הרים</b>: ראה ר\"ה יא, א. מאמרי אדה\"ז תקס\"ז ריש ע' רד. מאמרי אדה\"א דברים ח\"א ע' נה. וש\"נ. ש\"א צח, א. שה\"א כה, א הערה 3."],["3532","362","<b>שמעו הרים</b>: מיכה ו, ב."],["3533","363","<b>לא כאברהם שקראו הר</b>: ראה רש\"י ויצא כח, יז. פסחים פח, א. שוח\"ט פא, ב. מאמרי אדה\"א דברים ח\"ב ע' תרסו. וש\"נ. שה\"א קה, א ובהערה 2."],["3534","364","<b>אברהם אוהבי</b>: ישעי' מא, ח."]]],[2300540578,"דמלכא<sup data-n=\"3535\">365</sup>, והי' הולך <span data-k=\"pg\">קיג</span> ּ ועולה לה' בדביקות הנפש ממדרגה למדרגה העליונה יותר והיינו בהעלאות והתקשרות בעומק אחר עומק ומזה הלך וקרב אל ה' בעילוי אחר עילוי כו' כמ\"ש בזהר בענין הלוך ונסוע הנגבה<sup data-n=\"3536\">366</sup> שהלך מדרגא לדרגא כו', וזהו ע\"י בחי' הפשטת והעתקת הנפש מהגוף להדבק למעלה באלקים חיים ולכך נק' בשם הר כו'. ואבות סימן לבנים<sup data-n=\"3537\">367</sup> שנטוע ומושרש בכאו\"א מישראל בירושה מאבות בחי' אהבה זו לצאת מחומר הגופני ולעלות ולידבק באלקים חיים בעילוי אחר עילוי כרוח האדם כו'.\n<b>אך</b> הנה כ' מי יעלה בהר ה'<sup data-n=\"3538\">368</sup> כו' נקי כפים ובר לבב<sup data-n=\"3539\">369</sup> כו', פי' הר ה'<sup data-n=\"3540\">370</sup> הוא בחי' אהבה האלקי' שמעלה ומגביה את הנפש למעלה מעלה כו' שזהו כמו שעולה בהר ה'<sup data-n=\"3541\">371</sup> כו' וכמו שהעולה בהר שהולך ועולה מלמטה למעלה בגובה ההר עד שמגיע לראש ההר שכל רגע הולך ומתעלה וא\"א לו לעמוד כו', כך<sup data-n=\"3542\">372</sup> או' מי יעלה בהר ה' נקי כפים ובר לבב דוקא, נקי כפים בפו\"מ בסומ\"ר בכלל ובפרט מן הגזל ושפ\"ד שא\"א שיעלה באהבה וקירוב אל ה' וידיו דמים מלאו<sup data-n=\"3543\">373</sup> כמ\"ש ובפרשכם כפיכם<sup data-n=\"3544\">374</sup> אעלים עיני מכם כו', ובר לבב<sup data-n=\"3545\">*375</sup> נקי וטהור מכל לכלוך וטומאה שאין בלבו שום תערובות רצונות זרות רק לה' לבדו ונק' לב א' לאביו שבשמים<sup data-n=\"3546\">375</sup>, שאם אינו בר לבב כו'<sup data-n=\"3547\">376</sup> קשור [לבו] לדבר זר איך יעלה באהבה אל הוי' הרי אמר כי קצר המצע מהשתרע<sup data-n=\"3548\">377</sup>. וזהו אשר לא נשא<sup data-n=\"3549\">378</sup> לשוא נפשו לשוא הוא<sup data-n=\"3550\">379</sup> אשר לא נמשך רצונו ונפשו לשום דבר זר שנק' שוא כלל, הוא יעלה בהר ה' [ב]הילוך התפעלות האהבה אלקי' הנ\"ל, אבל מי שנשא והמשיך כל נפשו לשוא לא יוכל לעלות בהר ה' כלל, ואם לפעמים יגבור בלבו התפעלות האה' אלקי' הנ\"ל<sup data-n=\"3551\">380</sup> ויעלה בהר הוי' בודאי יפול לאחור כי מי שלא יוכל לעלות בגובה ההר בהכרח שיפול למטה [שא\"א לו לעמוד בהר ונפילה זו הוא מן הגובה לעומק שתורידנה למטה] מטה ביותר כמו נופל מגג לארץ שנפילתו למטה יותר, וכך בעלותו בהר כש[מ]גיע לגובה ההר יותר כשיפול משם יותר<sup data-n=\"3552\">381</sup> יותר תהי' נפילתו בתחתית ההר כידוע וד\"ל. ועוד נפרש אשר לא נשא לשוא נפשו גם במי שלא נמשך אחר תאוות ורצונות זרות שזהו אשר אמר ובר לבב מכל סיג, אך מ\"מ יש אשר נשא לשוא נפשו ולא לשוא דקליפות אלא הכוונה לשוא ולחנם טרח ויגע לשאת נפשו בהעלותו בהר ה'",[["3535","365","<b>אברהם. . רחימא דמלכא</b>: נסמן לעיל סב, א."],["3536","366","<b>הלוך ונסוע הנגבה</b>: לך יב, ט. ראה זהר שם פ, א. פד, א."],["3537","367","<b>ואבות סימן לבנים</b>: ראה ב\"ר פ\"מ, ו. הנסמן ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300251123\" data-slug=\"likkutei-sichot\" data-id=\"1300251123\">לקו\"ש תולדות (כרך כה) ע' 123</a>."],["3538","368","<b>מי יעלה בהר ה'</b>: תהלים כד, ג."],["3539","369","<b>נקי כפים ובר לבב</b>: תהלים שם, ד."],["3540","370","<b>ה'</b>: בד: ליתא."],["3541","371","<b>ה'</b>: ניתוסף ע\"פ: ט."],["3542","372","<b>כך</b>: גט: אך."],["3543","373","<b>וידיו דמים מלאו</b>: ע\"פ סיום הכתוב שבהערה הבאה."],["3544","374","<b>ובפרשכם כפיכם</b>: ישעי' א, טו."],["3545","*375","<b>ובר לבב</b>: ראה גם מאמרי אדה\"א ויקרא ח\"ב ר\"ע תקנב. הנחות תקע\"ז ע' רסט. וש\"נ."],["3546","375","<b>לב א' לאביו שבשמים</b>: ברכות נז, א."],["3547","376","<b>כו'</b>: בד: כי."],["3548","377","<b>כי </b>[ט: ליתא]<b> קצר המצע מהשתרע [ט</b>: כו']: ראה גם לעיל פ' שמות לח, א. וש\"נ."],["3549","378","<b>אשר לא נשא</b>: המשך הכתוב נקי כפים ובר לבב."],["3550","379","<b>לשוא הוא</b>: טי: שזהו."],["3551","380","<b>הנ\"ל. . לו</b>: ניתוסף ע\"פ: ט."],["3552","381","<b>יותר</b>: בד: ליתא."]]],[2300540594,"בהתפעלות אהבה האלקי' הנ\"ל. והוא כאשר אין הכוונה שלימה בהתפעלות זו לה' בלבד אלא כוונתו להשלים נפשו בשלימות מעלת הדביקות שיגיע למדריגת צדיק וחסיד [או] שישמח<sup data-n=\"3553\">382</sup> לבבו בהגיע לזה ולעצמו הוא מתכוין, ואין בלבו כוונה האמיתי' שהוא רק לדבקה בו ית' בלבד כמ\"ש לאהבה את ה' כי הוא חייך<sup data-n=\"3554\">383</sup> ממש והוא עיקר המכוון<sup data-n=\"3555\">384</sup> מקור כל חיי העולמות כו' וכה\"ג, א\"כ ה\"ז עד\"מ כמו הצמא למים ואינו חפץ במים כלל רק חפץ להיות <span data-k=\"pg\">228</span> ּ בצמאון שבודאי אין זה צמאון כלל וכך הוא עיקר הדביקות לדבקה בו ית' כמ\"ש ואתם הדבקים בה'<sup data-n=\"3556\">385</sup> כו', אבל אם אינו חפץ רק בצמאון ודביקות מצד התפעלות לעצמו ולא לדבק[ה] בה' א\"ז אהבה וצמאון ודביקות כלל וכאוהב דבר מה שאינו מתכוין להתפעלות אהבה רק לדבק בדבר האהוב, וז\"ש אשר לא נשא לשוא נפשו ולחנם<sup data-n=\"3557\">386</sup> בהתפעלות אהבה זו כנ\"ל דהיינו שכוונתו בתמימות רק לדבקה בו ית' בלבד בלי שום תערובות עצמו כלל כנ\"ל והוא ישא ברכה<sup data-n=\"3558\">387</sup> כו' בח\"י ברכות דשמו\"ע שנק'<sup data-n=\"3559\">389</sup> סולם<sup data-n=\"3560\">388</sup> כו', אבל אם נושא נפשו באהבה זו בתערובות רע<sup data-n=\"3561\">390</sup> ולגרמי' ודאי יפול מגובה ההר ולשוא נשא נפשו.\n<b>והנה</b> אהרן שודמ\"ט יש בכחו להמשיך התעוררו' אהבה בלב כאו\"א מישראל שיוכל לעלות בהר ה' כו' שילך הלוך ויעלה בדביקות והתלהבות הנפש בעילוי אחר עילוי כמ\"ש בהעלותך את הנרות כו', והוא ענין תי' הר שבשם אהרן ונו\"ן פשוטה שנמשכת מלמעלה למטה עד הניצוץ היותר קטן שביש[ראל]. והטעם הוא לפי [ש]שורש בחי' ומדרג' אהרן כה\"ג למעלה הוא בבחי' רב חסד<sup data-n=\"3562\">391</sup> דא\"א שהוא בחי' אה\"ר העליונה שלמעלה מן החכ' [כמו שאו' אה\"ר אהבתנו אהבת עולם<sup data-n=\"3563\">392</sup> אהבתנו כו', והוא למעלה הרבה מאהבה זו שנק' הר הוי' שנמשכה מן החכמה] ו[ה]טעם ע\"כ בכחה לעורר ולהמשיך התפעלות זאת דא\"ז<sup data-n=\"3564\">393</sup> ממילא, כענין משכני אחריך נרוצה<sup data-n=\"3565\">394</sup> פי' משכני בחבלי עבותות אה\"ר מלמעלה וממילא אחריך נרוצה לעלות בהר ה'.\n<b>וביאור</b> הענין הנה ידוע עיקר ההפרש בין אה\"ר לאה\"ז דאה\"ר היא בהתעוררו' הרצון הפשוט ועצמי הבא מעצם הנפש ממש בלתי מורכב בטעם ושכל לרצון כלל אלא אהבה",[["3553","382","<b>שישמח</b>: גט: שיטיב."],["3554","383","<b>לאהבה. . חייך</b>: נצבים ל, כ [בדילוג]."],["3555","384","<b>עיקר המכוון</b>: ט: ליתא."],["3556","385","<b>ואתם הדבקים בה'</b>: ואתחנן ד, ד."],["3557","386","<b>נפשו ולחנם</b>: ט: ולחנם נפשו."],["3558","387","<b>ישא ברכה</b>: תהלים כד, ה."],["3559","389","<b>שנק' סולם</b>: ניתוסף ע\"פ: ט."],["3560","388","<b>דשמו\"ע שנק' סולם</b>: ראה זח\"א (רע\"מ בהשמטות) רסו, ב. ח\"ג (תוספת) שו, ב. ת\"ז תמ\"ה (פג, א)."],["3561","390","<b>רע</b>: ניתוסף ע\"פ: ט."],["3562","391","<b>אהרן כה\"ג. . רב חסד</b>: ראה לקמן פ' בשלח קמא, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תצ. וש\"נ. במדבר ח\"ד ע' א'שיט. וש\"נ."],["3563","392","<b>אה\"ר. . אהבת עולם</b>: ברכת ק\"ש שחרית (נוסח אשכנז וספרד)."],["3564","393","<b>דא\"ז</b>: בד: דאהבה זוטא."],["3565","394","<b>משכני אחריך נרוצה</b>: שה\"ש א, ד."]]],[2300540609,"שברצון ותענוג עצמי למעלה מן הטעם ודעת לגמרי ונק' אה\"ר בתענוגי' כידוע, והוא אות א' דאהרן אותיות פלא<sup data-n=\"3566\">395</sup> שמופלא ומובדל מן השכל וטעם לגמרי כו'. ואהבה זוטא היא האהבה שנולדה מן השכל והתבוננו' אלקות בטוב טעם ודעת כל חד לפוש\"ד<sup data-n=\"3567\">396</sup> בבחי' חו\"ב שבנשמה כו' שיכלה כחה מיד בכלות התפעלות השכל וההשגה כידוע, אבל בחי' אה\"ר הנ\"ל לא תתבטל ולא יכלה כחה לעולם להיותה באה מעצם הרצון שבלתי מורכב בדבר מה כו' שכל עצם אינו משתנה<sup data-n=\"3568\">397</sup> כלל. וזהו ענין הר ההר<sup data-n=\"3569\">398</sup> הר ע\"ג הר עד\"מ הר הגשמי שהוא צומח שבדומם, אבל לגבי הר העליון גם הוא כדומם יחשב לפי שהוא נק' שטח ומישור לגבי הר העליון שעלי', כך גם העולה בהר ה' באה\"ז הנ\"ל עדיין נק' [בחי'] דומם עפר לגבי בחי' אה\"ר הנ\"ל שהיא למעלה הרבה מובדלת מן התפעלות השכל מפני שצריך לעלות אלי' בביטול ההשגה והטעם לגמרי כאלו לא נתפעל כלום מצד הטעם כו', ע\"ד דוגמא<sup data-n=\"3570\">399</sup> כאשר אדם חפץ בדבר מה מצד טעם שיש לו יבוטל הרצון שמצד הטעם כשבא לכלל רצון ואה\"ר בלא טעם כלל כו'. וכמו נשמות בג\"ע הגם שנהנין<sup data-n=\"3571\">400</sup> מזיו השכינה בטעם והשגה כשבאים ועולים לפני ה' ממש בהשתחווא' וביטול עצמי מביטול<sup data-n=\"3572\">401</sup> כל התפעלות השכל והשגה הראשונה כענין מה פשפשת<sup data-n=\"3573\">402</sup> כו', כאדם<sup data-n=\"3574\">403</sup> שרוצה ליכנס אל המלך שיש בו ביטול מצד הטעם אך כאשר בא לפני המלך שבטל בעצם בלא טעם הרי נעשה כאבן דומם ממש כו' וד\"ל. וזהו שאמר אברהם אוהבי ורחימא דמלכא ואנכי עפר ואפר<sup data-n=\"3575\">404</sup> כו' שנעשה התפעלות אה' שלו בטעם והשגה בבחי' דומם עפר ממש בהגיעו לבחי' אה\"ר בחי' רב חסד הנ\"ל. ולכך ציוה ה' שיאסף אהרן אל עמיו בה\"ר הה\"ר<sup data-n=\"3576\">405</sup> דוקא <span data-k=\"pg\">קיד</span> ּ לפי שזהו עצם שרש מדרגתו למעלה (בבחי' רב חסד דא\"א ד[בי'] אחיד אבא<sup data-n=\"3577\">406</sup> כו'). ואמנם מבחי' אה\"ר הנ\"ל נמשך ומתאחד בהתלבשות בחכ' שהוא בחי' כח מ\"ה<sup data-n=\"3578\">407</sup> וכמ\"ש והחכ' מאין תמצא<sup data-n=\"3579\">408</sup> מאין העצמי דרצון הפשוט נמשך לבחי' יש להיות בחי' הביטול בעצם [גם] בחכמה למעלה מן השגה וטעם כמו ונחנו מ\"ה<sup data-n=\"3580\">409</sup> בהעדר הרגשת עצמ[ו] לגמרי כו' שנק' ביטול היש עכ\"פ ומשם נמשך לבינה והשגה כידוע. וזהו פי' אות א' דאהרן כידוע דאות אל\"ף בהיפוך אותיות פלא<sup data-n=\"3581\">410</sup>, דפנימי' כ\"ע שהוא בחי' ביטול הרצון הפשוט ועצמי נק' פלא<sup data-n=\"3582\">*411</sup> נבדל ומופלא מן ביטול החכ', ואמנם כאשר נמשך ומתאחד ומתחבר בחכמה כח מ\"ה להיות ביטול היש לגמרי נק' אלף לשון",[["3566","395","<b>א'. . פלא</b>: נסמן לקמן הערה 410."],["3567","396","<b>כל חד לפוש\"ד</b>: נסמן לקמן בהערה 455."],["3568","397","<b>שכל עצם אינו משתנה</b>: ראה לקמן פ' בא צה, ב. קטז, ב. מאמרי אדה\"א שמות ח\"ב ע' תעד. וש\"נ. הנחות תקע\"ז ע' קטו. ש\"א נב, ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680230\" data-slug=\"torat-chaim\" data-id=\"2300680230\">תו\"ח וישב רא, ב</a> ובהערה 11."],["3569","398","<b>הר ההר</b>: חוקת כ, כב. ראה גם מאמרי אדה\"ז תקס\"ג כאן (ע' קכח). תקס\"ז ע' רה. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380400\" data-slug=\"likkutei-torah\" data-id=\"4001380400\">לקו\"ת נשא כג, סע\"א</a>. לקמן הערה 405."],["3570","399","<b>ע\"ד דוגמא. . כו'</b>: ניתוסף ע\"פ: גט."],["3571","400","<b>נשמות. . שנהנין</b>: נסמן לעיל נח, ב."],["3572","401","<b>מביטול</b>: ג: יבוטל. ד: מבוטל."],["3573","402","<b>מה פשפשת</b>: זהר בהקדמה א, ב."],["3574","403","<b>כאדם</b>: ט: וכמו אדם."],["3575","404","<b>ואנכי עפר ואפר</b>: וירא יח, כז."],["3576","405","<b>שיאסף אהרן. . הה\"ר</b>: חוקת כ, כג ואילך. ראה גם לקמן פ' פקודי תנב, א. מאמרי אדה\"ז תקס\"ז ע' קצו. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380392\" data-slug=\"likkutei-torah\" data-id=\"4001380392\">לקו\"ת נשא כא, א</a>. לעיל הערה 398."],["3577","406","<b>רב חסד. . אבא</b>: ראה ע\"ח (שער או\"א) שי\"ד, פ\"א."],["3578","407","<b>בחכ'. . כח מ\"ה</b>: זהר (רע\"מ) צו כח, א. לד, א."],["3579","408","<b>והחכ' מאין תמצא</b>: איוב כח, יב."],["3580","409","<b>ונחנו מה</b>: נסמן לעיל פ' שמות מג, א."],["3581","410","<b>אל\"ף בהיפוך אותיות פלא</b>: ראה ת\"ז ת\"ע (קלה, א). הקדמת הראב\"ד לס\"י נתיב הא'."],["3582","*411","<b>כ\"ע. . פלא</b>: ראה תיקונים לז\"ח צח, ד."]]],[2300540623,"אולפנא<sup data-n=\"3583\">411</sup> ולימוד כמו והחכ' מאין תמצא מאין העצמי דכתר [תמצא] מן ההעלם לגילוי להיות בביטול והעדר הרגשת עצמ[ו] וזהו א' דאהרן וד\"ל.\n<b>וזהו</b> סדר אותיות שם אהרן בתחלה אות הא' שהוא בחי' הירידה והמשכה מהעלם אור הרצון העצמי' להאיר בחכ' כו', ואמנם גם החכ' הרי היא בבחי' העלם ואין למעלה מן השגת השכל רק הוא [כמו] טעם כמוס לרצון וע\"כ מוליד אה\"ר ברצון ותענוג שבאה מן עצם הרצון כו' והוא תי' ה\"ר שבאהרן שהוא בחי' הר ההר, ומבחי' הר ההר הזה נמשך תולדות<sup data-n=\"3584\">412</sup> אה\"ז הנ\"ל ע\"י הארת והמשכת [ה]חכ' בבינה והשגת השכל וטעם. ונמצא שתי' הר שבאהרן ה[וא] אה\"ר המקור לכל תולדות אה\"ז מן השכל והשגה כמו הר ע\"ג הר ואז נק' הר ה' [כש]נמשך להשגה ושכל<sup data-n=\"3585\">413</sup> וטעם ומוליד אה\"ר בלב כו'. ואמנם כדי שיומשך למטה בכללות נש\"י עד הקטן שבישראל הו\"ע הנו\"ן פשוטה שבסוף תי' אהרן שיוכל כאו\"א לעלות בהר ה', והוא מה שיתעורר כל אדם בהתפעלות אהבה האלקי' שנולדה מן השכל אף לעורר גם להיותר תחתון בתשובה שלימה כענין ב\"ק מכרזת בכ\"י שובו בנים<sup data-n=\"3586\">414</sup> כו', וקול זה המעורר לב כ\"א גם להרשעים וקלי עולם הכל הוא מבחי' רב חסד העליון שבבחי' אה\"ר העליונה עד\"מ אב שמושך לבנו באה\"ר שמגלה לו עד שיומשך לבו אליו בהתפעלות גדולה כו' וכמו השיבנו ה' אליך ונשובה<sup data-n=\"3587\">415</sup> כידוע, והוא ענין הנו\"ן פשוטה שהולך ונמשך למטה ביותר עד נשמות היותר נמוכות הנק' עקביים כידוע שכנס\"י הם בציור קומת האדם<sup data-n=\"3588\">416</sup> יש נשמות שנק' ראשי אלפי ישראל כו' עד נשמות שנק' עקביים<sup data-n=\"3589\">417</sup> ובכללות הקומה הוא דור האחרון הזה שנק' עקבות משיחא<sup data-n=\"3590\">418</sup>, ומפני שצריך שיגיע אור המשכה דאה\"ר העליונה מרב חסד שבעצמות א\"ס ב\"ה גם בנשמות דעקביים עד שיחזור בתשובה גם לרשעים גמורים שהן בעומק רע דשאול תחתית כענין וימינך פשוטה<sup data-n=\"3591\">419</sup> כו'. וזהו ענין הנו\"ן פשוטה דאהרן כי אהרן הוא מז' רועים כידוע וענין הפרנסה שמפרנס לכללות נש\"י מראש לרגל שבהם הוא לעוררם באהבה ותשוקה מטעם הנ\"ל וד\"ל.\n<b>וזהו</b> הוא אהרן ומשה כו' הזכיר אהרן בתחלה ואח\"כ משה, והנה בתחלה צריך שיומשך בכנ\"י מלמעלה למטה חכ' ועוז שיומשך לי[ב]ם בהתפעלות אה' ותשו[בה] שיוכלו לעלות בהר ה' כנ\"ל שזהו בא מכח אה\"ר העליונה בחי' אהר\"ן כה\"ר<sup data-n=\"3592\">420</sup> כנ\"ל ע\"כ הזכיר אהרן בתחלה ואח\"כ משה, לפי שמדבר בענין יצ\"מ כמ\"ש אשר אמר ה' להם הוציאו את בנ\"י ממצרים, <span data-k=\"pg\">230</span> ּ וידוע",[["3583","411","<b>אלף לשון אולפנא</b>: ראה מאמרי אדה\"א דברים ח\"ג ע' א'כו. וש\"נ. נ\"ך ע' קעג. לקמן פ' בשלח רמו, ד."],["3584","412","<b>תולדות</b>: ניתוסף ע\"פ: גט."],["3585","413","<b>ושכל</b>: בד: ליתא."],["3586","414","<b>ב\"ק. . שובו בנים</b>: ירמי' ג, יד. כב. ראה זהר נשא קכו, א. מאמרי אדה\"א ויקרא ח\"א ע' ט. בראשית ע' שמב. הנחות תקע\"ז ע' ק ובהנסמן בהנ\"ל."],["3587","415","<b>השיבנו ה' אליך ונשובה</b>: איכה ה, כא."],["3588","416","<b>שכנס\"י. . האדם</b>: נסמן לעיל פ' שמות מה, ד."],["3589","417","<b>נשמות שנק' ראשי אלפי ישראל. . עקביים</b>: ראה תניא פ\"ב."],["3590","418","<b>דור האחרון. . עקבות משיחא</b>: נסמן לעיל ל, א."],["3591","419","<b>וימינך </b>[ד: ימינך]<b> פשוטה</b>: ראה גם לעיל עב, ב. וש\"נ."],["3592","420","<b>כה\"ר</b>: בד: א' הר."]]],[2300540637,"ענין יצ\"מ שהוא התחלת ההתעוררות לצאת מן המיצר וצמצום דחושך דקליפה וסט\"א מנש\"ט כו' כמו היוצא מבית האסורים ממש כו', והוא ענין התעוררות תשו' שנמשך כח ועוז זה מלמעלה שהוא ע\"י המשכת אה\"ר רב חסד העליון דוקא שזהו נו\"ן פשוטה דאהרן כו'. וע\"כ אמר הוא אהרן ומשה<sup data-n=\"3593\">421</sup> שנק' שודמ\"ט כו'<sup data-n=\"3594\">422</sup> להוציאם ממצרים, והן כמו ברכות הנ\"ל<sup data-n=\"3595\">423</sup> עד ב\"ש שעז\"א מי זאת עולה מן המדבר כו' ואח\"כ הודו לה' כו' שהוא התחלת ההודאה כשיוצא מחושך לאור, וזהו כמו שמתחיל אדם לעלות בהר ה' שאמ' מי יעלה בהר ה' נקי כפים וכו' עד שהולך ועולה בהתפעלות אהבה האלקי' בפסוד\"ז עד ק\"ש בפ' ואהבת שאז עלתה הנשמה האלקי' בהר ה' ע\"י אהרן שודמ\"ט באהבה שנולדה מן השגה והתבוננו' דיחו\"ע דשמע ישראל כו' ואח\"כ משה שוש' דמל[כא] במצות ת\"ת במ\"ש והיו הדברים כו' כמשי\"ת וד\"ל. וזהו [הוא] אהרן ואח\"כ משה אשר אמר [ה'] להם הוציאו כו', פי' לצאת ממצרים ולעלות בהר ה' אמר [ה'] לאהרן תחלה ואח\"כ למשה<sup data-n=\"3596\">424</sup> שיאמר לזקני ישראל, וכמו שמצינו של[גבי] זקני ישראל הי' [אהרן] עיקר המדבר ולגבי פרעה הי' משה עיקר המדבר וכמ\"ש הם המדברים אל פרעה הוא מש\"ה ואהר\"ן משה תחלה ואח\"כ אהרן (וכמשי\"ת הטעם בסמוך).\n<b>אך</b> עדיין י\"ל מ\"ש הוציאו את ב\"י<sup data-n=\"3597\">425</sup> על צבאותם מהו לשון על צבאותם למעלה מצבאותם הלא הם נק' צבאות הוי' כמ\"ש בעצם היום הזה הוציאו<sup data-n=\"3598\">426</sup> כל צבאות הוי' כו'. אך הענין הוא דע\"י העלאה זאת לב\"י ע\"י אהרן שודמ\"ט באמצעות המשכ' בחי' אה\"ר העליונה שלמעלה מן החכ' הוא שהעלם והביאם למעלה מעלה מבחי' המספר והתחלקות דצבאותם, והוא שהעלם והביאם לדבק בעצמות ה'<sup data-n=\"3599\">427</sup> א\"ס ב\"ה ממש שלמעלה מעלה מבחי' מקור התחלקות מספר צבאות שהן ס' רבוא שנמשכין מבחי' ו\"ק העליוני' דאצי' שהן [ששה] מדות דאצי' חג\"ת נה\"י<sup data-n=\"3600\">428</sup> כו' וכמ\"ש לך ה'<sup data-n=\"3601\">429</sup> הגדולה והגבו' וכמ\"ש לע\"ל והי' מספר בנ\"י כחול הים אשר לא ימד<sup data-n=\"3602\">430</sup> כו', וזהו מ\"ש על צבאותם למעלה מבחי' צבאות ה' הבאים במספר והתחלקות ס\"ר כו' וד\"ל. ולהבין זה הנה כתיב קק\"ק ה' צבאות<sup data-n=\"3603\">431</sup> כו', ג\"פ קדוש הן ג' מיני צמצוצי<sup data-n=\"3604\">432</sup>' [ב]בחי' קדוש שהוא בחי' ההעלם והפלאת הערך כמו צמצום הא' מכ[\"תר] לחו\"ב והוא בחי' צמצום הרצון ותענוג שלמעלה מן השכל וטעם, וצמצום הב' מחו\"ב למדות חג\"ת, והג' ממדות למחו\"ד זהו קדוש הג' להיות הוי' צבאות שהוא אור השפע הנמשך לעלמין סתימין ואתגליין שמתהוים מבחי' מחו\"ד והן נש\"י<sup data-n=\"3605\">433</sup>, רק שהנשמות נק' צבאות הוי' וכמו ס\"ר נש\"י שהיו ביצ\"מ<sup data-n=\"3606\">434</sup> נק' צבאות הוי' אבל מלאכים דבריא' או' קדוש הוי'",[["3593","421","<b>ומשה</b>: בגד: כו'."],["3594","422","<b>כו'</b>: גט: שצוה לו ה'."],["3595","423","<b>הנ\"ל</b>: בד: השחר."],["3596","424","<b>ואח\"כ למשה</b>: בד: ליתא."],["3597","425","<b>הוציאו את ב\"י</b>: המשך הכתוב הוא אהרן ומשה."],["3598","426","<b>בעצם היום הזה הוציאו </b>[בד: יצאו]: בא יב, מא."],["3599","427","<b>ה'</b>: בד: ליתא."],["3600","428","<b>נה\"י</b>: בד: ליתא."],["3601","429","<b>לך ה'</b>: דהי\"א כט, יא."],["3602","430","<b>והי' מספר. . לא ימד </b>[ט: ליתא]: הושע ב, א."],["3603","431","<b>קק\"ק ה' צבאות</b>: ישעי' ו, ג. ראה גם הנסמן לעיל נח, ב."],["3604","432","<b>ג\"פ. . צמצומי</b>: ניתוסף ע\"פ: גט. — תיבת מיני ליתא בג."],["3605","433","<b>נש\"י</b>: גט: נשמות ומלאכי'."],["3606","434","<b>ס\"ר. . ביצ\"מ</b>: בא יב, לז."]]],[2300540649,"צבאות דהיינו שהוא קדוש ומובדל מהם להיות שרשם רק מבחי' שם אלקים<sup data-n=\"3607\">435</sup> כידוע וד\"ל. ועז\"א לכו חזו מפעלות אלקים דוקא אשר שם שמות בארץ<sup data-n=\"3608\">436</sup> כו' הוא מבחי'<sup data-n=\"3609\">437</sup> התחלקות הצירופי אותיות דמחו\"ד שנחלקים מהששה מדות חג\"ת נה\"י דז\"א, שכל מדה נחלקת ליו\"ד ויו\"ד לק' וק' לאלף ואלף לרבוא שהן ס\"ר או ת\"ר אלף והן מספר בנ\"י בצבאותם ובכללות נק' צבאות הוי'. והיינו כדוגמא של ד' מחנות שכינה<sup data-n=\"3610\">438</sup> למעלה במלאכים שיש בחי' שם מיוחד בכל מחנה דד' מחנות כמו דגל מחנה ראובן למט' בסט' דדרום הוא למעלה בבחי' מחנה מיכאל<sup data-n=\"3611\">439</sup> וכמ\"ש בזהר פ' פקודי<sup data-n=\"3612\">440</sup> שס\"ר <span data-k=\"pg\">קטו</span> ּ נש\"י הוא מספר מכוון בסדר הדגלים בדוגמא ד' מחנות שכינה למעלה ממש. וזהו תפקדו אותם לצבאותם<sup data-n=\"3613\">441</sup> לפי בחי' מספר השמות שבמחנה שכינה למעלה שמ[ת]חלקים בהתחלקות לס\"ר כמו שמקבלים מבחי' המדות דאצי' שם<sup data-n=\"3614\">442</sup> הוי' שבכל ספי' וע\"כ [נק'] צבאות הוי' (וכמ\"ש ששם עלו שבטים<sup data-n=\"3615\">443</sup> שבטי י\"ה דהיינו ו\"ק דדכורא שהן י\"ב ג\"א<sup data-n=\"3616\">444</sup> כו'). אך הנה כאן אמר הוציאו את ב\"י על צבאותם למעלה ממספר צבאות[ם] הבא בהתחלקות מו\"ק דאצי', והוא לפי שע\"י בחי' המשכה דאה\"ר העליונה העלם [ל]בחי' עצמות המאציל כמו שהוא למעלה מצמצום ק[דוש] הא' שהוא צמצום העצמו' ברצון שנמשך בחו\"ב כו'. ולכך א' במה דקשה רישא לסיפא והי' מספר כו' אשר לא ימד כו' כאן כשישראל עושי' רש\"מ<sup data-n=\"3617\">445</sup>, פי' שרצונו ש\"מ [במצות] הוא בחי' פנימי' הכ[ת\"ר] שלמעלה גם מבחי' שורש המדות דחו\"ב שמקבלים מרצון הנק' כ[ת\"ר]<sup data-n=\"3618\">446</sup> ע\"כ שם הוא למעלה מבחי' המספר והתחלקות המסתעפי' מהמדות לגמרי (כי רק<sup data-n=\"3619\">447</sup> מה שמאיר מכ' [ש]הוא הרצון לחכמה הוא רק חיצוני' הכתר והן מדות שבכ[ת\"ר], אבל פנימי' הכלי<sup data-n=\"3620\">448</sup> שלמעלה גם מחכ' שבכ' שם הוא למעלה גם ממדות שבכ[ת\"ר]). ולפי\"ז ה\"ז בחי' ומדרגה שלמעלה גם מאות א' דאהרן שהוא הארת הכת\"ר בחכמה כנ\"ל שזהו רק להמשיך בחי' אה\"ז שיעלו בהר ה' כנ\"ל, אבל על צבאות הוי' בחי'<sup data-n=\"3621\">449</sup> פלא דפנימי' הכתר להיות[ו] מדבר ברצה\"ע<sup data-n=\"3622\">450</sup> שהוא בתו'<sup data-n=\"3623\">451</sup> העלאה והתכללות למעלה ממש שזהו בחי' או\"ח היפוך או\"י דא' וד\"ל, וזהו הוציאו את ב\"י על צבאותם",[["3607","435","<b>מלאכים. . שם אלקים</b>: ראה אגה\"ת פ\"ד. מאמרי אדה\"א ויקרא ח\"א ע' ט־ בראשית ע' קכא ובהנסמן שם."],["3608","436","<b>בארץ</b>: בדט: ליתא. ג: כבפנים. בגדט: ניתוסף: א\"ת שמות כו' [גט: ליתא] אלא שמות [בד: ליתא]. ברכות ז, ב."],["3609","437","<b>הוא מבחי'</b>: גט: והוא ענין ריבוי."],["3610","438","<b>ד' מחנות שכינה</b>: זהר במדבר קיח, ב."],["3611","439","<b>דגל מחנה ראובן. . דדרום. . מיכאל</b>: נסמן לעיל סו, ב."],["3612","440","<b>בזהר פ' פקודי</b>: נסמן לעיל פ' שמות א, ב."],["3613","441","<b>תפקדו אותם לצבאותם</b>: במדבר א, ג."],["3614","442","<b>שם</b>: ג: ובשם."],["3615","443","<b>ששם עלו שבטים. . דדכורא</b>: תהלים קכב, ד. נסמן לקמן פ' בא קכז, ד."],["3616","444","<b>ו\"ק. . י\"ב ג\"א</b>: ראה מאמרי אדה\"א שמות ח\"א ע' קסט. וש\"נ."],["3617","445","<b>כאן כשישראל עושי' רש\"מ</b>: יומא כב, ב."],["3618","446","<b>מרצון הנק' כ[ת\"ר]</b>: ראה פרדס (שער עצמות וכלים) שער ד', פ\"ח. (שער הצחצחות) שי\"א, פ\"ה. פ\"ו. אגה\"ק סכ\"ט. הנסמן במאמרי אדה\"א הנחות תקע\"ז ע' עב."],["3619","447","<b>רק</b>: בד: ליתא."],["3620","448","<b>הכלי</b>: בד: הכת\"ר."],["3621","449","<b>בחי'</b>: ט: הוא בבחי'."],["3622","450","<b>ברצה\"ע</b>: גט: ביצי\"מ."],["3623","451","<b>בתו'</b>: בד: בבחי'."]]],[2300540661,"למעלה מבחי' צבאות הוי' דחכ' ומדות דאצי' (גם למעלה ממדות דבכתר דחכ')<sup data-n=\"3624\">452</sup>.\n<b>והנה</b> יובן כ\"ז בעבודת ה' במה שא' ואהבת את הוי' אלקיך בכל לבבך ובכל נפשך ובכל מאדך, דהנה ידוע מ\"ש תוכן רוחות ותוכן לבות<sup data-n=\"3625\">453</sup> [ש]הרוח הוא רוח חכמה ובינה שבמוח שיש לכאו\"א אופן מדרגתו בשכלו והשגה שבשכל<sup data-n=\"3626\">454</sup> והשגה אלקית להשיג ולהכיר את בוראו כחו\"ח לפוש\"ד<sup data-n=\"3627\">455</sup> דוקא כמ\"ש בזהר, וז\"ש נודע בשערים בעלה<sup data-n=\"3628\">456</sup> בענין תרעין עילאין<sup data-n=\"3629\">457</sup> שהן חמשים שע\"ב<sup data-n=\"3630\">458</sup> ונק' שער [ע]\"ש לשון שיעור דמשער בשכלו והשגתו דוקא והוא לפי אופן מדריגת שרש נשמתו למעלה וכ\"א יש לו שכל והשגה מיוחד[ת] נבדל משכל והשגת זולתו, וכמו שאנו רואים בחוש<sup data-n=\"3631\">459</sup> שיש שכל שמתפעל משכל והשגה [אלקי'] זה דוקא וזה יתפעל מהשגת שכל אחר לפי שאין כל הדיעות שוות<sup data-n=\"3632\">460</sup> להיות שיש לכ\"א מדריג' שלו בפ\"ע וזהו תוכן רוחות ה', כי נו\"ר<sup data-n=\"3633\">461</sup> חלק אלוה<sup data-n=\"3634\">462</sup> הוא כמ\"ש נשמת שדי תבינם<sup data-n=\"3635\">463</sup> וכ' אכן רוח הוא באנוש<sup data-n=\"3636\">464</sup>, כי רוח האדם העולה למעלה<sup data-n=\"3637\">465</sup>, וכמו במ\"ת שהי' ס' רבוא<sup data-n=\"3638\">466</sup> מיני דיעות והשגות באלקות, לפי שכללו[תם הוא] ע' נפש דיעקב<sup data-n=\"3639\">467</sup> שמתחלקים לס\"ר ע\"י [התחלקות ה]מדות כנ\"ל בענין צבאות הוי' כו' וע\"כ מ\"ש<sup data-n=\"3640\">468</sup> ס\"ר מיני דיעות והשגות לפי מספר [ההתחלקות] דס\"ר ניצוצי' ומס\"ר הללו מסתעפים ענפים פרטים בכל דור ודור עד שיש לכ\"א מישראל דעת והשגה לפום שעו\"ד כו'. וזהו נודע בשערים<sup data-n=\"3641\">469</sup> באינון שיעורין כו' ששרשן הכללי הוא בנון שערי בינה אם הבנים<sup data-n=\"3642\">470</sup> והיא ה\"א עילאה דש' הוי'<sup data-n=\"3643\">471</sup> וכו' והיינו נודע בשערים בעלה דכנ\"י שהוא בחי' ז\"א דאצי' שמקבל מוחין דח\"ס באינון<sup data-n=\"3644\">472</sup> תרעין עילאין דהיינו נש\"ב דאצי' כידוע וד\"ל. <span data-k=\"pg\">232</span> ּ ועד\"ז נמשך ממוחין דחב\"ד למדות שבלב וז\"ש תוכן לבות ה' שמתפעל הלב באוי\"ר שמצד התבוננות ממש לפי אופן התפעלות השכל והשגה שבמוח בכאו\"א לפי מדריגת שרש<sup data-n=\"3645\">473</sup> נשמתו ורוחו כמו אם ישים אליו לבו רוחו ונשמתו אליו יאסוף<sup data-n=\"3646\">474</sup> כו', וז\"ש בזהר בפי' בשערים בכל חד וחד לפום מה דמשער בלבי' שלפי [אופן] כלי השגתו במוח בינה",[["3624","452","<b>(גם. . דחכ')</b>: ניתוסף ע\"פ: גט."],["3625","453","<b>תוכן רוחות ותוכן לבות</b>: בד: תוכן לבות ותוכן רוחות — משלי כא, ב. טז, ב."],["3626","454","<b>בשכלו והשגה שבשכל</b>: בד: בשכל."],["3627","455","<b>כחו\"ח לפוש\"ד</b>: ראה הקדמת התניא ע\"פ הזהר וירא קג, ב."],["3628","456","<b>נודע בשערים בעלה</b>: משלי לא, כג."],["3629","457","<b>בענין </b>[בד: באינון]<b> תרעין עילאין</b>: ראה זהר שם [ושם דרגין. וראה זהר פינחס רנג, ב (עה\"פ שאו שערים) תרעין]. לקמן פ' בא קיז, ג."],["3630","458","<b>חמשים שע\"ב</b>: ר\"ה כא, ב."],["3631","459","<b>בחוש</b>: ניתוסף ע\"פ: ט."],["3632","460","<b>שאין כל הדיעות שוות</b>: ראה ברכות נח, א (ובדק\"ס שם). תניא בהקדמה."],["3633","461","<b>נו\"ר</b>: ט: נשמה ורוח."],["3634","462","<b>נו\"ר חלק אלוה</b>: נסמן לעיל נא, ד."],["3635","463","<b>נשמת שדי תבינם</b>: איוב לב, ח [ושם: ונשמת — ראה לקמן פ' תצוה שמט, ג הערה 250. שה\"א ע' מב. מאמרי אדה\"א נ\"ך ע' שכ. וש\"נ]. ראה גם לקמן פ' ויקהל שצד, א."],["3636","464","<b>נשמת. . באנוש</b>: גט: אכן רוח כו' נשמת שדי תבינם וכתיב."],["3637","465","<b>כי רוח האדם העולה למעלה </b>[בד: כו']: קהלת ג, כא [ושם: מי יודע רוח בני האדם — ראה לקמן פ' בשלח קנד, ב. יתרו רנא, ג. פקודי תנח, ד. הנסמן במאמרי אדה\"א בראשית ע' שסד. ש\"א י, א. שע\"ת סא, ג ובהערה 33]."],["3638","466","<b>במ\"ת שהי' ס' רבוא</b>: ראה שבת פח, א. לעיל הערה 434."],["3639","467","<b>ע' נפש דיעקב</b>: ויגש מו, כז."],["3640","468","<b>מ\"ש</b>: גט: יש."],["3641","469","<b>בשערים</b>: בתו\"ח באים כאן התיבות: דכנ\"י. . דח\"ס שנמצא להלן בשו\"ה עילאה."],["3642","470","<b>בינה אם הבנים</b>: נסמן לעיל פ' שמות יז, א."],["3643","471","<b>בינה. . ה\"א עילאה דש' הוי'</b>: ראה ת\"ז בהקדמה ו, ב ובהנסמן בניצוצי זהר שם. הנסמן בתו\"ח ויצא קסז, ג הערה 38."],["3644","472","<b>דח\"ס באינון</b>: ג: דאבא מאינון. ט: דחב\"ד מאינון."],["3645","473","<b>שרש</b>: ניתוסף ע\"פ: גט."],["3646","474","<b>אם ישים. . יאסוף</b>: איוב לד, יד."]]],[2300540673,"כך הוא מתפעל ומשער בלבי' וכמ\"ש בינה ליבא<sup data-n=\"3647\">475</sup> כו', וכך אנו אומרים ותן בלבינו בינה להבין<sup data-n=\"3648\">476</sup> כו' דלב מבין<sup data-n=\"3649\">477</sup> והלב רואה<sup data-n=\"3650\">478</sup> ראיית עיני השכל שהיא החכ' ונק' עין השכל דבלבא<sup data-n=\"3651\">479</sup> כמ\"ש במ\"א. [ו]כל [זה] היינו ב' אהב[ות] דבכל לבבך ובכל נפשך פי' בכל נפשך לפ\"ע מדריגת נפש [ו]רוח של כאו\"א בשרש מדרגתו כך הוא מתפעל במוחו ולבו בכל לבו ובכל נפשו כו', אבל בחי' אה\"ר דבכל מאדך הוא למעלה מעלה הרבה מ[ערך] התפעלו' השכל והשגה שבמוח ולב לפי שהוא אה\"ר שבלתי מוגבלת כלל בכלי השכל וכלי הלב וע\"כ [נק'] מאד בלי גבול<sup data-n=\"3652\">480</sup>, ומאדך הוא למעלה מגדר הכלי שלך<sup data-n=\"3653\">481</sup> כידוע, והענין הוא שזהו התפעלות עצמיות הנפש ממש שהוא בפנימי' ועצם הרצון הפשוט שבלתי מתיישב ומורכב בשכל והשגה וטעם (אף לא בשכל וטעם כמוס לרצון להיותו למעלה גם מבחי' התפעלות רצון וכידוע ומבואר במ\"א שהתפעלות רצון יש בו שינוי וחילוף משעה לשעה כו', משא\"כ עצמיות הרצון<sup data-n=\"3654\">482</sup> ופנימי[ותו ו]נקודתו שהוא בעצם הנפש ממש לא ישונה לעולם) (ובאמת פי' ובכל נפשך כ\"ז רבוי לרבות התפעלות הרצון שלמעלה מן השכל כי הרצון נק' נפש<sup data-n=\"3655\">483</sup> כידוע ובכל מאדך היינו התפעלות עצמיות הנפש וכמו כל עצמותי תאמרנה<sup data-n=\"3656\">484</sup> וכו'). וזהו כמו ענין הנ\"ל בפי' על צבאותם למעלה מצבאות הוי' דבמו\"ד כ'<sup data-n=\"3657\">485</sup> ובאתעדל\"ת באה\"ר בכל מאדך זה נעשה אתעדל\"ע בעצמי' הנפש<sup data-n=\"3658\">486</sup> אוא\"ס ב\"ה [ממש] ג\"כ באותו אופן ומדריגה, והוא בחי' פנימי' ועצמות הרצון הפשוט ותענוג הפשוט שלמעלה מבחי' הגבלת האור בכלי שהוא למעלה מהתחלקות המדות לגמרי כנ\"ל, והיינו בחי' פלא [ה]עליון שמופלא ומובדל מהיות גם מקור לחו\"ב ומדות כ'<sup data-n=\"3659\">487</sup> שנק' פנימי' הכתר בכלל וכנ\"ל בפי' עושין רש\"מ כו' והוא הנק' עילת כל העילות<sup data-n=\"3660\">488</sup> כו', או עילאין על כל עילאין<sup data-n=\"3661\">489</sup> סדכ\"ס דלית מח' תב\"כ להיות בבחי' עצמיות אוא\"ס ב\"ה ממש שאינו נתפס בשום מחשבה (אפי' במח\"ק<sup data-n=\"3662\">490</sup> או ח\"ס<sup data-n=\"3663\">491</sup> שנק' שכל הנעלם כו' מטעם הנ\"ל ברצון הפשוט) רק בהתפעלות העליות<sup data-n=\"3664\">493</sup> שברצון הוא נתפס וכו', [וכמו] בבע\"ת האמיתי' שגדולי' יותר מצד\"ג<sup data-n=\"3665\">494</sup> משום דמשכי [לי'] בחילא יתיר<sup data-n=\"3666\">495</sup> כו', והוא מה שיש בכח כאו\"א",[["3647","475","<b>בינה ליבא</b>: ת\"ז בהקדמה (יז, א)."],["3648","476","<b>ותן בלבינו בינה להבין</b>: ברכת ק\"ש שחרית. ראה גם מאמרי אדה\"א שמות ח\"ב ע' תנז. לקמן פ' תצוה של, ב."],["3649","477","<b>דלב מבין</b>: ברכות סא, א. ראה גם מאמרי אדה\"א שמות ח\"א ע' כ."],["3650","478","<b>והלב רואה</b>: קה\"ר פ\"א טז, א. ראה גם מאמרי אדה\"א שמות ח\"א וח\"ב שם."],["3651","479","<b>עין השכל דבלבא</b>: ראה זהר (רע\"מ) משפטים קטז, ב. הנסמן במאמרי אדה\"א קונטרסים ע' תקפד."],["3652","480","<b>מאד בלי גבול</b>: נסמן לעיל סא, ב."],["3653","481","<b>ומאדך. . מגדר הכלי שלך</b>: ראה לקמן פ' בשלח קמב, ד. מאמרי אדה\"ז תקס\"ב ח\"א ע' קיז וע' קצה. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370179\" data-slug=\"torah-or\" data-id=\"3901370179\">תו\"א מקץ לט, סע\"ג</a> ואילך."],["3654","482","<b>שהתפעלות. . עצמיות הרצון</b>: ראה גם סידור ערב שבת קסב, סע\"ג ואילך."],["3655","483","<b>כי </b>[ניתוסף ע\"פ: גט]<b> הרצון נק' נפש</b>: ראה לקמן פ' בשלח רב, א. תצוה שעח, א. מאמרי אדה\"ז תקס\"ה ח\"א ע' קכו. שע\"ת נג, ב ובהערה 25."],["3656","484","<b>כל עצמותי תאמרנה</b>: תהלים לה, י."],["3657","485","<b>דבמו\"ד כ'</b>: גט: דכתר וחכ'."],["3658","486","<b>הנפש</b>: בד: ליתא."],["3659","487","<b>כ'</b>: ט: כו'."],["3660","488","<b>עילת כל העילות</b>: ראה זהר בראשית כב, ב. פרדס (שער אם הא\"ס הוא הכתר) ש\"ג, פ\"א."],["3661","489","<b>עילאין </b>[בד: עילאה]<b> על כל עילאין</b>: ת\"ז בהקדמה (יז, א)."],["3662","490","<b>במח\"ק</b>: בד: במחשבה הקדומה."],["3663","491","<b>או ח\"ס</b>: גט: וח\"ס. 492) שנק' שכל הנעלם: ראה גם לעיל פ' שמות לג, א. מז, ג. וש\"נ."],["3664","493","<b>העליות</b>: בד: העצמי'."],["3665","494","<b>בבע\"ת. . שגדולי' יותר מצד\"ג</b>: נסמן לעיל מא, א."],["3666","495","<b>דמשכי </b>[לי']<b> בחילא יתיר</b>: נסמן לעיל לז, א."]]],[2300540685,"למסו\"נ על קדה\"ש בפו\"מ ולשוב בתשו' [שלימ'] עד כלות הנפש ממש כראב\"ד<sup data-n=\"3667\">496</sup> שזהו ענין אה\"ר דכל מאדך הנ\"ל, [וד\"ל].\n<b>ומעתה</b> י\"ל מהו<sup data-n=\"3668\">497</sup> הוא אהרן ומשה מהו בחי' משה שאחר אהרן שנק' שודמ\"ט<sup data-n=\"3669\">498</sup> כנ\"ל, הנה סדר הפסוקי' בק\"ש אחר ואהבת אומר והיו הדברים האלה כו' ודברת בם כו' והיינו בחי' משה כמ\"ש תורה צוה לנו משה והוא בחי' השוב שאחר בחי' הרצוא דואהבת שע\"י אהרן שודמ\"ט. וי\"ל תחלה פי' תיבת שם משה שהוא<sup data-n=\"3670\">499</sup> מורה על עצם מדריגתו בבחי' שוב דמצות ת\"ת כמו שפי' שם אהרן מורה על בחי' העלאה באה\"ר בבחי' רצוא כנ\"ל, דהנה הטעם שנק' משה מבואר לפי שמן המים משיתיהו<sup data-n=\"3671\">500</sup> וא\"כ תי' זה<sup data-n=\"3672\">501</sup> היינו לשון משוי<sup data-n=\"3673\">502</sup> והוא שנמשך מן המים כו', והענין הוא דבחי' המים הללו היינו בחי' מים עליונים דחכ' עצמה<sup data-n=\"3674\">503</sup> <span data-k=\"pg\">קטז</span> ּ דוקא וכמ\"ש במאמר<sup data-n=\"3675\">504</sup> יהי רקיע בתוך המים<sup data-n=\"3676\">505</sup> כו', ומים עליונים שמעל לרקיע היינו בחי' חכ\"ע שהוא בחי' חכ' שבתורה הקדומה<sup data-n=\"3677\">506</sup> שקדמה לעולם<sup data-n=\"3678\">507</sup> הנאצל<sup data-n=\"3679\">508</sup> והנברא וכמ\"ש בתו' ואהי' אצלו אמון<sup data-n=\"3680\">509</sup> וכו' ונק' משל הקדמוני<sup data-n=\"3681\">510</sup> קדמונו ש\"ע<sup data-n=\"3682\">511</sup> כו' והוא בחי' עצמי' חכמתו ית' הכלולה בעצמי' אוא\"ס<sup data-n=\"3683\">512</sup> ב\"ה דלתבונתו אין מספר<sup data-n=\"3684\">513</sup> כלל, ו[מ]בחי' חכ' [עילאה] זו נמשך מקור שרש נשמתו של משה למטה כמ\"ש מן המים משיתיהו מבחי' מים עליונים דח\"ע זו<sup data-n=\"3685\">514</sup> ליתן תו'<sup data-n=\"3686\">515</sup> [לישראל] למטה<sup data-n=\"3687\">516</sup> ע\"י דוקא, והוא התו' הנגלית לנו לשמור ולעשות בעה\"ד טו\"ר ולהבדיל בין טו\"ר בסו\"מ בשס\"ה ל\"ת וע\"ט ברמ\"ח<sup data-n=\"3688\">517</sup> מ\"ע כו' ונק' תו' שלמטה שיצא מתו' שלמעלה כידוע (ולזה הטעם אמרו<sup data-n=\"3689\">518</sup> ג\"כ בשם משה [כמו] מה שמו<sup data-n=\"3690\">519</sup> ומה שם בנו<sup data-n=\"3691\">520</sup> מ\"ה שמו בחי' מ\"ה דחכ' שבתו' הקדומה מה שם בנו כשנמשך למטה). אך הנה לפ\"ז הי' ראוי שיקרא שמו משוי ולא משה מאחר שעל שם יציאתו מן שרשו [ב]חכ' עילאה למטה נק' משה כי ממים עליונים [הללו] נמשך למטה הרי כבר נמשך משם כי אמר מן המים משיתיהו שהוא משוי ונמשך כבר מן המים עליונים כו' ולמה נק' שמו משה<sup data-n=\"3692\">521</sup> בחולם המ\"ם שהוא מורה לשון תמידות כי כל חולם מורה לשון הוה",[["3667","496","<b>כראב\"ד</b>: נסמן לעיל מא, א."],["3668","497","<b>מהו</b>: בד: מ\"ש."],["3669","498","<b>שודמ\"ט</b>: בד: שושבינא דמלכא."],["3670","499","<b>אומר. . האלה. . בחי'. . שהוא</b>: ניתוסף ע\"פ: גט."],["3671","500","<b>שמן המים משיתיהו</b>: שמות ב, י. ראה גם הנסמן לעיל לה, ד."],["3672","501","<b>תי' זה</b>: ט: תיבה זו דמשה."],["3673","502","<b>דמשה היינו לשון משוי</b>: ראה אבן עזרא־ תוספות השלם שמות ב, י."],["3674","503","<b>דחכ' עצמה</b>: בד: דח\"ע."],["3675","504","<b>במאמר</b>: בד: במ\"א ע\"פ."],["3676","505","<b>יהי רקיע בתוך המים</b>: בראשית א, ו. ראה גם לעיל לה, סע\"ד ואילך ובהנסמן לשם."],["3677","506","<b>שבתורה הקדומה</b>: נסמן לעיל ב, ד."],["3678","507","<b>שבתורה. . שקדמה לעולם</b>: פסחים נד, א."],["3679","508","<b>שקדמה לעולם הנאצל</b>: ראה מאמרי אדה\"ז תקס\"ז ע' ריג. שע\"ת יב, ב. קלד, ב. מאמרי אדה\"א דברים ח\"ד ע' א'קעט. ע' א'תסט. לקמן פ' בא צה, ד. בשלח ריא, א. תצוה שלא, ד."],["3680","509","<b>ואהי' אצלו אמון</b>: משלי ח, ל."],["3681","510","<b>משל הקדמוני</b>: נסמן לעיל ח, ב."],["3682","511","<b>קדמונו ש\"ע</b>: לשון ב\"ר פל\"ח, ז. זהר לך פד, א."],["3683","512","<b>אוא\"ס</b>: בד: א\"ס."],["3684","513","<b>דלתבונתו אין מספר</b>: תהלים קמז, ה."],["3685","514","<b>זו</b>: בד: ליתא."],["3686","515","<b>תו'</b>: בתו\"ח באים גם כאן התיבות: שלמטה. . שלמעלה שבסמוך בשו\"ה ל\"ת."],["3687","516","<b>למטה</b>: ניתוסף ע\"פ: ט."],["3688","517","<b>בשס\"ה. . ברמ\"ח</b>: מכות כג, סע\"ב."],["3689","518","<b>אמרו</b>: ט: נק'."],["3690","519","<b>משה. . מה שמו</b>: נסמן לעיל פ' שמות מג, ד."],["3691","520","<b>מה שמו ומה שם בנו</b>: משלי ל, ד."],["3692","521","<b>כי. . משה</b>: ט: שהרי. . ניתוסף ע\"פ: ט."]]],[2300540697,"דהיינו שהוא ממשיך בתמידות ממים עליונים ולא שכבר נמשך [(ולא שנמשך בתמידות] אלא הוא ממשיך בתמידות מח\"ע שהמ\"ם דמשה מורה לשון מפעיל ולא לשון נפעל). אך הענין לפי שבאמת הגם שכבר נמשך מח\"ע שנק' מ\"ע הרי הוא הממשיך ומביא שפע מבחי' ח\"ע דמח' הקדומה שנק' ים החכ' הקדומה, כי הלא ידוע מ\"ש בזהר דאורייתא מחע\"נ<sup data-n=\"3693\">522</sup> פי' מחכ' [עילאה] הקדומה הנ\"ל יצא התו' רק בבחי' הארה [אחת] בעלמא כענין מה שאמר נחש\"מ תורה<sup data-n=\"3694\">523</sup> שאינו רק כמו בחי' נובלות מח\"ע הקדומה והוא כמו השואב בכד קטן מים הגדול כך כ\"ד ספרי' דאוריי' אינו רק כמו כד א' [הנשאב] מים הגדול, וזה שנא' ברבקה ותרד העינה מעיין דח\"ע ותמלא כד\"ה ותע\"ל<sup data-n=\"3695\">524</sup> וכמ\"ש במ\"א וד\"ל. ואמנם מי הוא הממוצע הממשיך [ו]מביא אור שפע זאת מח\"ע למטה זהו משה שהוא הממשיך ושואב מים החכ' הקדומה הנ\"ל להיות בא בגילוי אור דתו' שלמטה שלנו, וזש\"א תו' צוה לנו משה<sup data-n=\"3696\">*525</sup> כו' (ועד\"ז א' בס' הבהיר דדהע\"ה הי' מחבר תו' שלמטה בתו' שלמעלה<sup data-n=\"3697\">525</sup> ומשה הוא המחבר תו' שלמעלה בתו' שלמטה וראי' ממ\"ת דכתי' משה ידבר והאלקי' יעננו בקול הרי עצמות חכ' ית' באנכי ולא יהי' לך שמפי הגבורה שמע[נ]ו<sup data-n=\"3698\">526</sup> גם זה ע\"י משה<sup data-n=\"3699\">*527</sup> שהאיר והמשיך מפנימי' ועצמי' חכ' עילאה לגילוי אור בהתלבשות בדברים גשמיי' כו'). וזהו [מפני] שנק' משה ע\"ש שמן המים עליונים משיתיהו כי שרש נשמתו משם הוא ע\"כ ביציאתו משם למטה ביכולתו להיות דולה וממשיך מח\"ע בתמידות ולכך נק' משה בחולם המ\"ם כו' (וזש\"א וגם דלה דלה<sup data-n=\"3700\">527</sup> [לנו] וישק את הצאן שהוא ג\"כ מורה ענין התמידות שעולה<sup data-n=\"3701\">528</sup> ומשקה תמיד ממ\"ע להשקות את הצאן מטעם הנ\"ל, או שכוונתו ב\"פ<sup data-n=\"3702\">529</sup> דלה על תושב\"כ ותושבע\"פ דדלי' הא' הוא ענין הגבהה מלמטה למעלה שזהו ענין העלאו' הבירורי' דרפ\"ח שנפלו למטה והן בחי' מ\"ת כידוע, והדלי' הב'<sup data-n=\"3703\">530</sup> הוא הבירור דבחכ' דוקא אתברירו<sup data-n=\"3704\">531</sup> וזה הכח והעוז לא ניתנה רק למשה לכך אמר תורה צוה לנו משה דקאי בתושבע\"פ <span data-k=\"pg\">234</span> ּ וזהו דל\"ה דל\"ה לנו ב' פעמים וד\"ל) (וזהו וישק את הצאן [ד]כמו שבפנימי' העולמות נמשך מפנימי' ח\"ע וח\"ת לכל הנשמות כמו בג\"ע דכתי' ונהר יוצא מעדן להשקות<sup data-n=\"3705\">532</sup> כו', כך בחיצוני' העולמות מקבלים כל השפע ע\"י החכ' דתו' הבא בגילוי בתו' שלמטה שהוא תושב\"כ ותושבע\"פ כו' כמ\"ש אם לא בריתי<sup data-n=\"3706\">533</sup> כו').",[["3693","522","<b>דאורייתא מחע\"נ</b>: נסמן לעיל פ' שמות יא, ב."],["3694","523","<b>נחש\"מ תורה</b>: ב\"ר פי\"ז, ה. פמ\"ד, יז."],["3695","524","<b>ותרד העינה. . ותמלא כד\"ה ותע\"ל</b>: חיי שרה כד, טז. ראה ת\"ז תכ\"א (מו, ב). ביאוה\"ז וישב כה, א. מאמרי אדה\"א דברים ח\"א ע' רכו. וש\"נ. שמות ח\"א ע' ק. וש\"נ. ח\"ב ע' שצו."],["3696","*525","<b>הממוצע. . משה</b>: ראה גם לקמן פ' תצוה שכג, ג. וש\"נ."],["3697","525","<b>בס' הבהיר דדהע\"ה. . בתו' שלמעלה</b>: ראה שם (סנ\"ח) סקצ\"ו. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תשפג. ח\"ד ע' א'רכא. דרושי חתונה ח\"ב ע' תרכח בשם מדרש."],["3698","526","<b>באנכי. . שמפי הגבורה שמע[נ]ו</b>: מכות כד, א. לעיל סט, א. וש\"נ."],["3699","*527","<b>גם זה ע\"י משה</b>: ראה גם מאמרי אדה\"א במדבר ח\"ב ס\"ע תלד ואילך."],["3700","527","<b>וגם דלה דלה</b>: שמות ב, יט."],["3701","528","<b>שעולה</b>: בד: שדולה."],["3702","529","<b>ב\"פ</b>: ניתוסף ע\"פ: ט."],["3703","530","<b>הא'. . הב'</b>: ניתוסף ע\"פ: ט."],["3704","531","<b>דבחכ'. . אתברירו</b>: נסמן לעיל פ' שמות י, ג."],["3705","532","<b>ונהר. . להשקות</b>: בראשית ב, י."],["3706","533","<b>אם לא בריתי</b>: ירמי' לג, כה."]]],[2300540709,"<b>ובזה</b> יובן מש\"א ה' למשה כאשר מיאן לילך בשליחות לבנ\"י ואמר לא איש דברים אנכי<sup data-n=\"3707\">534</sup> [כו'] כי כ\"פ וכבד ל'<sup data-n=\"3708\">535</sup> כו' ואמר לו ה' מי שם פה לאדם<sup data-n=\"3709\">536</sup> כו' ואנכי אהי' עם פיך<sup data-n=\"3710\">537</sup> כו' וע\"כ זה לא רצה משה ואמר שלח נא ביד תשלח<sup data-n=\"3711\">538</sup> אמר לו ה' הלא אהרן אחיך<sup data-n=\"3712\">539</sup> הלוי ידעתי כי דבר ידבר כו' עד ודיבר הוא לך<sup data-n=\"3713\">540</sup> אל העם ו[הי'] הוא יהי' לך לפה ואתה תהי' לו לאלקים כו', כי הנה ענין דליי' והמשכה זאת ממים עליונים דח\"ע ע\"י משה כנ\"ל הרי הוא למעלה מעלה מן הסדר של [ה]השתל' שא\"א הי' שיבא ע\"י בגילוי בפה בדבור ע\"כ אמר לא איש דברים אנכי כו' כי כבד פה וכ\"ל אנכי וא' ברע\"מ כבד פה תשבע\"פ כ\"ל תושב\"כ<sup data-n=\"3714\">541</sup> כו', להיות ששליחותו הי' לב\"י להמשיך להם האור מן ההעלם לגילוי וידוע שסדר השתל' הוא דוקא בא בבחי' העלם וגילוי, והיינו כמו בחי'<sup data-n=\"3715\">542</sup> אותיות הדבור בפה שנמשך בגילוי מן העלם המדות ומח' ושכל וחכ' שבראש, כמו בהשתל' העולמות<sup data-n=\"3716\">543</sup> דבמע\"ב ביו\"ד מאמרות שבהן<sup data-n=\"3717\">544</sup> נבה\"ע<sup data-n=\"3718\">545</sup> ומלואו, ודאי זה הדבור הוא בא ונמשך מן בחי' ההעלם דמח' ומדות ע\"י ה' מוצאות שבפה שמוציא בגילוי שהוא נק' פה המדבר כו' [ו]כמ\"ש בס\"י וקבען בפה שהוא מקור המוציא לך\"ב אותיות בצירופים שונים והן אחה\"ע<sup data-n=\"3719\">546</sup> מהגרון גיכ\"ק מן החיך כידוע. אבל יש בחי' ומדריגה עליונה [מאד] שלמעלה מבחי' ההשתל' דהעלם וגילוי לגמרי שא\"א לבוא לבחי' משפיע<sup data-n=\"3720\">547</sup> מהעלם לגילוי כלל, והיינו בחי' פנימי' ח\"ע שנבדל [ב]ערך מהיות גם בחי' מקור לחכמה שבראש להיות נמשך בבחי' העלם וגילוי אלא הוא בבחי' אין ממש ונק' פלאות חכ'<sup data-n=\"3721\">548</sup> שמופלא ונעלם בלתי יוכל לבא בגילוי מההעלם. ומ\"ש והחכ' מאין תמצא לבחי' יש היינו רק בחי' חיצוני' הח\"ע שיורד מן ההעלם לגילוי אור כמו עד\"מ המצאות שכל חדש שנגלה במוח החכ' מן העלם ולא<sup data-n=\"3722\">549</sup> למציאות שכל ממש פי'<sup data-n=\"3723\">550</sup> עומק החכמה<sup data-n=\"3724\">551</sup>, אבל בחי' עצם כח המשכיל כמו שהוא ה\"ה נבדל בערך מהיות מקור משפיע להביא שפע שכל מהעלם לגילוי כלל והוא מה שלא יוכל האדם להביא בדבור בפה כלל<sup data-n=\"3725\">552</sup>, דמה שיוכל אדם להביא בגילוי בדבור אינו רק מה שמושכל במוחו בגילוי מההעלם כו' [וכמו] פיה פתחה בחכ'<sup data-n=\"3726\">553</sup> (וכמשי\"ת). וזהו שאמר משה ששרשו מפנימי' ח\"ע כי מן המים משיתיהו כנ\"ל לא איש דברים אנכי כו', וע\"כ כדי להמשיך ח\"ע דתו' שלמעלה לתו' שלמטה א' כבד פה תשבע\"פ כ\"ל תשב\"כ מטעם הנ\"ל וד\"ל, והוא להיותו למעלה ממקור השתל' דהעלם",[["3707","534","<b>לא איש דברים אנכי</b>: שמות ד, י."],["3708","535","<b>וכבד ל'</b>: ניתוסף ע\"פ: ט."],["3709","536","<b>מי שם פה לאדם</b>: שמות שם, יא."],["3710","537","<b>ואנכי אהי' עם פיך</b>: שמות ד, יב."],["3711","538","<b>שלח נא ביד תשלח</b>: שם ד, יג."],["3712","539","<b>הלא אהרן אחיך</b>: שמות שם, יד."],["3713","540","<b>ודיבר הוא לך</b>: שם שם, טז."],["3714","541","<b>כבד פה. . תושב\"כ</b>: נסמן לעיל פ' שמות מז, ד."],["3715","542","<b>בחי'</b>: בד: ליתא."],["3716","543","<b>העולמות</b>: בד: ליתא."],["3717","544","<b>ביו\"ד מאמרות שבהן נבה\"ע</b>: אבות רפ\"ה."],["3718","545","<b>נבה\"ע</b>: בד: נברא כל העולמות [ט: העולם]."],["3719","546","<b>אחה\"ע</b>: נסמן לעיל פ' שמות מז, ב."],["3720","547","<b>לבחי' משפיע</b>: בד: בבחי' ושפע. ט. בבחי' אור ושפע."],["3721","548","<b>פלאות חכ'</b>: נסמן לעיל פ' שמות כא, ב."],["3722","549","<b>ולא</b>: בד: ואי\"ן."],["3723","550","<b>פי'</b>: ב: פלאות. ג: פנימית. ד: פ'."],["3724","551","<b>פי' עומק החכמה</b>: ג: ניתוסף עה\"ג. ט: ליתא. וראה בהערה הבאה."],["3725","552","<b>כלל</b>: ט: ניתוסף: והוא עומק פני' החכ'. וראה הערה שלפנ\"ז."],["3726","553","<b>פיה פתחה בחכ'</b>: משלי לא, כו."]]]]});
